INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她给女儿树立了了一个坚强的榜样。", "corrected_sentence": "她给女儿树立了一个坚强的榜样。", "error_description": "错误：“树立了”后面多出一个“了”，动词后只用一个“了”，应说“树立了一个坚强的榜样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
