INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "建立、确立，使某种形象、风气等成立并被认可。", "primary_collocate": null, "pronunciation": "shù lì", "ipa": "ʂu⁵¹ li⁵¹", "syllable_count": 2, "sentences": [{"text": "他想在公司里树立好形象。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校要树立良好的学习风气。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人要树立正确的人生目标。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店靠好服务树立了自己的名声。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要帮孩子树立学好数学的信心。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位新校长很快就树立了威信。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直想树立一个爱学习的好形象。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有树立正确的观念，才能做出好选择。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把诚信当作原则，树立了好品牌。", "target_word": "树立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就树立过当医生的理想。", "target_word": "树立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "树立了", "label": "体标"}, {"form": "树立过", "label": "体标"}, {"form": "樹立", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "建立、确立形象、风气、观念等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13c58d25-1eb8-4b9e-9181-3173d9fab08e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：听到的是“树立”，指建立、确立某种形象、风气等。"}, {"text": "书吏", "is_correct": false, "explanation": "声调不同：shū 为第一声，shù 为第四声。书吏意思是旧时官府中抄写文书的小吏。"}, {"text": "树篱", "is_correct": false, "explanation": "声调不同：lí 为第二声，lì 为第四声，意思是密植成墙的树木。"}, {"text": "数理", "is_correct": false, "explanation": "声调不同：lǐ 为第三声，lì 为第四声，意思是数学的道理。"}], "explanations": {"树立": "正确：听到的是“树立”，指建立、确立某种形象、风气等。", "书吏": "声调不同：shū 为第一声，shù 为第四声。书吏意思是旧时官府中抄写文书的小吏。", "树篱": "声调不同：lí 为第二声，lì 为第四声，意思是密植成墙的树木。", "数理": "声调不同：lǐ 为第三声，lì 为第四声，意思是数学的道理。"}, "sentence_index": null, "correct_answer": "树立"}, "level_3": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：“树立好形象”指在公司里确立良好的形象。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“想破坏好形象”与前半句“想”所表达的正面愿望相矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "语义：形象不能被吃，“想吃好形象”不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”与“形象”不相配，“洗好形象”不是常见说法。"}], "explanations": {"树立": "正确：“树立好形象”指在公司里确立良好的形象。", "破坏": "语义：“想破坏好形象”与前半句“想”所表达的正面愿望相矛盾。", "吃": "语义：形象不能被吃，“想吃好形象”不通。", "洗": "搭配：“洗”与“形象”不相配，“洗好形象”不是常见说法。"}, "sentence_index": 0, "correct_answer": "树立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他多年树立了丰富的经验。", "explanation": "这里应该用〈积累〉。树立用于形象、风气、榜样，经验要说“积累”。"}, {"text": "这位选手树立了观众的喜爱。", "explanation": "这里应该用〈赢得〉。喜爱是别人给予的，要说“赢得”，“树立”不能用于此。"}, {"text": "他树立了很多真诚的朋友。", "explanation": "这里应该用〈拥有〉。朋友要说“拥有”，“树立”不能用于人际关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：听到的是“树立”，指建立、确立某种形象、风气等。"}, {"text": "熟栗", "is_correct": false, "explanation": "声调不同：shú 为第二声，shù 为第四声。熟栗意思是煮熟或炒熟的栗子。"}, {"text": "属吏", "is_correct": false, "explanation": "声调不同：shǔ 为第三声，shù 为第四声。属吏意思是隶属于官府的下级官吏。"}, {"text": "书立", "is_correct": false, "explanation": "第一音节声调不同：shū 为第一声，shù 为第四声，意思是书挡。"}], "explanations": {"树立": "正确：听到的是“树立”，指建立、确立某种形象、风气等。", "熟栗": "声调不同：shú 为第二声，shù 为第四声。熟栗意思是煮熟或炒熟的栗子。", "属吏": "声调不同：shǔ 为第三声，shù 为第四声。属吏意思是隶属于官府的下级官吏。", "书立": "第一音节声调不同：shū 为第一声，shù 为第四声，意思是书挡。"}, "sentence_index": null, "correct_answer": "树立"}, "level_3": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：“树立一个好形象”指确立良好的形象，与“爱学习”相合。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“想打碎好形象”与句意相反，与“爱学习”的正面形象矛盾。"}, {"text": "投诉", "is_correct": false, "explanation": "搭配：“投诉”的对象是事件或服务，“投诉一个形象”搭配不当。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”多与希望、热情连用，不能与“形象”搭配。"}], "explanations": {"树立": "正确：“树立一个好形象”指确立良好的形象，与“爱学习”相合。", "打碎": "语义：“想打碎好形象”与句意相反，与“爱学习”的正面形象矛盾。", "投诉": "搭配：“投诉”的对象是事件或服务，“投诉一个形象”搭配不当。", "点燃": "搭配：“点燃”多与希望、热情连用，不能与“形象”搭配。"}, "sentence_index": 6, "correct_answer": "树立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她掌握了一门外语，还树立了它。", "explanation": "这里“树立”用错了。外语属于技能，应当用“学会”，“树立”只用于形象、风气或榜样，不能用于技能。"}, {"text": "他发表了一篇论文，还树立了它。", "explanation": "这里“树立”用错了。论文是文章，应当用“撰写”，“树立”只用于形象、风气或榜样，不能用于文章。"}, {"text": "公司开辟了新市场，又树立了它。", "explanation": "这里“树立”用错了。市场要说“拓展”，“树立”只用于形象、风气或榜样，不能用于市场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直想树立了良好的形象。", "corrected_sentence": "他一直想树立良好的形象。", "error_description": "错误：“想”表示意愿，后面的“树立”不能带“了”，应说“想树立”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他树立得良好的形象，大家都很信任他。", "corrected_sentence": "他树立了良好的形象，大家都很信任他。", "error_description": "错误：动词“树立”后带宾语表示完成时要用“了”，不能用补语标记“得”，应说“树立了良好的形象”，不能说“树立得良好的形象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
