INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "受到很多人欢迎和关注的。", "primary_collocate": null, "pronunciation": "rè mén", "ipa": "ʐɤ˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "这个话题很热门。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "热门景点人特别多。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个词最近变得很热门。", "target_word": "热门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在最热门的专业是什么？", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暑假里，热门的旅游城市到处是人。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他选了一个不太热门的工作。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热门的比赛，网上有很多人讨论。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为很热门，这家饭馆要排队。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写的文章成了网上最热门的话题。", "target_word": "热门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个热门问题，记者已经问过很多次了。", "target_word": "热门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱門", "label": "繁体"}], "register": "中性", "sense_fingerprint": "受很多人欢迎和关注的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88937676-1732-4c8a-9ac7-4b6520113a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热门", "is_correct": true, "explanation": "正确：「热门」指受很多人欢迎和关注，用来形容这个话题很受关注。"}, {"text": "咸", "is_correct": false, "explanation": "语义：「咸」指味道，不能用来形容话题。"}, {"text": "饱", "is_correct": false, "explanation": "语义：「饱」指吃得满足，不能用来形容话题。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：「瘦」形容人或动物的身材，不能用来形容话题。"}], "explanations": {"热门": "正确：「热门」指受很多人欢迎和关注，用来形容这个话题很受关注。", "咸": "语义：「咸」指味道，不能用来形容话题。", "饱": "语义：「饱」指吃得满足，不能用来形容话题。", "瘦": "体貌：「瘦」形容人或动物的身材，不能用来形容话题。"}, "sentence_index": 0, "correct_answer": "热门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗面太热门了，等凉一点再吃。", "explanation": "「热门」指受很多人欢迎和关注，不能用来形容食物的温度，这句把它当成了「热」的意思。"}, {"text": "这杯奶茶很热门，你先放凉再喝。", "explanation": "「热门」形容受欢迎的程度，不能用来说奶茶的温度，这句误用了它的意思。"}, {"text": "这间屋子很热门，我们开窗吧。", "explanation": "「热门」指受欢迎、受关注，不能用来形容屋子的温度，这句误用了它的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热门", "is_correct": true, "explanation": "正确：「热门」指受很多人欢迎和关注，用来形容这场比赛受到大家讨论。"}, {"text": "饿", "is_correct": false, "explanation": "搭配：「饿」只用于人或动物想吃东西，不能用来修饰「比赛」。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：「寂静」指没有声音，与后面「网上有很多人讨论」矛盾。"}, {"text": "辣", "is_correct": false, "explanation": "语义：「辣」指味道，不能用来修饰比赛。"}], "explanations": {"热门": "正确：「热门」指受很多人欢迎和关注，用来形容这场比赛受到大家讨论。", "饿": "搭配：「饿」只用于人或动物想吃东西，不能用来修饰「比赛」。", "寂静": "语义：「寂静」指没有声音，与后面「网上有很多人讨论」矛盾。", "辣": "语义：「辣」指味道，不能用来修饰比赛。"}, "sentence_index": 6, "correct_answer": "热门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员的态度很热门，客人都很满意。", "explanation": "这里应该用〈热情〉。「热门」指受欢迎，不能用来形容态度。"}, {"text": "正午的太阳很热门，大家都躲在树下。", "explanation": "这里应该用〈炎热〉。「热门」指受欢迎，不能用来形容太阳的热度。"}, {"text": "大家为他的演讲鼓起了热门的掌声。", "explanation": "这里应该用〈热烈〉。「热门」指受欢迎，不能用来形容掌声的热烈程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
