INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "瓦是盖在屋顶上的一片一片的东西。", "primary_collocate": null, "pronunciation": "wǎ", "ipa": "wa˨˩˦", "syllable_count": 1, "sentences": [{"text": "屋顶上有很多一片一片的瓦。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一片瓦从屋顶上掉下来了。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨时，雨水顺着瓦流下来。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的瓦是灰色的。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风把屋顶上的瓦吹掉了。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在屋顶的瓦上走来走去。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爬上屋顶，检查有没有破的瓦。", "target_word": "瓦", "complexity_tier": "T3", "furigana": "tā pá shàng wū dǐng, jiǎn chá yǒu méi yǒu pò de wǎ.", "sentence_source": "generated"}, {"text": "那片瓦碎了，屋里会漏雨。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们捡起地上的一片碎瓦。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的瓦上长了绿色的草。", "target_word": "瓦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "瓦片", "label": "复合词"}], "register": "通用", "sense_fingerprint": "瓦：屋顶上一片一片盖着的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db54c0a-ae30-43eb-977b-2b2ba8aec6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94827, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瓦", "is_correct": true, "explanation": "正确：瓦（wǎ），屋顶上一片一片盖着的东西。"}, {"text": "挖", "is_correct": false, "explanation": "wā（第一声）与 wǎ（第三声）声调不同，意思是挖。"}, {"text": "娃", "is_correct": false, "explanation": "wá（第二声）与 wǎ（第三声）声调不同，意思是娃娃。"}, {"text": "袜", "is_correct": false, "explanation": "wà（第四声）与 wǎ（第三声）声调不同，意思是袜子。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 比 wǎ 多一个韵尾 n，意思是碗。"}], "explanations": {"瓦": "正确：瓦（wǎ），屋顶上一片一片盖着的东西。", "挖": "wā（第一声）与 wǎ（第三声）声调不同，意思是挖。", "娃": "wá（第二声）与 wǎ（第三声）声调不同，意思是娃娃。", "袜": "wà（第四声）与 wǎ（第三声）声调不同，意思是袜子。", "碗": "wǎn 比 wǎ 多一个韵尾 n，意思是碗。"}, "sentence_index": null, "correct_answer": "瓦"}, "level_3": {"options": [{"text": "瓦", "is_correct": true, "explanation": "瓦：屋顶上一片一片盖着的东西，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：“水”是液体，不能是屋顶上一片片的东西。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”用“扇”计量，不能说“一片一片的窗户”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”指整座建筑，不是盖在屋顶上的一片片材料。"}], "explanations": {"瓦": "瓦：屋顶上一片一片盖着的东西，符合句意。", "水": "语义：“水”是液体，不能是屋顶上一片片的东西。", "窗户": "搭配：“窗户”用“扇”计量，不能说“一片一片的窗户”。", "房子": "语义：“房子”指整座建筑，不是盖在屋顶上的一片片材料。"}, "sentence_index": 0, "correct_answer": "瓦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小心地把一片瓦装进了窗框。", "explanation": "这里应该用〈玻璃〉。瓦是盖屋顶的材料，装窗框要用玻璃。"}, {"text": "他用一片瓦擦了擦眼镜。", "explanation": "这里应该用〈布〉。瓦是盖屋顶的材料，擦眼镜要用布。"}, {"text": "他用一片瓦写了一封信。", "explanation": "这里应该用〈纸〉。瓦是盖屋顶的材料，写信要用纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94827, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瓦", "is_correct": true, "explanation": "正确：瓦（wǎ），屋顶上一片一片盖着的东西。"}, {"text": "蛙", "is_correct": false, "explanation": "wā（第一声）与 wǎ（第三声）声调不同，意思是青蛙。"}, {"text": "我", "is_correct": false, "explanation": "wǒ（第三声）与 wǎ（第三声）韵母不同（o 与 a），意思是我。"}, {"text": "网", "is_correct": false, "explanation": "wǎng（第三声）比 wǎ 多一个韵尾 ng，意思是网。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wǎ（第三声）韵母不同（u 与 a），意思是数字五。"}], "explanations": {"瓦": "正确：瓦（wǎ），屋顶上一片一片盖着的东西。", "蛙": "wā（第一声）与 wǎ（第三声）声调不同，意思是青蛙。", "我": "wǒ（第三声）与 wǎ（第三声）韵母不同（o 与 a），意思是我。", "网": "wǎng（第三声）比 wǎ 多一个韵尾 ng，意思是网。", "五": "wǔ（第三声）与 wǎ（第三声）韵母不同（u 与 a），意思是数字五。"}, "sentence_index": null, "correct_answer": "瓦"}, "level_3": {"options": [{"text": "瓦", "is_correct": true, "explanation": "瓦：屋顶上盖着的东西，破了会漏雨，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是坐具，与屋顶、漏雨无关。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”是插花的器皿，不能是屋顶上的东西。"}, {"text": "消息", "is_correct": false, "explanation": "搭配：“破”不能修饰“消息”，不说“破的消息”。"}], "explanations": {"瓦": "瓦：屋顶上盖着的东西，破了会漏雨，符合句意。", "椅子": "语义：“椅子”是坐具，与屋顶、漏雨无关。", "花瓶": "语义：“花瓶”是插花的器皿，不能是屋顶上的东西。", "消息": "搭配：“破”不能修饰“消息”，不说“破的消息”。"}, "sentence_index": 6, "correct_answer": "瓦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用一片片瓦包了饺子。", "explanation": "这里应该用〈饺子皮〉。瓦是盖屋顶的材料，包饺子要用饺子皮。"}, {"text": "这张桌子是用瓦做的。", "explanation": "这里应该用〈木头〉。瓦是盖屋顶的材料，做桌子要用木头。"}, {"text": "他一页一页地读这片瓦。", "explanation": "这里应该用〈书〉。瓦不能一页一页地读，要说书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
