INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨晚大风把屋顶上的瓦吹掉了一只。", "corrected_sentence": "昨晚大风把屋顶上的瓦吹掉了一片。", "error_description": "量词错误：“瓦”不用“只”计量，应用“片”（或“块”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
