INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "恶性肿瘤引起的疾病，细胞不正常增生并可扩散。", "primary_collocate": null, "pronunciation": "ái zhèng", "ipa": "ai˧˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "癌症是细胞不正常生长引起的病。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "医院用药物和手术治疗癌症。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "癌症细胞会扩散到身体其他地方。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "这种癌症在老年人中比较常见。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "每年体检可以早发现癌症。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "医生说他的癌症已经扩散了。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "研究人员正在寻找治疗癌症的新方法。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "吸烟会增加得癌症的危险。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "早期癌症的治愈率比较高。", "target_word": "癌症", "sentence_source": "generated"}, {"text": "这家医院专门治疗儿童癌症。", "target_word": "癌症", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "癌症患者", "label": "复合"}], "register": "中性", "sense_fingerprint": "医学说法：恶性肿瘤，细胞增生并扩散", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d36763-8831-45a5-9b61-1e9a276bb895') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "癌症", "is_correct": true, "explanation": "正确。癌症是细胞不正常生长引起的病，与句中的定义相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒由病毒引起，不是细胞不正常生长引起的病。"}, {"text": "骨折", "is_correct": false, "explanation": "语义：骨折是骨头断裂的外伤，不是细胞增生引起的病。"}, {"text": "白头发", "is_correct": false, "explanation": "体貌：白头发是外貌特征，不是细胞不正常生长引起的病。"}], "explanations": {"癌症": "正确。癌症是细胞不正常生长引起的病，与句中的定义相符。", "感冒": "语义：感冒由病毒引起，不是细胞不正常生长引起的病。", "骨折": "语义：骨折是骨头断裂的外伤，不是细胞增生引起的病。", "白头发": "体貌：白头发是外貌特征，不是细胞不正常生长引起的病。"}, "sentence_index": 0, "correct_answer": "癌症"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说这个癌症是良性的，不用担心。", "explanation": "这里应该用〈肿瘤〉。癌症指恶性肿瘤，不能说“良性”；良性的应说肿瘤。"}, {"text": "体检后，医生说他身上长了一块癌症。", "explanation": "这里应该用〈种〉。癌症作为病名，量词用“种”，不用“块”。"}, {"text": "他的癌症需要用夹板固定。", "explanation": "这里应该用〈骨折〉。夹板固定用于骨折，癌症不是骨头的损伤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "癌症", "is_correct": true, "explanation": "正确。“治疗癌症的新方法”指针对这种恶性疾病的治疗方法。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是病，“治疗玩具”说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是病，不能作为“治疗”的对象。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“治疗”一般用于疾病，感情不说“治疗”。"}], "explanations": {"癌症": "正确。“治疗癌症的新方法”指针对这种恶性疾病的治疗方法。", "玩具": "语义：玩具不是病，“治疗玩具”说不通。", "汽车": "语义：汽车不是病，不能作为“治疗”的对象。", "感情": "搭配：“治疗”一般用于疾病，感情不说“治疗”。"}, "sentence_index": 6, "correct_answer": "癌症"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的癌症需要戴眼镜。", "explanation": "这里应该用〈近视〉。戴眼镜矫正的是近视，癌症不能用眼镜处理。"}, {"text": "医生说他的癌症需要做心脏搭桥。", "explanation": "这里应该用〈冠心病〉。心脏搭桥用于冠心病，癌症不能用这种手术治疗。"}, {"text": "他的癌症需要坐浴。", "explanation": "这里应该用〈痔疮〉。坐浴治疗的是痔疮，癌症不能用坐浴治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈的同事得了一只癌症，现在治疗得很好。", "corrected_sentence": "我妈妈的同事得了一种癌症，现在治疗得很好。", "error_description": "量词错误：“癌症”是病名，量词应用“种”，“只”用于动物，不能用于病。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅前年得了一癌症，现在已经康复了。", "corrected_sentence": "我舅舅前年得了一种癌症，现在已经康复了。", "error_description": "数量词缺失：名词“癌症”前需要量词，应说“一种癌症”，不能直接用“一”加名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
