INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会环境是人们生活的周围，有人有规矩。", "primary_collocate": null, "pronunciation": "shè huì huán jìng", "ipa": "ʂɤ˥˩ xweɪ˥˩ xwan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "在安全的社会环境里，人们可以放心出门。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到新国家后，我慢慢熟悉了那里的社会环境。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会环境不好，大家都不敢相信陌生人。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学校也是社会环境的一部分。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母希望给孩子一个友好的社会环境。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的社会环境很有规矩，人人守法。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在复杂的社会环境中长大。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会环境越来越开放了。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会环境不同，人们的生活习惯也不同。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要改善社会环境，大家都要遵守规则。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "社會環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们生活的周围，有人也有规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a252ca3-929a-4eff-b85c-7b311aaea147') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衣柜", "is_correct": false, "explanation": "语义：人不能在衣柜里放心出门，这句话说不通。"}, {"text": "社会环境", "is_correct": true, "explanation": "社会环境指人们生活的周围，安全的社会环境让人可以放心出门。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“里”前要接场所名词，“年纪”不是场所，不能说“在……里”。"}, {"text": "信封", "is_correct": false, "explanation": "语义：人不能在信封里出门。"}], "explanations": {"衣柜": "语义：人不能在衣柜里放心出门，这句话说不通。", "社会环境": "社会环境指人们生活的周围，安全的社会环境让人可以放心出门。", "年纪": "搭配：“里”前要接场所名词，“年纪”不是场所，不能说“在……里”。", "信封": "语义：人不能在信封里出门。"}, "sentence_index": 0, "correct_answer": "社会环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的社会环境很潮湿，靠近海边。", "explanation": "这里应该用〈地理环境〉。社会环境指人际和社会条件，城市的湿度和位置要说地理环境。"}, {"text": "森林的社会环境保护得很好，树木长得很高。", "explanation": "这里应该用〈自然环境〉。社会环境不指森林，树木和山林要说自然环境。"}, {"text": "这片沙漠的社会环境很炎热，白天能把人晒伤。", "explanation": "这里应该用〈气候〉。社会环境指人际和社会条件，沙漠的冷热要说气候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字", "is_correct": false, "explanation": "语义：人不能在数字里长大，这句话说不通。"}, {"text": "社会环境", "is_correct": true, "explanation": "社会环境是人们生活的周围，他在复杂的社会环境中长大，说得通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：人不能在颜色里长大。"}, {"text": "样貌", "is_correct": false, "explanation": "体貌：“样貌”指人的外貌，不是人生活的场所。"}], "explanations": {"数字": "语义：人不能在数字里长大，这句话说不通。", "社会环境": "社会环境是人们生活的周围，他在复杂的社会环境中长大，说得通。", "颜色": "语义：人不能在颜色里长大。", "样貌": "体貌：“样貌”指人的外貌，不是人生活的场所。"}, "sentence_index": 6, "correct_answer": "社会环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子的社会环境很偏远，只有一条土路。", "explanation": "这里应该用〈交通环境〉。社会环境不指地理位置，村里的道路和交通要说交通环境。"}, {"text": "这间教室的社会环境很亮，窗户很大。", "explanation": "这里应该用〈采光条件〉。社会环境不指窗户，教室的光线要说采光条件。"}, {"text": "这间屋子的社会环境很潮湿，空气不流通。", "explanation": "这里应该用〈通风条件〉。社会环境不指空气，屋里的空气流动要说通风条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在安全地社会环境中，孩子们可以放心玩耍。", "corrected_sentence": "在安全的社会环境中，孩子们可以放心玩耍。", "error_description": "“安全”修饰名词“社会环境”，应用“的”，不能用“地”（“地”用于修饰动词）。应改为“安全的社会环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "要制造社会环境，我们都要守规矩。", "corrected_sentence": "要营造社会环境，我们都要守规矩。", "error_description": "“制造”多用于物品，“社会环境”应与“营造”搭配。应改为“营造”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
