INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94838, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类生活所处的社会条件和氛围的总和。", "primary_collocate": null, "pronunciation": "shè huì huán jìng", "ipa": "ʂɤ˥˩ xweɪ˥˩ xwan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "好的社会环境能让孩子健康长大。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会环境变了，人们的想法也变了。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的社会环境很安定。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很在意孩子成长的社会环境。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的社会环境需要大家一起努力。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家的社会环境差别很大。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会环境会影响一个人的性格。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人刚工作，要先适应社会环境。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想为企业创造好的社会环境。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的社会环境对女性并不公平。", "target_word": "社会环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "社會環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人类生活所处的社会条件和氛围的总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a252ca3-929a-4eff-b85c-7b311aaea147') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能让孩子健康长大，这句话说不通。"}, {"text": "社会环境", "is_correct": true, "explanation": "社会环境指人所处的社会条件和氛围，好的社会环境能让孩子健康长大。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不是让孩子长大的条件。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不能让孩子健康长大。"}], "explanations": {"颜色": "语义：颜色不能让孩子健康长大，这句话说不通。", "社会环境": "社会环境指人所处的社会条件和氛围，好的社会环境能让孩子健康长大。", "身材": "体貌：“身材”指人的体形，不是让孩子长大的条件。", "家具": "语义：家具不能让孩子健康长大。"}, "sentence_index": 0, "correct_answer": "社会环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的社会环境很清澈，鱼很多。", "explanation": "这里应该用〈生态环境〉。社会环境指人际关系和社会条件，河里的水和鱼要说生态环境。"}, {"text": "这家工厂的社会环境很烫，机器一开就热得难受。", "explanation": "这里应该用〈工作环境〉。社会环境不指温度，工厂的劳动条件要说工作环境。"}, {"text": "这家餐厅的社会环境很油，桌面黏糊糊的。", "explanation": "这里应该用〈卫生环境〉。社会环境不指油污，店里的整洁要说卫生环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "字数", "is_correct": false, "explanation": "语义：字数是文字的多少，不会影响一个人的性格。"}, {"text": "社会环境", "is_correct": true, "explanation": "社会环境指社会的条件和氛围，会影响一个人的性格。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体不会影响一个人的性格。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”指面部气色，不是影响性格的环境。"}], "explanations": {"字数": "语义：字数是文字的多少，不会影响一个人的性格。", "社会环境": "社会环境指社会的条件和氛围，会影响一个人的性格。", "字体": "语义：字体不会影响一个人的性格。", "脸色": "体貌：“脸色”指面部气色，不是影响性格的环境。"}, "sentence_index": 6, "correct_answer": "社会环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房子的社会环境很干燥，阳光也好。", "explanation": "这里应该用〈居住环境〉。社会环境指社会条件和氛围，房间的干湿和采光要说居住环境。"}, {"text": "这座城市的社会环境很湿润，夏天很凉快。", "explanation": "这里应该用〈气候〉。社会环境不说湿润，天气的冷暖和干湿要说气候。"}, {"text": "这条湖的社会环境漂着垃圾，岸边的草也枯了。", "explanation": "这里应该用〈水质〉。社会环境不指水中的杂物，湖水干净不干净要说水质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社会环境长了，人们的生活也变了。", "corrected_sentence": "社会环境变了，人们的生活也变了。", "error_description": "“长”用于植物或人的身体，不能用于“社会环境”。“社会环境”应与“变”搭配，应改为“变了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刚进公司的人，要先适应这只社会环境。", "corrected_sentence": "刚进公司的人，要先适应这个社会环境。", "error_description": "量词用错。“社会环境”的量词应用“个”，“只”多用于动物等，不能用于“社会环境”，应说“这个社会环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
