INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94847, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "第二天是今天过去后的下一天。", "primary_collocate": null, "pronunciation": "dì èr tiān", "ipa": "ti˥˩ aɚ˥˩ tʰjɛn˥", "syllable_count": 3, "sentences": [{"text": "今天先睡吧，第二天再做。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天先休息，第二天再说吧。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，第二天可能会晴。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天你先回家，第二天再来。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚早点睡，第二天要早起。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业，第二天要交。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不去，第二天一定去。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天先买票，第二天坐火车走。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太晚了，第二天我们再聊。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天写完信，第二天寄出去。", "target_word": "第二天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "今天过去后的下一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a9e6c79-9a64-4e29-86b7-f0772555b1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94847, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "第二天", "is_correct": true, "explanation": "正确答案：第二天，指今天过去后的下一天。"}, {"text": "第二班", "is_correct": false, "explanation": "bān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二班」。"}, {"text": "第二篇", "is_correct": false, "explanation": "piān（第一声）与 tiān（第一声）声母不同（p 与 t），意思是「第二篇」。"}, {"text": "第二千", "is_correct": false, "explanation": "qiān（第一声）与 tiān（第一声）声母不同（q 与 t），意思是「第二千」，较少用。"}], "explanations": {"第二天": "正确答案：第二天，指今天过去后的下一天。", "第二班": "bān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二班」。", "第二篇": "piān（第一声）与 tiān（第一声）声母不同（p 与 t），意思是「第二篇」。", "第二千": "qiān（第一声）与 tiān（第一声）声母不同（q 与 t），意思是「第二千」，较少用。"}, "sentence_index": null, "correct_answer": "第二天"}, "level_3": {"options": [{"text": "第二天", "is_correct": true, "explanation": "正确：第二天指今天过去后的下一天，与「再做」的时间安排一致。"}, {"text": "前天", "is_correct": false, "explanation": "语义：前天已经过去，不能作为「今天先睡」之后再做的时间。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：昨天在今天之前，不能作为「今天先睡」之后再做的时间。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：「先睡吧」与「去年再做」的时间不衔接，不能搭配。"}], "explanations": {"第二天": "正确：第二天指今天过去后的下一天，与「再做」的时间安排一致。", "前天": "语义：前天已经过去，不能作为「今天先睡」之后再做的时间。", "昨天": "语义：昨天在今天之前，不能作为「今天先睡」之后再做的时间。", "去年": "搭配：「先睡吧」与「去年再做」的时间不衔接，不能搭配。"}, "sentence_index": 0, "correct_answer": "第二天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事发生在昨天之前的第二天，我才知道。", "explanation": "这里指的是昨天之前的第二天，即大前天，应该用〈大前天〉。第二天只指某一天之后紧接着的那一天，不能指之前的日子。"}, {"text": "这次旅行我带了三个第二天。", "explanation": "这里把时间词「第二天」当成了可数的物品，应该用〈背包〉等具体物品名词；时间词不能用量词「个」计数。"}, {"text": "这门课第二天上，却每天都上。", "explanation": "这里「第二天」指一个具体的日子，与「每天都上」矛盾；表示隔天重复应当用〈隔天〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94847, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "第二天", "is_correct": true, "explanation": "正确答案：第二天，指今天过去后的下一天。"}, {"text": "第二边", "is_correct": false, "explanation": "biān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二边」。"}, {"text": "第二编", "is_correct": false, "explanation": "biān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二编」。"}, {"text": "第二番", "is_correct": false, "explanation": "fān（第一声）与 tiān（第一声）声母不同（f 与 t），意思是「第二番」。"}], "explanations": {"第二天": "正确答案：第二天，指今天过去后的下一天。", "第二边": "biān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二边」。", "第二编": "biān（第一声）与 tiān（第一声）声母不同（b 与 t），意思是「第二编」。", "第二番": "fān（第一声）与 tiān（第一声）声母不同（f 与 t），意思是「第二番」。"}, "sentence_index": null, "correct_answer": "第二天"}, "level_3": {"options": [{"text": "第二天", "is_correct": true, "explanation": "正确：第二天指「今天不去」之后紧接的那一天，与「一定去」的安排一致。"}, {"text": "前一天", "is_correct": false, "explanation": "语义：前一天在「今天不去」之前，与「第二天一定去」的先后顺序矛盾。"}, {"text": "上周", "is_correct": false, "explanation": "语义：上周已经过去，与「今天不去」之后的安排不符。"}, {"text": "上个月", "is_correct": false, "explanation": "搭配：「今天不去」之后的安排不能跨到上个月。"}], "explanations": {"第二天": "正确：第二天指「今天不去」之后紧接的那一天，与「一定去」的安排一致。", "前一天": "语义：前一天在「今天不去」之前，与「第二天一定去」的先后顺序矛盾。", "上周": "语义：上周已经过去，与「今天不去」之后的安排不符。", "上个月": "搭配：「今天不去」之后的安排不能跨到上个月。"}, "sentence_index": 6, "correct_answer": "第二天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天写完信，第二天却是一个月前寄出去的。", "explanation": "这里「第二天」指参照日之后的一天，却说寄出时间在一个月前，时间顺序矛盾；应该用〈之前〉类词表示更早的时间，第二天不能指更早。"}, {"text": "我今天写完信，第二天却说是昨天就寄出去的。", "explanation": "这里「第二天」指今天之后的一天，却说寄出是在昨天，时间顺序矛盾。"}, {"text": "我把信放在第二天的桌子上，忘了寄。", "explanation": "这里把「第二天」当成了地点的修饰语，时间词不能修饰桌子；应改为时间状语，如〈第二天我把信放在桌子上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一个第二天早上回家。", "corrected_sentence": "他第二天早上回家。", "error_description": "错误：「第二天」前面不能加量词「个」。作时间词时应说「第二天早上」，不说「一个第二天早上」。正确形式：他第二天早上回家。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们周末去了郊区，第二天们早上很早回家。", "corrected_sentence": "我们周末去了郊区，第二天早上很早回家。", "error_description": "错误：「第二天」是时间词，后面不能加复数词尾「们」。正确形式：我们周末去了郊区，第二天早上很早回家。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
