INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94850, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一国主管机关准许外国公民出入或经过本国国境的证明。", "primary_collocate": null, "pronunciation": "qiān zhèng", "ipa": "tɕʰjɛn˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "大使馆给他发了签证。", "target_word": "签证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "使馆今天不办理签证。", "target_word": "签证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外国人入境要有有效签证。", "target_word": "签证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国对一些国家免签证。", "target_word": "签证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的签证已经到期了。", "target_word": "签证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的签证很难拿到。", "target_word": "签证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "移民局可以取消他的签证。", "target_word": "签证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "签证上写着入境的日期。", "target_word": "签证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办事人员检查了我的签证。", "target_word": "签证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有签证的人不能上飞机。", "target_word": "签证", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "旅游签证", "label": "复合"}, {"form": "工作签证", "label": "复合"}, {"form": "簽證", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家机关准许外国人出入国境的证明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49292835-1821-4a3b-a8ba-49967b1b5e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "签证", "is_correct": true, "explanation": "正确：大使馆发放的是准许入境的签证，与“发”搭配自然。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是大使馆发放的物品，与语境不符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不由大使馆发放，与“给他发了”的语境不合。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“发”不与“电话”搭配，这里应说“打电话”。"}], "explanations": {"签证": "正确：大使馆发放的是准许入境的签证，与“发”搭配自然。", "作业": "语义：作业不是大使馆发放的物品，与语境不符。", "雨伞": "语义：雨伞不由大使馆发放，与“给他发了”的语境不合。", "电话": "搭配：“发”不与“电话”搭配，这里应说“打电话”。"}, "sentence_index": 0, "correct_answer": "签证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国给他办了一本签证。", "explanation": "这里应该用〈张〉。签证是纸质证件，量词用“张”，不用“本”。"}, {"text": "这家公司需要营业签证。", "explanation": "这里应该用〈许可证〉。签证只用于外国人出入国境，不能用于营业许可。"}, {"text": "进入公园要凭签证。", "explanation": "这里应该用〈通行证〉。签证只用于出入国境，不能用于进入公园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "签证", "is_correct": true, "explanation": "正确：移民局可以取消的是准许入境的签证，与“取消”搭配自然。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想不由移民局管理，也不能被取消。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“取消”不与“天气”搭配，天气不能被取消。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料与移民局的职责无关，与语境不合。"}], "explanations": {"签证": "正确：移民局可以取消的是准许入境的签证，与“取消”搭配自然。", "思想": "语义：思想不由移民局管理，也不能被取消。", "天气": "搭配：“取消”不与“天气”搭配，天气不能被取消。", "饮料": "语义：饮料与移民局的职责无关，与语境不合。"}, "sentence_index": 6, "correct_answer": "签证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请在合同上签证。", "explanation": "这里应该用〈签名〉。签证是出入境的许可证明，不能用于合同的签字。"}, {"text": "他收到了一台签证。", "explanation": "这里应该用〈张〉。台是用于机器的量词，签证不用“台”。"}, {"text": "他有签证，可以开车。", "explanation": "这里应该用〈驾照〉。签证是出入境的许可，不能代替驾驶证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的一台签证很难拿到。", "corrected_sentence": "这个国家的一张签证很难拿到。", "error_description": "错误在量词：签证是纸质证件，应用“张”，不用“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "移民局可以撤销他的一本签证。", "corrected_sentence": "移民局可以撤销他的一张签证。", "error_description": "错误在量词：签证是纸质证件，应用“张”，不用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
