INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94851, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "级别是人或事物在高低次序中所处的位置。", "primary_collocate": null, "pronunciation": "jí bié", "ipa": "tɕi˧˥ pje˧˥", "syllable_count": 2, "sentences": [{"text": "他的级别比我高。", "target_word": "级别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校里的老师有不同的级别。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏一共有十个级别。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的工作级别很高。", "target_word": "级别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "级别越高，工资就越多。", "target_word": "级别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是我们公司里级别最高的人。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同级别的医生，看病的钱不一样。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟刚进学校，还在最低的级别。", "target_word": "级别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做这个工作，要先从低级别开始，慢慢往上走。", "target_word": "级别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和工人的级别不同，坐的地方也不一样。", "target_word": "级别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "級別", "label": "繁体"}, {"form": "高级别", "label": "复合"}, {"form": "低级别", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事物在高低次序中所处的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e949e43-2da5-404e-9e85-f72be655bc2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”没有高低，“他的颜色比我高”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”没有高低，“他的味道比我高”说不通。"}, {"text": "级别", "is_correct": true, "explanation": "正确：级别是高低不同的等级，可以比较高低。"}, {"text": "气温", "is_correct": false, "explanation": "搭配：“气温”说环境的冷暖，不能说“他的气温”。"}], "explanations": {"颜色": "语义：“颜色”没有高低，“他的颜色比我高”说不通。", "味道": "语义：“味道”没有高低，“他的味道比我高”说不通。", "级别": "正确：级别是高低不同的等级，可以比较高低。", "气温": "搭配：“气温”说环境的冷暖，不能说“他的气温”。"}, "sentence_index": 0, "correct_answer": "级别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个级别很快，一下子就跑远了。", "explanation": "“级别”是抽象的等级，不能说快慢或跑远；“快”“跑远”只用于人或物体的移动。"}, {"text": "她的级别已经八十岁了。", "explanation": "这里应该用〈年龄〉。说人的岁数要用“年龄”，“级别”指等级高低，不能用来说年纪。"}, {"text": "这杯咖啡的级别很苦。", "explanation": "“级别”不能用味道来形容，“苦”只用于味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：温度指冷热，不能用来划分医生的等级，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音指声响，不能用来划分医生的等级，句意不通。"}, {"text": "分量", "is_correct": false, "explanation": "搭配：“分量”指重量或作用，不能修饰“医生”的分类。"}, {"text": "级别", "is_correct": true, "explanation": "正确：级别指医生的等级，不同等级收费不同。"}], "explanations": {"温度": "语义：温度指冷热，不能用来划分医生的等级，句意不通。", "声音": "语义：声音指声响，不能用来划分医生的等级，句意不通。", "分量": "搭配：“分量”指重量或作用，不能修饰“医生”的分类。", "级别": "正确：级别指医生的等级，不同等级收费不同。"}, "sentence_index": 6, "correct_answer": "级别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的级别是一种颜色。", "explanation": "“级别”指高低等级，不指颜色。"}, {"text": "我们的级别在早上七点吃饭。", "explanation": "这里把抽象的“级别”当成了会吃饭的人。应该用〈人〉：“级别”指等级，不能做吃饭的主语。"}, {"text": "这个箱子的级别很重。", "explanation": "“级别”不能用轻重来形容，“重”只用于物体的重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一本很高的级别。", "corrected_sentence": "这是一个很高的级别。", "error_description": "错误形式：“一本”；正确形式：“一个”。“级别”前的量词应是〈个〉，“本”用于书籍等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的级别了提高了。", "corrected_sentence": "他的级别提高了。", "error_description": "错误形式：“他的级别了提高了”；正确形式：“他的级别提高了”。“级别”后多了一个“了”：完成体“了”只应放在动词“提高”后面，不能放在“级别”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
