INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94859, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94859, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "缺少是应该有，可是没有或不够。", "primary_collocate": null, "pronunciation": "quē shǎo", "ipa": "tɕʰɥe˥ ʂau˨˩˦", "syllable_count": 2, "sentences": [{"text": "你的饭里缺少青菜。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很聪明，但是缺少自信。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个电影缺少一个好的结尾。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们缺少运动，身体不太好。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间缺少阳光，白天也很暗。", "target_word": "缺少", "complexity_tier": "T3", "furigana": "zhè ge fáng jiān quē shǎo yáng guāng, bái tiān yě hěn àn.", "sentence_source": "generated"}, {"text": "小明缺少朋友，常常一个人玩。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做菜时缺少了盐，菜没有味道。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个班缺少一本字典。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新人缺少经验，要多学习。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房子很大，但是缺少一张桌子。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺少了", "label": "体标"}, {"form": "缺少过", "label": "体标"}], "register": "中性", "sense_fingerprint": "本该有的却没有或不够", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49292835-1821-4a3b-a8ba-49967b1b5e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺少", "is_correct": true, "explanation": "正确：饭里应有青菜而没有，符合语境。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的主语须是有口的生物，“饭里咬青菜”不通。"}, {"text": "尝", "is_correct": false, "explanation": "配价：“尝”需要人作施事，“饭里”不能充当施事。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”的主语须是能吞咽的人或动物，“饭里吞青菜”不通。"}], "explanations": {"缺少": "正确：饭里应有青菜而没有，符合语境。", "咬": "语义：“咬”的主语须是有口的生物，“饭里咬青菜”不通。", "尝": "配价：“尝”需要人作施事，“饭里”不能充当施事。", "吞": "语义：“吞”的主语须是能吞咽的人或动物，“饭里吞青菜”不通。"}, "sentence_index": 0, "correct_answer": "缺少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们昨天缺少了那场演出。", "explanation": "这里应该用〈参加〉。缺少指应有的东西没有，不能用来说去参加演出。"}, {"text": "他终于缺少了上海。", "explanation": "这里应该用〈到达〉。缺少不能接地点作宾语，说抵达某地要用〈到达〉。"}, {"text": "周末我去养老院缺少爷爷。", "explanation": "这里应该用〈看望〉。缺少用于应有的事物，不用于探望人，探望要用〈看望〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺少", "is_correct": true, "explanation": "正确：盐缺了，所以菜没有味道，前后相合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不接“盐”，“洗盐”不能用于做菜。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象须是可饮用的液体，“喝盐”与做菜的语境不符。"}, {"text": "放", "is_correct": false, "explanation": "语义：放了盐就应有味道，与“菜没有味道”矛盾。"}], "explanations": {"缺少": "正确：盐缺了，所以菜没有味道，前后相合。", "洗": "搭配：“洗”不接“盐”，“洗盐”不能用于做菜。", "喝": "语义：“喝”的对象须是可饮用的液体，“喝盐”与做菜的语境不符。", "放": "语义：放了盐就应有味道，与“菜没有味道”矛盾。"}, "sentence_index": 6, "correct_answer": "缺少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小王昨天缺少了那次会议。", "explanation": "这里应该用〈缺席〉。缺少指应有的东西没有或数量不足，不能用来说人没有出席会议。"}, {"text": "我昨天缺少了一场考试。", "explanation": "这里应该用〈缺考〉。缺少指应有的东西没有或不够，不能说没有参加考试，要用〈缺考〉。"}, {"text": "我又缺少了那班车。", "explanation": "这里应该用〈错过〉。缺少指应有的东西没有，不能说没赶上车，要用〈错过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个食堂缺少了三本厨师。", "corrected_sentence": "这个食堂缺少了三个厨师。", "error_description": "错误：“厨师”的量词用“本”。“本”用于书籍，厨师是人，应用量词“个”，说“三个厨师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇曾经缺少过一本桥。", "corrected_sentence": "这个小镇曾经缺少过一座桥。", "error_description": "错误：“桥”的量词用“本”。“本”用于书籍，桥应用量词“座”，说“一座桥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
