INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "应有的没有或数量不足。", "primary_collocate": null, "pronunciation": "quē shǎo", "ipa": "tɕʰɥe˥ ʂau˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个城市缺少水。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司缺少会说汉语的人。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子缺少睡觉的时间。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他缺少工作经验，所以没找到工作。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店缺少新鲜的水果。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山区学校缺少好老师。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "病人缺少休息，所以好得很慢。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章缺少好的例子。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "沙漠里缺少雨水。", "target_word": "缺少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个队缺少一个好的教练。", "target_word": "缺少", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺少了", "label": "体标"}, {"form": "缺少过", "label": "体标"}], "register": "中性", "sense_fingerprint": "应有的东西没有或数量不够", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49292835-1821-4a3b-a8ba-49967b1b5e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺少", "is_correct": true, "explanation": "正确：“缺少”表示应有的没有，城市缺的是水，语境相合。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的主语须是能喝水的人或动物，城市不能喝水。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象不能是水，“这个城市咬水”不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般接衣物、蔬菜等，不能说“洗水”。"}], "explanations": {"缺少": "正确：“缺少”表示应有的没有，城市缺的是水，语境相合。", "喝": "语义：“喝”的主语须是能喝水的人或动物，城市不能喝水。", "咬": "语义：“咬”的对象不能是水，“这个城市咬水”不通。", "洗": "搭配：“洗”一般接衣物、蔬菜等，不能说“洗水”。"}, "sentence_index": 0, "correct_answer": "缺少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天缺少了那次会议。", "explanation": "这里应该用〈缺席〉。缺少指应有的东西没有或数量不足，不能用来说人没有出席会议。"}, {"text": "我今天缺少了一场考试。", "explanation": "这里应该用〈缺考〉。缺少指应有的东西没有或不够，不能说没有参加考试，要用〈缺考〉。"}, {"text": "我缺少了那班车。", "explanation": "这里应该用〈错过〉。缺少指应有的东西没有，不能说没赶上车，要用〈错过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺少", "is_correct": true, "explanation": "正确：“缺少休息”与“所以好得很慢”的因果相合。"}, {"text": "增加", "is_correct": false, "explanation": "语义：增加休息应当有利于恢复，与“好得很慢”的因果相反。"}, {"text": "节省", "is_correct": false, "explanation": "搭配：“节省”接时间、钱财等，不能接“休息”。"}, {"text": "具备", "is_correct": false, "explanation": "搭配：“具备”接条件、能力，不能接“休息”。"}], "explanations": {"缺少": "正确：“缺少休息”与“所以好得很慢”的因果相合。", "增加": "语义：增加休息应当有利于恢复，与“好得很慢”的因果相反。", "节省": "搭配：“节省”接时间、钱财等，不能接“休息”。", "具备": "搭配：“具备”接条件、能力，不能接“休息”。"}, "sentence_index": 6, "correct_answer": "缺少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天缺少了那场比赛。", "explanation": "这里应该用〈参加〉。缺少指应有的东西没有，不能用来说去参加比赛。"}, {"text": "他终于缺少了北京。", "explanation": "这里应该用〈到达〉。缺少不能接地点作宾语，说抵达某地要用〈到达〉。"}, {"text": "周末我去医院缺少奶奶。", "explanation": "这里应该用〈看望〉。缺少用于应有的事物，不用于探望人，探望要用〈看望〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院缺少了三本医生。", "corrected_sentence": "这家医院缺少了三个医生。", "error_description": "错误：“医生”的量词用“本”。“本”用于书籍，医生是人，应用量词“个”，说“三个医生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社区曾经缺少过一本医院。", "corrected_sentence": "这个社区曾经缺少过一家医院。", "error_description": "错误：“医院”的量词用“本”。“本”用于书籍，医院应用量词“家”，说“一家医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94862, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
