INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由股东选出的董事组成、负责公司重大决策的机构。", "primary_collocate": null, "pronunciation": "dǒng shì huì", "ipa": "tʊŋ˨˩ ʂɻ̩˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "董事会今天开会，决定新的计划。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的董事会有九个人。", "target_word": "董事会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "董事会同意了新经理的名单。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "股东们选出了新的董事会。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大事要先交给董事会决定。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会每个月开一次会。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是这家公司董事会的成员。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会没有通过这个办法。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会的决定，经理必须执行。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在董事会上提出了不同意见。", "target_word": "董事会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "董事會", "label": "繁体"}], "register": "正式", "sense_fingerprint": "公司股东选出董事组成的决策机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a9e6c79-9a64-4e29-86b7-f0772555b1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "董事会", "is_correct": true, "explanation": "正确：董事会是有决策权的机构，可以在今天开会并决定新的计划。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不是有决策能力的组织，不能开会并决定计划。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有开会的能力，与「决定新的计划」的主语不符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「开会」的主语应为人或组织，不能说「窗户今天开会」。"}], "explanations": {"董事会": "正确：董事会是有决策权的机构，可以在今天开会并决定新的计划。", "小猫": "语义：小猫不是有决策能力的组织，不能开会并决定计划。", "石头": "语义：石头没有开会的能力，与「决定新的计划」的主语不符。", "窗户": "搭配：「开会」的主语应为人或组织，不能说「窗户今天开会」。"}, "sentence_index": 0, "correct_answer": "董事会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "董事会负责检查公司的账目，防止财务出错。", "explanation": "这里应该用〈监事会〉。监事会负责监督检查，董事会负责决策，不负责检查账目。"}, {"text": "他这个月当选为公司的董事会，负责签字。", "explanation": "这里把只能用于个人的「当选」用在了机构上，应该用〈董事〉指个人；董事会是机构，不能当选。"}, {"text": "董事会负责公司的日常管理，每天都来上班。", "explanation": "这里应该用〈经理〉。董事会负责重大决策，日常管理由经理负责，董事会不每天上班处理具体事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "董事会", "is_correct": true, "explanation": "正确：他是这家公司董事会的成员，「董事会」是公司的决策机构，可以有成员。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不能有「成员」这一身份。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是公司的组织，不能说「这家公司教室的成员」。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：「厨房的成员」不是常见搭配，厨房指场所，不说有成员。"}], "explanations": {"董事会": "正确：他是这家公司董事会的成员，「董事会」是公司的决策机构，可以有成员。", "花园": "语义：花园是场所，不能有「成员」这一身份。", "教室": "语义：教室不是公司的组织，不能说「这家公司教室的成员」。", "厨房": "搭配：「厨房的成员」不是常见搭配，厨房指场所，不说有成员。"}, "sentence_index": 6, "correct_answer": "董事会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "股东们在董事会上投票表决。", "explanation": "这里应该用〈股东会〉。股东会由股东投票表决，董事会是董事的决策机构，股东不在董事会上投票。"}, {"text": "他把新产品放进了董事会，卖得很好。", "explanation": "这里把董事会当成了存放物品的场所，应该用〈仓库〉之类表示存放的地方；董事会是决策机构，不是场所或容器。"}, {"text": "我昨天吃了董事会，很饱。", "explanation": "这里把董事会当成了可以吃的东西，应该用〈午饭〉等食物；董事会是机构，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的一只董事会有七位成员。", "corrected_sentence": "这家公司的董事会有七位成员。", "error_description": "错误：「一只董事会」中量词「只」用错。「只」用于动物，不能修饰董事会，这里应说「一个董事会」或「一届董事会」。正确形式：这家公司的董事会有七位成员。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家大公司的董事会的决定了新的规定。", "corrected_sentence": "这家大公司的董事会决定了新的规定。", "error_description": "错误：「董事会」后多加了「的」，「决定」应直接作谓语，应说「董事会决定了」，不说「董事会的决定了」。正确形式：这家大公司的董事会决定了新的规定。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真话", "is_correct": true, "explanation": "真话是真实的话，与“谎言”意思相反。"}, {"text": "天空", "is_correct": false, "explanation": "天空与“谎言”没有反义关系。"}, {"text": "电脑", "is_correct": false, "explanation": "电脑与“谎言”没有反义关系。"}, {"text": "作文", "is_correct": false, "explanation": "作文与“谎言”没有反义关系。"}], "correct_answer": "真话", "explanations": {"真话": "真话是真实的话，与“谎言”意思相反。", "天空": "天空与“谎言”没有反义关系。", "电脑": "电脑与“谎言”没有反义关系。", "作文": "作文与“谎言”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真话", "is_correct": true, "explanation": "真话是真实的话，与“谎言”意思相反。"}, {"text": "灯泡", "is_correct": false, "explanation": "灯泡与“谎言”没有反义关系。"}, {"text": "老虎", "is_correct": false, "explanation": "老虎与“谎言”没有反义关系。"}, {"text": "果汁", "is_correct": false, "explanation": "果汁与“谎言”没有反义关系。"}], "correct_answer": "真话", "explanations": {"真话": "真话是真实的话，与“谎言”意思相反。", "灯泡": "灯泡与“谎言”没有反义关系。", "老虎": "老虎与“谎言”没有反义关系。", "果汁": "果汁与“谎言”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "谎言是不真的话，是骗人的话。", "primary_collocate": null, "pronunciation": "huǎng yán", "ipa": "xwɑŋ˨˩˦ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "你为什么要用谎言骗我？", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直生活在谎言里。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话都是谎言，别相信。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现丈夫对她说了很多谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个谎言需要更多谎言来保护。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的谎言很快就没人信了。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子为了不挨骂，编了一个谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢谎言，只想听真话。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友之间不能有谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里的那个谎言，大家都知道了。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句谎言", "label": "量词"}, {"form": "一个谎言", "label": "量词"}, {"form": "謊言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不真实、骗人的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49292835-1821-4a3b-a8ba-49967b1b5e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谎言", "is_correct": true, "explanation": "谎言是骗人的话，放在“你为什么要用___骗我？”中，“用”的宾语是骗人的手段，语义相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是骗人的手段，“用钥匙骗我”语义不通。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调不能用来骗人，句中“骗”需要的是话或假象。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴不能作为骗人的手段，“用钢琴骗我”搭配不当。"}], "explanations": {"谎言": "谎言是骗人的话，放在“你为什么要用___骗我？”中，“用”的宾语是骗人的手段，语义相符。", "钥匙": "语义：钥匙不是骗人的手段，“用钥匙骗我”语义不通。", "空调": "语义：空调不能用来骗人，句中“骗”需要的是话或假象。", "钢琴": "搭配：钢琴不能作为骗人的手段，“用钢琴骗我”搭配不当。"}, "sentence_index": 0, "correct_answer": "谎言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她找了个谎言，说自己要出差，就不来了。", "explanation": "这里应该用〈借口〉。“找借口”是固定搭配；谎言是编造出来的假话，不说“找”。"}, {"text": "丈夫对她说了一张谎言，她没有相信。", "explanation": "这里应该用〈句〉或〈个〉。“张”用于纸张、桌面等平面的东西，不能用来计量谎言。"}, {"text": "丈夫给她讲了一根谎言，她很快就发现了。", "explanation": "这里应该用〈句〉或〈个〉。“根”用于细长的东西，不能用来计量谎言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谎言", "is_correct": true, "explanation": "“编了一个___”中，谎言是可以编造的内容，语义相符。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋不是可以编造的内容，“编了一个皮鞋”语义不通。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“编”的宾语多为故事、谎话、歌曲等，“房子”不能被编。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是可以编造的内容，句中需要的是假话。"}], "explanations": {"谎言": "“编了一个___”中，谎言是可以编造的内容，语义相符。", "皮鞋": "语义：皮鞋不是可以编造的内容，“编了一个皮鞋”语义不通。", "房子": "配价：“编”的宾语多为故事、谎话、歌曲等，“房子”不能被编。", "闹钟": "语义：闹钟不是可以编造的内容，句中需要的是假话。"}, "sentence_index": 6, "correct_answer": "谎言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把谎言切成了几块，装进盘子里。", "explanation": "谎言是抽象的假话，不能切开装盘，这里把它当成了食物。"}, {"text": "那个谎言在桌子上跑来跑去，很可爱。", "explanation": "谎言不会自己跑动，也不可爱，这里把它当成了有生命的东西。"}, {"text": "那个谎言被雨淋湿了，颜色变深了。", "explanation": "谎言是抽象的话，没有实体，不会被雨淋湿，这里把它当成了有实体的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的那张谎言很快就被拆穿了。", "corrected_sentence": "他的那个谎言很快就被拆穿了。", "error_description": "量词错误：“张”用于纸张、桌面等平面的东西，不能计量谎言，这里应改为“那个谎言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她听到了一本谎言，心里很难过。", "corrected_sentence": "她听到了一句谎言，心里很难过。", "error_description": "错误：“谎言”的量词用“本”。“本”用于书籍，谎言是话，应用量词“句”，说“一句谎言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真话", "is_correct": true, "explanation": "真话是真实的话，与“谎言”意思相反。"}, {"text": "天气", "is_correct": false, "explanation": "天气与“谎言”没有反义关系。"}, {"text": "音乐", "is_correct": false, "explanation": "音乐与“谎言”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流与“谎言”没有反义关系。"}], "correct_answer": "真话", "explanations": {"真话": "真话是真实的话，与“谎言”意思相反。", "天气": "天气与“谎言”没有反义关系。", "音乐": "音乐与“谎言”没有反义关系。", "河流": "河流与“谎言”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真话", "is_correct": true, "explanation": "真话是真实的话，与“谎言”意思相反。"}, {"text": "作业", "is_correct": false, "explanation": "作业与“谎言”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头与“谎言”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园与“谎言”没有反义关系。"}], "correct_answer": "真话", "explanations": {"真话": "真话是真实的话，与“谎言”意思相反。", "作业": "作业与“谎言”没有反义关系。", "石头": "石头与“谎言”没有反义关系。", "花园": "花园与“谎言”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "虚假的、用来骗人的话。", "primary_collocate": null, "pronunciation": "huǎng yán", "ipa": "xwɑŋ˨˩˦ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他说的是谎言，我们都不信。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谎言总有一天会露出来。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想再听他的谎言了。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说了一个谎言，妈妈很生气。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉孩子们，不能编造谎言。", "target_word": "谎言", "complexity_tier": "T3", "furigana": "lǎoshī gàosu háizimen, bù néng biānzào huǎngyán.", "sentence_source": "generated"}, {"text": "他用谎言骗了朋友。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谎言让大家很难过。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谎言一旦被揭穿，就很难再让人相信。", "target_word": "谎言", "complexity_tier": "T3", "furigana": "huǎngyán yídàn bèi jiēchuān, jiù hěn nán zài ràng rén xiāngxìn.", "sentence_source": "generated"}, {"text": "老师说，谎言会伤害别人。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听出来了，这是一句谎言。", "target_word": "谎言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句谎言", "label": "量词"}, {"form": "一个谎言", "label": "量词"}, {"form": "謊言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "虚假的、用来骗人的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49292835-1821-4a3b-a8ba-49967b1b5e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谎言", "is_correct": true, "explanation": "谎言指虚假的、用来骗人的话，放在“他说的是___，我们都不信”中，与“不信”相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“他说的是歌曲”虽合语法，但歌曲不是可以相信或不相信的内容，与“我们都不信”搭配不起来。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以说出来的内容，“他说的是冰箱，我们都不信”语义不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不存在真假可辨的内容，与“我们都不信”搭配不起来。"}], "explanations": {"谎言": "谎言指虚假的、用来骗人的话，放在“他说的是___，我们都不信”中，与“不信”相符。", "歌曲": "语义：“他说的是歌曲”虽合语法，但歌曲不是可以相信或不相信的内容，与“我们都不信”搭配不起来。", "冰箱": "语义：冰箱不是可以说出来的内容，“他说的是冰箱，我们都不信”语义不通。", "汽车": "语义：汽车不存在真假可辨的内容，与“我们都不信”搭配不起来。"}, "sentence_index": 0, "correct_answer": "谎言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找了个谎言，说自己生病了，不去上班。", "explanation": "这里应该用〈借口〉。“找借口”是固定搭配；谎言是编造出来的假话，不说“找”。"}, {"text": "妈妈听了一把谎言，心里很难过。", "explanation": "这里应该用〈句〉或〈个〉。“把”用于有柄的器具，不能用来计量谎言。"}, {"text": "他编了一根谎言，很快就被拆穿了。", "explanation": "这里应该用〈句〉或〈个〉。“根”用于细长的东西，不能用来计量谎言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谎言", "is_correct": true, "explanation": "谎言能引起大家难过，放在“这个___让大家很难过”中语义通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能让大家难过，句中需要能引起情绪的人或事。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜不能让大家难过，句子说的是引起情绪的事。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“眼镜”与“让大家很难过”搭配不当，也不是令人难过的事。"}], "explanations": {"谎言": "谎言能引起大家难过，放在“这个___让大家很难过”中语义通顺。", "桌子": "语义：桌子不能让大家难过，句中需要能引起情绪的人或事。", "白菜": "语义：白菜不能让大家难过，句子说的是引起情绪的事。", "眼镜": "搭配：“眼镜”与“让大家很难过”搭配不当，也不是令人难过的事。"}, "sentence_index": 6, "correct_answer": "谎言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把谎言放进冰箱里，怕它坏掉。", "explanation": "谎言是抽象的假话，不是食物或物品，不能放进冰箱，这里把它当成了具体的东西。"}, {"text": "这个谎言昨天去超市买了三斤苹果。", "explanation": "谎言是抽象的假话，不会自己去超市买东西，这里把它当成了人。"}, {"text": "这个谎言开花了，颜色很漂亮。", "explanation": "谎言不是植物，不能开花，这里误用了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只谎言被大家识破了。", "corrected_sentence": "那个谎言被大家识破了。", "error_description": "量词错误：“谎言”的量词应用“个”或“句”，“只”用于动物等，这里应改为“那个谎言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说了一本谎言，大家都不信。", "corrected_sentence": "他说了一句谎言，大家都不信。", "error_description": "错误：“谎言”的量词用“本”。“本”用于书籍，谎言是话，应用量词“句”，说“一句谎言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
