INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "赌场是大人用钱来玩输赢游戏的地方。", "primary_collocate": null, "pronunciation": "dǔ chǎng", "ipa": "tu˨˩˦ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爸爸说，赌场不是小孩子去的地方。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌场里的灯很亮，声音也很吵。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次去赌场，只玩了一个小时。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌场是大人玩牌赢钱的地方。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们旅行时参观过那个有名的赌场。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进赌场的人都想赢钱，可是常常会输。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌场里不能带小孩进去。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌场老板每天都能收到很多钱。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从赌场出来，口袋里一分钱也没有了。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "澳门有很多大赌场，游客也很多。", "target_word": "赌场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "賭場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大人用钱玩输赢游戏的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a252ca3-929a-4eff-b85c-7b311aaea147') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赌场", "is_correct": true, "explanation": "赌场（dǔ chǎng）指大人用钱玩输赢游戏的地方，是正确答案。"}, {"text": "独唱", "is_correct": false, "explanation": "独唱（dú chàng）两个音节的声调都与“赌场”不同，意思是一个人演唱。"}, {"text": "肚肠", "is_correct": false, "explanation": "肚肠（dù cháng）两个音节的声调都与“赌场”不同，意思是胃肠等内脏。"}, {"text": "谷场", "is_correct": false, "explanation": "谷场（gǔ chǎng）只有声母不同：g 与“赌”的 d 不同，意思是打谷子用的场地。"}], "explanations": {"赌场": "赌场（dǔ chǎng）指大人用钱玩输赢游戏的地方，是正确答案。", "独唱": "独唱（dú chàng）两个音节的声调都与“赌场”不同，意思是一个人演唱。", "肚肠": "肚肠（dù cháng）两个音节的声调都与“赌场”不同，意思是胃肠等内脏。", "谷场": "谷场（gǔ chǎng）只有声母不同：g 与“赌”的 d 不同，意思是打谷子用的场地。"}, "sentence_index": null, "correct_answer": "赌场"}, "level_3": {"options": [{"text": "赌场", "is_correct": true, "explanation": "赌场是大人去的地方，与“不是小孩子去的地方”的语境相合。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园正是小孩子去的地方，与“不是小孩子去的地方”矛盾。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场是小孩子常去的地方，与句意矛盾。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "搭配：“去的地方”要求处所，“冰淇淋”不是处所。"}], "explanations": {"赌场": "赌场是大人去的地方，与“不是小孩子去的地方”的语境相合。", "幼儿园": "语义：幼儿园正是小孩子去的地方，与“不是小孩子去的地方”矛盾。", "游乐场": "语义：游乐场是小孩子常去的地方，与句意矛盾。", "冰淇淋": "搭配：“去的地方”要求处所，“冰淇淋”不是处所。"}, "sentence_index": 0, "correct_answer": "赌场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们下了一大笔赌场。", "explanation": "这里应该用〈赌注〉。赌注是下注的钱，赌场是场所，不能用来下注。"}, {"text": "他把赌场押在桌上。", "explanation": "这里应该用〈筹码〉。筹码是下注时押在桌上的小件，赌场是场所，不能当作筹码押上桌。"}, {"text": "他们安排了一场赌场。", "explanation": "这里应该用〈赌局〉。赌局指一场赌博活动，赌场是供人赌博的场所，不能说“一场赌场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赌场", "is_correct": true, "explanation": "赌场是可以进去的处所，“里”指场所内部，与“进去”相合。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“进去”要求能进入的处所，书包不能让人“进去”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是能让人进去的地方，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能让小孩进去，句意不通。"}], "explanations": {"赌场": "赌场是可以进去的处所，“里”指场所内部，与“进去”相合。", "书包": "搭配：“进去”要求能进入的处所，书包不能让人“进去”。", "手机": "语义：手机不是能让人进去的地方，句意不通。", "冰箱": "语义：冰箱不能让小孩进去，句意不通。"}, "sentence_index": 6, "correct_answer": "赌场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了还赌场，卖掉了房子。", "explanation": "这里应该用〈赌债〉。赌债指赌博欠下的债，赌场是场所，不能说“还赌场”。"}, {"text": "他输光了所有的赌场，连回家的车钱都没了。", "explanation": "这里应该用〈赌资〉。赌资指用于赌博的钱，赌场是场所，不能说“输光了赌场”。"}, {"text": "他的赌场是跟父亲学的。", "explanation": "这里应该用〈赌术〉。赌术指赌博的技巧，赌场是场所，不是可以学的技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只赌场只有成年人能进。", "corrected_sentence": "这家赌场只有成年人能进。", "error_description": "量词错误：“这只赌场”中的“只”用于动物，赌场应用“家”，应说“这家赌场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去过的赌场。", "corrected_sentence": "他去过赌场。", "error_description": "句子不完整：“他去过的赌场”只是名词短语，没有谓语；“的”使“去过”变成定语，应说“他去过赌场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "军方指军队这一方，常与政府或民间相对。", "primary_collocate": null, "pronunciation": "jūn fāng", "ipa": "tɕyn˥ faŋ˥", "syllable_count": 2, "sentences": [{"text": "谈判时，军方和政府意见不同。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，军方队伍赢了。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方和民间都参加了这次活动。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方的医院也给老百姓看病。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司和军方有长期的合作。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父亲在军方工作。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目由军方和学校一起做。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方的训练基地离城市很远。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间和军方的关系一直很好。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有军方的背景，大家都很尊重他。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "和军队有关的一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13c58d25-1eb8-4b9e-9181-3173d9fab08e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方（jūn fāng）指和军队有关的一边，是正确答案。"}, {"text": "均分", "is_correct": false, "explanation": "fēn（分）与 fāng（方）韵母不同（前鼻音与后鼻音），意思是平均分配。"}, {"text": "军伤", "is_correct": false, "explanation": "shāng（伤）与 fāng（方）声母不同（sh与f），意思是军人受的伤。"}, {"text": "军锋", "is_correct": false, "explanation": "fēng（锋）与 fāng（方）韵母不同（eng 与 ang），军锋指军队的前锋。"}, {"text": "军防", "is_correct": false, "explanation": "fáng（防）与 fāng（方）声调不同（第二声与第一声），意思是军事防守。"}], "explanations": {"军方": "军方（jūn fāng）指和军队有关的一边，是正确答案。", "均分": "fēn（分）与 fāng（方）韵母不同（前鼻音与后鼻音），意思是平均分配。", "军伤": "shāng（伤）与 fāng（方）声母不同（sh与f），意思是军人受的伤。", "军锋": "fēng（锋）与 fāng（方）韵母不同（eng 与 ang），军锋指军队的前锋。", "军防": "fáng（防）与 fāng（方）声调不同（第二声与第一声），意思是军事防守。"}, "sentence_index": null, "correct_answer": "军方"}, "level_3": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方指和军队有关的一边，能与政府在谈判中意见不同，符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能在谈判中与政府持不同意见。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有立场，不能与政府意见不同。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能持有意见。"}], "explanations": {"军方": "军方指和军队有关的一边，能与政府在谈判中意见不同，符合语境。", "厨房": "语义：厨房是场所，不能在谈判中与政府持不同意见。", "窗户": "语义：窗户没有立场，不能与政府意见不同。", "身材": "体貌：身材指人的体形，不能持有意见。"}, "sentence_index": 0, "correct_answer": "军方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军方今年三岁了，还不太会说话。", "explanation": "这里应该用〈孩子〉。军方是和军队有关的一边，是抽象的关系，不能说年龄。"}, {"text": "这个超市的军方很多，我每天都去。", "explanation": "这里应该用〈商品〉。军方是和军队有关的一方，不能指超市里的商品，也不能说「很多军方」。"}, {"text": "他把军方借给了朋友。", "explanation": "这里应该用〈资料〉。军方是抽象的一方，不能像物品一样借出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方指和军队有关的一边，可以与学校一起承担项目，符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "配价：“由……做”要求能做事的主体，天空不能承担项目，与学校并列也不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能承担或完成项目。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子是物品，不能承担或完成项目。"}], "explanations": {"军方": "军方指和军队有关的一边，可以与学校一起承担项目，符合语境。", "天空": "配价：“由……做”要求能做事的主体，天空不能承担项目，与学校并列也不成立。", "汽车": "语义：汽车是交通工具，不能承担或完成项目。", "镜子": "语义：镜子是物品，不能承担或完成项目。"}, "sentence_index": 6, "correct_answer": "军方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "军方跑得很快，大家都追不上。", "explanation": "这里应该用〈选手〉。军方是和军队有关的一边，是抽象的关系，不能像人一样跑步。"}, {"text": "我们的食堂用军方做饭。", "explanation": "这里应该用〈食材〉。军方是抽象的一方，不能作为做饭的材料。"}, {"text": "窗外的军方在唱歌，很好听。", "explanation": "这里应该用〈小鸟〉。军方是和军队有关的一边，不会唱歌，不能作为唱歌的主体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "军方得代表今天很忙。", "corrected_sentence": "军方的代表今天很忙。", "error_description": "错误形式“军方得代表”，正确形式“军方的代表”：“的”连接定语“军方”和中心语“代表”，“得”用于补语，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事，军方的同意了我们的请求。", "corrected_sentence": "这件事，军方同意了我们的请求。", "error_description": "错误形式「军方的同意了」，正确形式「军方同意了」：「的」后面接的是动词「同意」，这里应直接作谓语，去掉「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
