INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94874, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "军队方面，指军队的领导机关或代表。", "primary_collocate": null, "pronunciation": "jūn fāng", "ipa": "tɕyn˥ faŋ˥", "syllable_count": 2, "sentences": [{"text": "军方昨天发表了一份声明。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方说，他们会保护平民。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问军方是否知道这件事。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方负责人今天见了记者。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方拒绝回答这个问题。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方已经同意了这个计划。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方告诉大家，演习将在明天开始。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方的新闻发言人说话很慢。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在等军方的回答。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军方要求大家离开这个地区。", "target_word": "军方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "军队的领导机关或代表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13c58d25-1eb8-4b9e-9181-3173d9fab08e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方（jūn fāng）指军队的领导机关或代表，是正确答案。"}, {"text": "均分", "is_correct": false, "explanation": "fēn（分）与 fāng（方）韵母不同（前鼻音与后鼻音），意思是平均分配，不是军队方面。"}, {"text": "军伤", "is_correct": false, "explanation": "shāng（伤）与 fāng（方）声母不同（sh与f），意思是军人受的伤。"}, {"text": "军汤", "is_correct": false, "explanation": "tāng（汤）与 fāng（方）声母不同（t与f），意思是军营里的汤。"}, {"text": "军防", "is_correct": false, "explanation": "fáng（防）与 fāng（方）声调不同（第二声与第一声），意思是军事防守。"}], "explanations": {"军方": "军方（jūn fāng）指军队的领导机关或代表，是正确答案。", "均分": "fēn（分）与 fāng（方）韵母不同（前鼻音与后鼻音），意思是平均分配，不是军队方面。", "军伤": "shāng（伤）与 fāng（方）声母不同（sh与f），意思是军人受的伤。", "军汤": "tāng（汤）与 fāng（方）声母不同（t与f），意思是军营里的汤。", "军防": "fáng（防）与 fāng（方）声调不同（第二声与第一声），意思是军事防守。"}, "sentence_index": null, "correct_answer": "军方"}, "level_3": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方指军队的领导机关或代表，能够以机构身份发表声明，符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能以机构身份发表声明。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有发声的能力，不能发表声明。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不能以官方身份发表正式声明。"}], "explanations": {"军方": "军方指军队的领导机关或代表，能够以机构身份发表声明，符合语境。", "厨房": "语义：厨房是场所，不能以机构身份发表声明。", "石头": "语义：石头没有发声的能力，不能发表声明。", "小孩": "语义：小孩不能以官方身份发表正式声明。"}, "sentence_index": 0, "correct_answer": "军方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天喝三杯军方。", "explanation": "这里应该用〈咖啡〉。军方指机关或代表，不是饮品，不能被喝。"}, {"text": "这支军方有三千人，驻守在边境。", "explanation": "这里应该用〈部队〉。军方不能用量词“支”计数，也不能作为一支有人数的队伍。"}, {"text": "他吃了一碗军方，很饱。", "explanation": "这里应该用〈米饭〉。军方指机关或代表，不是食物，不能用“碗”盛装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军方", "is_correct": true, "explanation": "军方能够告诉大家演习的消息，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有说话的能力，不能告诉大家事情。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能充当告知的主体。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，没有说话的能力，不能告诉大家事情。"}], "explanations": {"军方": "军方能够告诉大家演习的消息，符合语境。", "天气": "语义：天气没有说话的能力，不能告诉大家事情。", "身材": "体貌：身材指人的体形，不能充当告知的主体。", "椅子": "语义：椅子是家具，没有说话的能力，不能告诉大家事情。"}, "sentence_index": 6, "correct_answer": "军方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河里的军方很多，孩子们都爱抓。", "explanation": "这里应该用〈鱼〉。军方指机关或代表，不是动物，不能在河里被抓。"}, {"text": "这位军方每天在食堂吃饭，很辛苦。", "explanation": "这里应该用〈军人〉。军方指机关或代表，不指单个的人。"}, {"text": "我昨天在超市买了一斤军方。", "explanation": "这里应该用〈军粮〉。军方是机关或代表，不是可以称重的物品，不能用“斤”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府同意了军方得请求。", "corrected_sentence": "政府同意了军方的请求。", "error_description": "错误形式“军方得请求”，正确形式“军方的请求”：“的”连接定语“军方”和中心语“请求”，“得”用于补语，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们听取了军方得意见。", "corrected_sentence": "我们听取了军方的意见。", "error_description": "错误形式“军方得意见”，正确形式“军方的意见”：“的”连接定语和中心语，“得”用于补语，不能用于此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
