INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94877, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94877, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "造型是东西做出来的样子。", "primary_collocate": null, "pronunciation": "zào xíng", "ipa": "tsɑu˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个杯子的造型很特别。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这辆车的造型。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的造型像一条龙。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个灯的造型很可爱。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做的蛋糕造型很漂亮。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种椅子造型简单，也很舒服。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢小动物造型的饼干。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖各种造型的蜡烛。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子的造型有点奇怪。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花瓶造型不同，颜色也不同。", "target_word": "造型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "物品做出来的外观样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0d37556-ca61-4ff7-a93f-9f6b9ec23596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94877, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": false, "explanation": "语义：杯子没有性格，「性格」只用于人或拟人，与器物的样子无关。"}, {"text": "造型", "is_correct": true, "explanation": "造型指物品做出来的样子，「杯子的造型很特别」符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：杯子没有性格，「脾气」与器物无关。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：器物不呼吸，「呼吸很特别」说不通。"}], "explanations": {"性格": "语义：杯子没有性格，「性格」只用于人或拟人，与器物的样子无关。", "造型": "造型指物品做出来的样子，「杯子的造型很特别」符合句意。", "脾气": "语义：杯子没有性格，「脾气」与器物无关。", "呼吸": "搭配：器物不呼吸，「呼吸很特别」说不通。"}, "sentence_index": 0, "correct_answer": "造型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个灯有一只造型很可爱。", "explanation": "这里的量词应用〈种〉或〈个〉。「只」多用于动物或成对物品中的一个，不用来数「造型」。"}, {"text": "这把吉他的造型很好听。", "explanation": "这里应该用〈音色〉。造型指外形，不能用来形容声音好听。"}, {"text": "这个杯子的造型很好吃。", "explanation": "造型指外形，不能用来形容味道；「好吃」说的是食物的滋味，杯子不是食物，二者都不搭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口味", "is_correct": false, "explanation": "搭配：「口味」是味道，「小动物口味」说不通，与饼干的形状无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「小动物价格」说不通，价格不用来描述形状。"}, {"text": "造型", "is_correct": true, "explanation": "造型指饼干做成的样子，「小动物造型的饼干」符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：小动物的年龄与饼干的形状无关，句意不通。"}], "explanations": {"口味": "搭配：「口味」是味道，「小动物口味」说不通，与饼干的形状无关。", "价格": "搭配：「小动物价格」说不通，价格不用来描述形状。", "造型": "造型指饼干做成的样子，「小动物造型的饼干」符合句意。", "年龄": "语义：小动物的年龄与饼干的形状无关，句意不通。"}, "sentence_index": 6, "correct_answer": "造型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些花瓶里有一把造型不同。", "explanation": "这里的量词应用〈种〉或〈个〉。「把」多用于有柄或有靠背的东西，不用来数「造型」。"}, {"text": "这首歌的造型很响。", "explanation": "这里应该用〈音量〉。造型指外形，不能用来形容声音的大小。"}, {"text": "这朵花的造型很香。", "explanation": "这里应该用〈气味〉。造型指外形，不能用来形容气味的浓淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盏灯有一只特别的造型。", "corrected_sentence": "这盏灯有一种特别的造型。", "error_description": "错误：「造型」的量词用错。「只」多用于动物或成对物品中的一个，「造型」应用量词「种」，改为「这盏灯有一种特别的造型。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个蛋糕有一把特别的造型。", "corrected_sentence": "这个蛋糕有一种特别的造型。", "error_description": "错误：「造型」的量词用错。「把」用于有柄或有靠背的东西，不用来数「造型」，应改为「种」，写作「有一种特别的造型」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
