INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94881, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94881, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开枪是用枪打出子弹。", "primary_collocate": null, "pronunciation": "kāi qiāng", "ipa": "kʰaɪ˥ tɕʰjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "警察向天开枪，大家都停下来了。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次开枪，手一直在抖。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵听到命令，马上开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有命令，谁也不能开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起枪，对着前面开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷跑了，警察没有开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人看见一只鹿，就开枪了。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到开枪的声音，孩子们很害怕。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不敢开枪，因为前面有人。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的人不停地开枪。", "target_word": "开枪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了枪", "label": "体标"}, {"form": "开过枪", "label": "体标"}, {"form": "開槍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用枪打出子弹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49292835-1821-4a3b-a8ba-49967b1b5e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开枪", "is_correct": true, "explanation": "开枪指用枪打出子弹，“警察向天开枪”表示鸣枪示警，与后文“大家都停下来了”相符。"}, {"text": "开会", "is_correct": false, "explanation": "语义：开会不是用枪射击，“警察向天开会”语义不通。"}, {"text": "开花", "is_correct": false, "explanation": "语义：开花是植物的动作，与“警察”和“向天”不搭。"}, {"text": "开车", "is_correct": false, "explanation": "搭配：“开车”不能与“向天”搭配作为射击动作，句意不通。"}], "explanations": {"开枪": "开枪指用枪打出子弹，“警察向天开枪”表示鸣枪示警，与后文“大家都停下来了”相符。", "开会": "语义：开会不是用枪射击，“警察向天开会”语义不通。", "开花": "语义：开花是植物的动作，与“警察”和“向天”不搭。", "开车": "搭配：“开车”不能与“向天”搭配作为射击动作，句意不通。"}, "sentence_index": 0, "correct_answer": "开枪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这枚火箭开枪成功，飞上了天空。", "explanation": "这里应该用〈发射〉。开枪指用枪打出子弹，火箭升空要说“发射”。"}, {"text": "他拿起打火机，用力开枪。", "explanation": "这里应该用〈点火〉。打火机是用来让火燃起来的，不能用枪打出子弹。"}, {"text": "他拉弓开枪，一箭射中了目标。", "explanation": "这里应该用〈射箭〉。拉弓射箭用“射”，不能说“开枪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开枪", "is_correct": true, "explanation": "猎人看见鹿后用枪射击，“就开枪了”语义通顺。"}, {"text": "开学", "is_correct": false, "explanation": "语义：开学是学校的活动，与猎人和鹿无关。"}, {"text": "开花", "is_correct": false, "explanation": "语义：开花是植物的动作，与猎人看见鹿无关。"}, {"text": "开幕", "is_correct": false, "explanation": "语义：开幕指演出或会议的开始，与猎人看见鹿无关。"}], "explanations": {"开枪": "猎人看见鹿后用枪射击，“就开枪了”语义通顺。", "开学": "语义：开学是学校的活动，与猎人和鹿无关。", "开花": "语义：开花是植物的动作，与猎人看见鹿无关。", "开幕": "语义：开幕指演出或会议的开始，与猎人看见鹿无关。"}, "sentence_index": 6, "correct_answer": "开枪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不停地开枪，把饭菜都做好了。", "explanation": "开枪只指用枪打出子弹，不能用来做饭，这里误用了词义。"}, {"text": "老师在教室里开枪，讲解课文。", "explanation": "开枪不能用来讲课，这里误用了词义。"}, {"text": "他每天早上开枪，去公园跑步。", "explanation": "“开枪”不是锻炼身体的方式，这一句误用了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时开枪过，所以不怕枪声。", "corrected_sentence": "他年轻时开过枪，所以不怕枪声。", "error_description": "离合词错误：“开枪”中间可以插入“过”，应说“开过枪”，不能说“开枪过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他朝墙上开枪了一枪，墙上留下了一个弹孔。", "corrected_sentence": "他朝墙上开了一枪，墙上留下了一个弹孔。", "error_description": "离合词错误：“开枪”拆开后，“了”应放在“开”和“枪”之间，且“枪”不能重复，应说“开了一枪”，不能说“开枪了一枪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad2c49a5-b2f0-470e-ae6b-b16772a50848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
