INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "创办并经营企业的人。", "primary_collocate": null, "pronunciation": "qǐ yè jiā", "ipa": "tɕʰi˨˩˦ je˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "他二十岁就创办了公司，成了企业家。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位企业家创办的公司很成功。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位女企业家，自己经营一家工厂。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业家需要有好想法，也要敢做事。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老企业家办了三十年企业。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多企业家来学校给学生讲课。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位企业家一直在经营自己的小店。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想打工，想做一名企业家。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位企业家常把钱用在新的工厂上。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校请来一位有名的企业家。", "target_word": "企业家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "企业家精神", "label": "复合"}], "register": "中性", "sense_fingerprint": "创办并经营企业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0803c99c-fda8-4e16-9a88-b48c5c697e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：他二十岁已经创办了公司，“学生”的身份与此不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”与“创办了公司”没有关系，句子说不通。"}, {"text": "企业家", "is_correct": true, "explanation": "“创办了公司”的人就是创办并经营企业的人，与“企业家”一致。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：“他”是人，不能“成了”工厂，句意不通。"}], "explanations": {"学生": "语义：他二十岁已经创办了公司，“学生”的身份与此不符。", "病人": "语义：“病人”与“创办了公司”没有关系，句子说不通。", "企业家": "“创办了公司”的人就是创办并经营企业的人，与“企业家”一致。", "工厂": "语义：“他”是人，不能“成了”工厂，句意不通。"}, "sentence_index": 0, "correct_answer": "企业家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家企业家生产的电脑很多，卖到了很多国家。", "explanation": "量词“家”多用于公司、商店等机构，这里误用于指人的“企业家”，应改用量词“位”。"}, {"text": "他刚被公司录用，就成了一名企业家。", "explanation": "这里应该用〈员工〉。企业家是创办并经营企业的人，被公司录用的只是员工，不能用“企业家”。"}, {"text": "我们厂里新来了一头企业家。", "explanation": "这里应该用〈位〉。企业家指人，量词要用“位”；“头”多用于牛、猪等牲畜，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医生", "is_correct": false, "explanation": "语义：医生主要是给病人看病，与“经营自己的小店”不符。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手以唱歌为职业，与“经营自己的小店”不符。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“经营”要求经营者有经营能力，“小孩”与“经营小店”搭配不上。"}, {"text": "企业家", "is_correct": true, "explanation": "经营自己的小店，就是经营企业的人，与“企业家”一致。"}], "explanations": {"医生": "语义：医生主要是给病人看病，与“经营自己的小店”不符。", "歌手": "语义：歌手以唱歌为职业，与“经营自己的小店”不符。", "小孩": "搭配：“经营”要求经营者有经营能力，“小孩”与“经营小店”搭配不上。", "企业家": "经营自己的小店，就是经营企业的人，与“企业家”一致。"}, "sentence_index": 6, "correct_answer": "企业家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学毕业后就创办了一位企业家，大家都很佩服。", "explanation": "这里应该用〈公司〉。“创办”的对象是公司这类组织，不能创办一个人。"}, {"text": "周末我们去参观那位企业家，很有意思。", "explanation": "这里应该用〈工厂〉，量词也要从“位”改为“家”。“参观”针对工厂、展览这类地方，人不能作为参观的对象。"}, {"text": "他每天早上都喝企业家，很有营养。", "explanation": "这里应该用〈牛奶〉。“喝”的对象是饮料，企业家是人，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年被评为一棵年度企业家。", "corrected_sentence": "他去年被评为一位年度企业家。", "error_description": "量词错误：“企业家”指人，应用量词“位”；“棵”多用于树木等植物，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识一头经营工厂的企业家。", "corrected_sentence": "我认识一位经营工厂的企业家。", "error_description": "量词错误：“企业家”指人，应用量词“位”；“头”多用于牛、猪等牲畜，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
