INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94913, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94913, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "名人是很多人都认识的人。", "primary_collocate": null, "pronunciation": "míng rén", "ipa": "miŋ˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这位名人今天来我们学校了。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多名人都喜欢住在这个地方。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的歌手，现在成了名人。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在机场看见了一位名人。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名人也有自己的烦恼。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想成为名人，所以天天练习唱歌。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店常有名人来吃饭。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围着那位名人要签名。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友里有几个名人。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名人的一举一动，大家都很关心。", "target_word": "名人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名人堂", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多人都认识的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a252ca3-929a-4eff-b85c-7b311aaea147') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名人", "is_correct": true, "explanation": "名人指很多人都认识的人，可以用“这位”修饰，并且能够“来学校”。"}, {"text": "赌场", "is_correct": false, "explanation": "搭配：量词“位”只用于人，“赌场”是场所，不能说“这位赌场”。"}, {"text": "名声", "is_correct": false, "explanation": "语义：“名声”是抽象概念，不能自己“来学校”。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是建筑，不能被说成“这位”，也不能自己“来学校”。"}], "explanations": {"名人": "名人指很多人都认识的人，可以用“这位”修饰，并且能够“来学校”。", "赌场": "搭配：量词“位”只用于人，“赌场”是场所，不能说“这位赌场”。", "名声": "语义：“名声”是抽象概念，不能自己“来学校”。", "图书馆": "语义：图书馆是建筑，不能被说成“这位”，也不能自己“来学校”。"}, "sentence_index": 0, "correct_answer": "名人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去了一处著名的名人。", "explanation": "这里应该用〈名胜〉。名胜指风景名胜之地，“一处”用于地方，名人指人，不能用来指景点。"}, {"text": "这件衣服是名人。", "explanation": "这里应该用〈名牌〉。名牌指有名的品牌，名人指人，不能指衣服的牌子。"}, {"text": "这个产品的名人很好记。", "explanation": "这里应该用〈名称〉。名称指事物的叫法，名人指有名的人，不能用来指产品的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名人", "is_correct": true, "explanation": "名人是人，可以“来吃饭”，“常有”指经常有人光顾。"}, {"text": "黄金", "is_correct": false, "explanation": "语义：黄金是金属，不会来吃饭。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能进食，句意不通。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“来吃饭”要求有生命的主语，“雨水”不能与之搭配。"}], "explanations": {"名人": "名人是人，可以“来吃饭”，“常有”指经常有人光顾。", "黄金": "语义：黄金是金属，不会来吃饭。", "石头": "语义：石头不能进食，句意不通。", "雨水": "搭配：“来吃饭”要求有生命的主语，“雨水”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "名人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影是名人，大家都说值得一看。", "explanation": "这里应该用〈名作〉。名作指著名的作品，名人指有名的人，不能用来指电影。"}, {"text": "孔子的这段话是名人，大家都背过。", "explanation": "这里应该用〈名句〉。名句指著名的语句，名人指有名的人，不能用来指一段话。"}, {"text": "这首歌是名人，人人都会唱。", "explanation": "这里应该用〈名曲〉。名曲指著名的乐曲，名人指有名的人，不能用来指歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只名人昨天在电视台录了节目。", "corrected_sentence": "这位名人昨天在电视台录了节目。", "error_description": "量词错误：“这只名人”中的“只”用于动物，指人应用“位”或“个”，应说“这位名人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她上了一次电视，就变成了地名人。", "corrected_sentence": "她上了一次电视，就变成了名人。", "error_description": "助词错误：“地”用于修饰动词或形容词，名词“名人”前不能用，应说“就变成了名人”，去掉“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
