INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94929, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "惹是做了事让别人生气。", "primary_collocate": null, "pronunciation": "rě", "ipa": "ʐɤ˨˩˦", "syllable_count": 1, "sentences": [{"text": "别惹我，我今天心情不好。", "target_word": "惹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他生气了，你别惹他。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只狗很凶，小孩都不敢惹它。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟总爱惹姐姐生气。", "target_word": "惹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板今天不高兴，大家都不敢惹他。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说话这么难听，当然会惹别人不高兴。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我说错了一句话，没想到惹她生气了。", "target_word": "惹", "complexity_tier": "T3", "furigana": "wǒ shuō cuò le yí jù huà, méi xiǎng dào rě tā shēng qì le.", "sentence_source": "generated"}, {"text": "小明把同桌惹生气了，正在道歉。", "target_word": "惹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人脾气很大，谁也不想惹他。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开玩笑开过头，惹得朋友很不高兴。", "target_word": "惹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惹了", "label": "体标"}, {"form": "惹过", "label": "体标"}, {"form": "招惹", "label": "复合"}], "register": "口语", "sense_fingerprint": "惹：招惹某人，让对方生气或不高兴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fbe1663-1e8b-4cb8-871b-99d7fbafc682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惹", "is_correct": true, "explanation": "正确。“别惹我”指不要招惹我，与“我今天心情不好”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃我”。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”带的是衣物，不能以人作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，“煮我”不成立。"}], "explanations": {"惹": "正确。“别惹我”指不要招惹我，与“我今天心情不好”的语境相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃我”。", "穿": "配价：“穿”带的是衣物，不能以人作宾语。", "煮": "搭配：“煮”的对象是食物，“煮我”不成立。"}, "sentence_index": 0, "correct_answer": "惹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟总惹姐姐吃饭。", "explanation": "这里应该用〈劝〉。惹表示招惹、使人生气，不能表示劝人做事，劝姐姐吃饭要用〈劝〉。"}, {"text": "妈妈每天惹一顿丰盛的午饭。", "explanation": "这里应该用〈做〉。惹表示招惹、使人生气，不能用于做饭，做一顿饭要用〈做〉。"}, {"text": "他热情地惹客人。", "explanation": "这里应该用〈招待〉。惹表示招惹、使人生气，不能用于热情对待客人，热情招待客人要用〈招待〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惹", "is_correct": true, "explanation": "正确。“没想到惹她生气”指无意中招惹她，使她生气，与“说错了一句话”相符。"}, {"text": "夸", "is_correct": false, "explanation": "语义：夸人会使人高兴，与“说错了一句话”的因果关系矛盾。"}, {"text": "帮", "is_correct": false, "explanation": "语义：“帮”是帮助，不会使人生气，与前文的因果不合。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要受赠对象和物件，只带人作宾语，说“送她生气”不通。"}], "explanations": {"惹": "正确。“没想到惹她生气”指无意中招惹她，使她生气，与“说错了一句话”相符。", "夸": "语义：夸人会使人高兴，与“说错了一句话”的因果关系矛盾。", "帮": "语义：“帮”是帮助，不会使人生气，与前文的因果不合。", "送": "配价：“送”需要受赠对象和物件，只带人作宾语，说“送她生气”不通。"}, "sentence_index": 6, "correct_answer": "惹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈常惹宝宝睡觉。", "explanation": "这里应该用〈哄〉。惹表示招惹、使人生气，不能表示使人入睡，哄人入睡要用〈哄〉。"}, {"text": "我惹朋友吃了顿饭。", "explanation": "这里应该用〈请〉。惹表示招惹、使人生气，不能表示请客，请朋友吃饭要用〈请〉。"}, {"text": "我细心惹失落的朋友。", "explanation": "这里应该用〈安慰〉。惹表示招惹、使人生气，不能用于安慰他人，细心安慰失落的朋友要用〈安慰〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把她惹。", "corrected_sentence": "他把她惹生气了。", "error_description": "错误：“把”字句中，动词“惹”后必须有其他成分（如“生气了”），不能只说“把……惹”。正确：“他把她惹生气了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你把惹他生气。", "corrected_sentence": "你别惹他生气。", "error_description": "错误：“把”字句中，“把”后必须先接受事宾语，再接动词。“把惹”中“把”后直接接动词“惹”，缺少宾语，不成立。正确：“你别惹他生气。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
