INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94930, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引起不好的事情；招引。", "primary_collocate": null, "pronunciation": "rě", "ipa": "ʐɤ˨˩˦", "syllable_count": 1, "sentences": [{"text": "你别在外面惹事。", "target_word": "惹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这孩子老是惹麻烦，老师很头疼。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝多了酒，在街上惹出了大祸。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心点，别给自己惹来麻烦。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要乱说话，小心惹上麻烦。", "target_word": "惹", "complexity_tier": "T3", "furigana": "bú yào luàn shuō huà, xiǎo xīn rě shàng má fan.", "sentence_source": "generated"}, {"text": "他的一句玩笑话，惹出了不少麻烦。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想惹上官司，所以没有多说。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事是你惹的，你自己去解决。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居的狗乱叫，惹来了很多投诉。", "target_word": "惹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻时爱打架，惹过不少事。", "target_word": "惹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惹了", "label": "体标"}, {"form": "惹过", "label": "体标"}, {"form": "惹事", "label": "复合"}, {"form": "惹祸", "label": "复合"}], "register": "口语", "sense_fingerprint": "惹：引来麻烦、祸事等不好的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fbe1663-1e8b-4cb8-871b-99d7fbafc682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惹", "is_correct": true, "explanation": "正确。“惹事”指招来麻烦，与“别在外面”的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语多为衣物、身体等，不能说“洗事”。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说“煮事”。"}, {"text": "拍", "is_correct": false, "explanation": "配价：“拍”需要可拍打或拍摄的对象，与“事”搭配不通。"}], "explanations": {"惹": "正确。“惹事”指招来麻烦，与“别在外面”的语境相符。", "洗": "搭配：“洗”的宾语多为衣物、身体等，不能说“洗事”。", "煮": "搭配：“煮”的对象是食物，不能说“煮事”。", "拍": "配价：“拍”需要可拍打或拍摄的对象，与“事”搭配不通。"}, "sentence_index": 0, "correct_answer": "惹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次努力为我们惹来了一本词典。", "explanation": "这里应该用〈赢得〉。惹表示引来麻烦、祸事等，不能用于获得物品，获得奖品要用〈赢得〉。"}, {"text": "工厂每天惹大量的零件。", "explanation": "这里应该用〈制造〉。惹指引来麻烦、祸事等不好的结果，不能用于生产零件，制造零件要用〈制造〉。"}, {"text": "我们诚挚地惹你参加。", "explanation": "这里应该用〈邀请〉。惹指引来麻烦、祸事等不好的结果，不能用于邀请他人，邀请别人参加要用〈邀请〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惹", "is_correct": true, "explanation": "正确。“惹上官司”指招来官司，与“没有多说”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“官司”作宾语，说“唱上官司”不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮料等，不能说“喝上官司”。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”指编织，与“官司”无关，句意不通。"}], "explanations": {"惹": "正确。“惹上官司”指招来官司，与“没有多说”的语境相符。", "唱": "搭配：“唱”不能带“官司”作宾语，说“唱上官司”不通。", "喝": "搭配：“喝”的宾语应是饮料等，不能说“喝上官司”。", "织": "语义：“织”指编织，与“官司”无关，句意不通。"}, "sentence_index": 6, "correct_answer": "惹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他通过努力惹来了一辆自行车。", "explanation": "这里应该用〈得到〉。惹表示引来麻烦、祸事等，不能用于获得物品，通过努力得到物品要用〈得到〉。"}, {"text": "他在比赛中惹了很大的进步。", "explanation": "这里应该用〈取得〉。惹指引来麻烦、祸事等不好的结果，不能用于进步，取得进步要用〈取得〉。"}, {"text": "我很惹你的帮助。", "explanation": "这里应该用〈感谢〉。惹指引来麻烦、祸事等不好的结果，不能用于表达感激，感谢别人的帮助要用〈感谢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一不小心惹了上麻烦。", "corrected_sentence": "他一不小心惹上了麻烦。", "error_description": "错误：结果补语“上”应紧跟在“惹”后，“了”应放在“上”之后。“了”放在了“上”之前，不能说“惹了上麻烦”。正确：“惹上了麻烦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这孩子从来惹不事。", "corrected_sentence": "这孩子从来不惹事。", "error_description": "错误：否定词“不”应放在“惹”前，说“从来不惹事”，不能放在动词之后。正确：“这孩子从来不惹事。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
