INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94943, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "斗是两个人互相比谁厉害。", "primary_collocate": null, "pronunciation": "dòu", "ipa": "tou˥˩", "syllable_count": 1, "sentences": [{"text": "我们来斗一斗，看谁跑得快。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想跟我斗，可是斗不过我。", "target_word": "斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人斗了半天，还是分不出高低。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥和弟弟斗力气，谁也赢不了谁。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你俩别吵了，到场上斗一斗吧。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不服气，非要跟我斗个高低。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个厨师斗了一场，评委说平手。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老同学见面就爱斗，每次都要比个输赢。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不跟你斗了，反正你比我厉害。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个选手斗得很激烈，不分上下。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "斗了", "label": "体标"}, {"form": "斗过", "label": "体标"}, {"form": "斗一斗", "label": "重叠"}, {"form": "鬥", "label": "繁体"}], "register": "口语", "sense_fingerprint": "斗：两人互相比试，看谁更强、更厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fbe1663-1e8b-4cb8-871b-99d7fbafc682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "斗", "is_correct": true, "explanation": "斗（dòu）指两人互相比试、看谁更强，是本词的正确答案。"}, {"text": "抖", "is_correct": false, "explanation": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“抖动”。"}, {"text": "陡", "is_correct": false, "explanation": "dǒu（第三声）与 dòu 声调不同，意思是“陡峭”。"}, {"text": "透", "is_correct": false, "explanation": "tòu（第四声）与 dòu 只有声母不同（t 与 d），意思是“穿过、透明”。"}], "explanations": {"斗": "斗（dòu）指两人互相比试、看谁更强，是本词的正确答案。", "抖": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“抖动”。", "陡": "dǒu（第三声）与 dòu 声调不同，意思是“陡峭”。", "透": "tòu（第四声）与 dòu 只有声母不同（t 与 d），意思是“穿过、透明”。"}, "sentence_index": null, "correct_answer": "斗"}, "level_3": {"options": [{"text": "吃一吃", "is_correct": false, "explanation": "语义：“吃一吃”与“看谁跑得快”的比试内容不合，句子说不通。"}, {"text": "睡一睡", "is_correct": false, "explanation": "语义：“睡一睡”与“看谁跑得快”的比试内容不合，句子说不通。"}, {"text": "斗一斗", "is_correct": true, "explanation": "斗一斗：两人比试一下，与“看谁跑得快”相符，是句中的形式。"}, {"text": "写一写", "is_correct": false, "explanation": "语义：“写一写”不是比试的动作，与“看谁跑得快”的语境不合。"}], "explanations": {"吃一吃": "语义：“吃一吃”与“看谁跑得快”的比试内容不合，句子说不通。", "睡一睡": "语义：“睡一睡”与“看谁跑得快”的比试内容不合，句子说不通。", "斗一斗": "斗一斗：两人比试一下，与“看谁跑得快”相符，是句中的形式。", "写一写": "语义：“写一写”不是比试的动作，与“看谁跑得快”的语境不合。"}, "sentence_index": 0, "correct_answer": "斗一斗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直在斗孩子玩，孩子笑个不停。", "explanation": "这里应该用〈逗〉。“逗”表示逗弄、哄人开心，与“斗”同音但意思不同。"}, {"text": "他斗着一袋米，慢慢走进了屋子。", "explanation": "这里应该用〈扛〉。斗表示两人互相比试，不能表示扛、抬东西。"}, {"text": "他斗了一本小说，一天就看完了。", "explanation": "这里应该用〈读〉。斗表示两人互相比试，不能用于读书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94943, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "斗", "is_correct": true, "explanation": "斗（dòu）指两人互相比试、看谁更强，是本词的正确答案。"}, {"text": "都", "is_correct": false, "explanation": "dōu（第一声）与 dòu 声调不同，意思是“全部、都”。"}, {"text": "兜", "is_correct": false, "explanation": "dōu（第一声）与 dòu 声调不同，意思是“口袋、兜子”。"}, {"text": "抖", "is_correct": false, "explanation": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“抖动”。"}], "explanations": {"斗": "斗（dòu）指两人互相比试、看谁更强，是本词的正确答案。", "都": "dōu（第一声）与 dòu 声调不同，意思是“全部、都”。", "兜": "dōu（第一声）与 dòu 声调不同，意思是“口袋、兜子”。", "抖": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“抖动”。"}, "sentence_index": null, "correct_answer": "斗"}, "level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能与“一场”搭配表示比试，“煮了一场”说不通。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是操作食材的动作，与“一场”“平手”的比试语境不合。"}, {"text": "揉", "is_correct": false, "explanation": "语义：“揉”是按压的动作，不能表示两个厨师之间的比试。"}, {"text": "斗", "is_correct": true, "explanation": "斗：两个厨师互相比试，与“一场”“评委说平手”相符。"}], "explanations": {"煮": "搭配：“煮”不能与“一场”搭配表示比试，“煮了一场”说不通。", "切": "语义：“切”是操作食材的动作，与“一场”“平手”的比试语境不合。", "揉": "语义：“揉”是按压的动作，不能表示两个厨师之间的比试。", "斗": "斗：两个厨师互相比试，与“一场”“评委说平手”相符。"}, "sentence_index": 6, "correct_answer": "斗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她斗了斗头发上的雪，走进屋里。", "explanation": "这里应该用〈抖〉。“抖”表示振动，“斗”没有这个意思。"}, {"text": "这两个选手斗得很亲热，一直互相帮忙。", "explanation": "这里应该用〈合作〉。“斗”指两人互相比高低，两人亲热、互相帮忙要说“合作”，不能用“斗”。"}, {"text": "这段山路很斗，我们走了一下午。", "explanation": "这里应该用〈陡〉。“斗”没有陡峭的意思，形容山路险峻要说“陡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两人为了比个高低，斗下来了。", "corrected_sentence": "两人为了比个高低，斗起来了。", "error_description": "“斗”表示开始互相争斗，要用“起来”作补语；“下来”不表示这个意思，应说“斗起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个老同学斗热火朝天，谁也不肯服输。", "corrected_sentence": "两个老同学斗得热火朝天，谁也不肯服输。", "error_description": "“斗”后面表示状态的补语要用“得”连接，应说“斗得热火朝天”，省掉“得”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
