INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94944, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对打，争斗：人或动物互相打斗。", "primary_collocate": null, "pronunciation": "dòu", "ipa": "tou˥˩", "syllable_count": 1, "sentences": [{"text": "两只公鸡在院子里斗起来了。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别斗了，小心受伤。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那两只狗为了一根骨头斗得很凶。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个男孩在街上斗了起来，老师马上去看。", "target_word": "斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两只蛐蛐一放进盆里就斗。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩为了一点小事，斗了好几年。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗不怕大狗，敢跟它斗。", "target_word": "斗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们两个人一见面就斗，谁也不让谁。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公牛斗得满身是汗，还不肯停。", "target_word": "斗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两只猫在墙上斗着，叫声很大。", "target_word": "斗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "斗了", "label": "体标"}, {"form": "斗过", "label": "体标"}, {"form": "斗一斗", "label": "重叠"}, {"form": "斗争", "label": "复合"}, {"form": "鬥", "label": "繁体"}], "register": "口语", "sense_fingerprint": "斗：人或动物互相打斗、争斗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 蛐 (Zipf 2.12), 蛐 (Zipf 2.12)']::text[], '9fbe1663-1e8b-4cb8-871b-99d7fbafc682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "斗", "is_correct": true, "explanation": "斗（dòu）指两方相互打斗、争斗，与句中“斗起来了”的意思相符。"}, {"text": "抖", "is_correct": false, "explanation": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“抖动”，与争斗无关。"}, {"text": "都", "is_correct": false, "explanation": "dōu（第一声）与 dòu 声调不同，意思是“全部、都”。"}, {"text": "透", "is_correct": false, "explanation": "tòu（第四声）与 dòu 只有声母不同（t 与 d），意思是“穿过、透明”。"}], "explanations": {"斗": "斗（dòu）指两方相互打斗、争斗，与句中“斗起来了”的意思相符。", "抖": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“抖动”，与争斗无关。", "都": "dōu（第一声）与 dòu 声调不同，意思是“全部、都”。", "透": "tòu（第四声）与 dòu 只有声母不同（t 与 d），意思是“穿过、透明”。"}, "sentence_index": null, "correct_answer": "斗"}, "level_3": {"options": [{"text": "读", "is_correct": false, "explanation": "语义：公鸡不会“读”，句子说的是公鸡之间的打斗。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧起来”多用于火势，不能用来说两只公鸡。"}, {"text": "斗", "is_correct": true, "explanation": "斗：两只公鸡互相打斗，与“起来了”搭配，意思通顺。"}, {"text": "写", "is_correct": false, "explanation": "语义：公鸡不会“写”，与院子里打架的情景不合。"}], "explanations": {"读": "语义：公鸡不会“读”，句子说的是公鸡之间的打斗。", "烧": "搭配：“烧起来”多用于火势，不能用来说两只公鸡。", "斗": "斗：两只公鸡互相打斗，与“起来了”搭配，意思通顺。", "写": "语义：公鸡不会“写”，与院子里打架的情景不合。"}, "sentence_index": 0, "correct_answer": "斗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上在公园里斗太极拳，身体越来越好。", "explanation": "这里应该用〈练〉。斗指人与人之间的争斗或比试，练太极拳不是对抗，不能说“斗太极拳”。"}, {"text": "他用棍子斗了球。", "explanation": "这里应该用〈打〉。“斗”表示人或动物之间的争斗，不能用来指击打球。"}, {"text": "他斗了一碗面条，吃得很香。", "explanation": "这里应该用〈吃〉。斗表示争斗或比试，不能用来指吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94944, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "斗", "is_correct": true, "explanation": "斗（dòu）指两方相互打斗、争斗，是本词的正确答案。"}, {"text": "陡", "is_correct": false, "explanation": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“陡峭”。"}, {"text": "兜", "is_correct": false, "explanation": "dōu（第一声）与 dòu 声调不同，意思是“口袋、兜子”。"}, {"text": "抖", "is_correct": false, "explanation": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“抖动”。"}], "explanations": {"斗": "斗（dòu）指两方相互打斗、争斗，是本词的正确答案。", "陡": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“陡峭”。", "兜": "dōu（第一声）与 dòu 声调不同，意思是“口袋、兜子”。", "抖": "dǒu（第三声）与 dòu（第四声）声调不同，意思是“抖动”。"}, "sentence_index": null, "correct_answer": "斗"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：“写”与“跟它”搭配不通，句子读来不通。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“跟它哭”不能这样组合，“哭”不用于这种对抗的语境。"}, {"text": "斗", "is_correct": true, "explanation": "斗：小狗敢跟大狗对抗，与“不怕”的语境相符。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”表示避开，与“敢”的意思冲突。"}], "explanations": {"写": "语义：“写”与“跟它”搭配不通，句子读来不通。", "哭": "搭配：“跟它哭”不能这样组合，“哭”不用于这种对抗的语境。", "斗": "斗：小狗敢跟大狗对抗，与“不怕”的语境相符。", "躲": "语义：“躲”表示避开，与“敢”的意思冲突。"}, "sentence_index": 6, "correct_answer": "斗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他斗了斗身上的雨水，然后走进屋里。", "explanation": "这里应该用〈抖〉。“抖”表示振动使东西落下，“斗”没有这个意思。"}, {"text": "这个孩子很斗，总能让大家笑个不停。", "explanation": "这里应该用〈逗〉。“逗”表示逗乐、使人发笑，“斗”是争斗或比试的意思，不能表示逗乐。"}, {"text": "他们俩斗得很有默契，配合得天衣无缝。", "explanation": "这里应该用〈合作〉。“斗”表示争斗、对抗，两人默契配合要说“合作”，不能用“斗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnin