INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有意思是让人觉得好玩，想看想听。", "primary_collocate": null, "pronunciation": "yǒu yì si", "ipa": "joʊ˨˩˦ i˥˩ sɨ", "syllable_count": 3, "sentences": [{"text": "这个动画片真有意思，孩子们看得很开心。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑话很有意思，我听了哈哈大笑。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的比赛太有意思了，我一直看着电视。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目有意思极了，我每周都看。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友给我讲了一件有意思的事。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话很有意思，我最爱听她讲故事。", "target_word": "有意思", "complexity_tier": "T3", "furigana": "tā shuō huà hěn yǒu yì si, wǒ zuì ài tīng tā jiǎng gùshi.", "sentence_source": "generated"}, {"text": "这首歌很有意思，歌词又好玩又好听。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的表演很有意思，很多人停下来看。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行中有什么有意思的事吗？", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个广播节目挺有意思，我天天上班路上听。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "好玩、让人想看想听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87abf8b-582d-4fb7-b060-3655ca7a7a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确答案。yǒu yì si 的意思是好玩、让人想看想听。"}, {"text": "有意识", "is_correct": false, "explanation": "shí（第二声）与 sī 声母不同（sh 与 s），意思是有意识、自觉。"}, {"text": "有意义", "is_correct": false, "explanation": "第三个音节 yi 与 si 声母不同，意思是有价值、有意义。"}, {"text": "有意志", "is_correct": false, "explanation": "zhì（第四声）与 si 声母不同（zh 与 s），意思是有决心、有毅力。"}], "explanations": {"有意思": "正确答案。yǒu yì si 的意思是好玩、让人想看想听。", "有意识": "shí（第二声）与 sī 声母不同（sh 与 s），意思是有意识、自觉。", "有意义": "第三个音节 yi 与 si 声母不同，意思是有价值、有意义。", "有意志": "zhì（第四声）与 si 声母不同（zh 与 s），意思是有决心、有毅力。"}, "sentence_index": null, "correct_answer": "有意思"}, "level_3": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确。“真有意思”说动画好玩，与“孩子们看得很开心”一致。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”说内容单调，与“孩子们看得很开心”矛盾。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”说没意思，与“孩子们看得很开心”矛盾。"}, {"text": "乏味", "is_correct": false, "explanation": "语域：“乏味”偏书面，且与“孩子们看得很开心”矛盾。"}], "explanations": {"有意思": "正确。“真有意思”说动画好玩，与“孩子们看得很开心”一致。", "枯燥": "语义：“枯燥”说内容单调，与“孩子们看得很开心”矛盾。", "无聊": "语义：“无聊”说没意思，与“孩子们看得很开心”矛盾。", "乏味": "语域：“乏味”偏书面，且与“孩子们看得很开心”矛盾。"}, "sentence_index": 0, "correct_answer": "有意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每天喝够水，对身体很有意思。", "explanation": "这里应该用〈有益〉。有意思指有趣，说对身体、对人有好处要用〈有益〉。"}, {"text": "这次改革很有意思，半年过去了，公司的业绩一点也没提高。", "explanation": "这里应该用〈有成效〉。有意思指好玩，说改革、措施的成果要用〈有成效〉。"}, {"text": "他为救落水的孩子牺牲了自己，这件事很有意思。", "explanation": "这里应该用〈有意义〉。有意思指好玩，说重大事件、行为的价值要用〈有意义〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确。“很有意思”说歌有趣，与“又好玩又好听”一致。"}, {"text": "难听", "is_correct": false, "explanation": "语义：“难听”说声音不好听，与“又好听”矛盾。"}, {"text": "刺耳", "is_correct": false, "explanation": "搭配：“刺耳”多形容声音尖利，与“又好听”矛盾。"}, {"text": "单调", "is_correct": false, "explanation": "语义：“单调”说内容变化少，与“又好玩”矛盾。"}], "explanations": {"有意思": "正确。“很有意思”说歌有趣，与“又好玩又好听”一致。", "难听": "语义：“难听”说声音不好听，与“又好听”矛盾。", "刺耳": "搭配：“刺耳”多形容声音尖利，与“又好听”矛盾。", "单调": "语义：“单调”说内容变化少，与“又好玩”矛盾。"}, "sentence_index": 6, "correct_answer": "有意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药很有意思，吃了两天病也没好。", "explanation": "这里应该用〈有效〉。有意思指好玩，说药物、治疗的效果要用〈有效〉。"}, {"text": "这次培训很有意思，我们听完一遍，却一点知识也没有学到。", "explanation": "这里应该用〈有价值〉。有意思指好玩，说培训、课程对人的收获要用〈有价值〉。"}, {"text": "这笔钱对他很有意思，帮他还清了所有的债。", "explanation": "这里应该用〈有帮助〉。有意思指有趣，说钱财对人的帮助要用〈有帮助〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
