INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有趣味，能引起兴趣。", "primary_collocate": null, "pronunciation": "yǒu yì si", "ipa": "joʊ˨˩˦ i˥˩ sɨ", "syllable_count": 3, "sentences": [{"text": "这本书很有意思，我一口气看完了。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲的故事特别有意思，大家都爱听。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影不太有意思，我看到一半就睡了。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的课很有意思，同学们都不想下课。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得学中文很有意思，每天都想学。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏真有意思，我玩了一个晚上。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个很有意思的人，总能让大家笑起来。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去山里走走，一定很有意思。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题很有意思，我们一起想想吧。", "target_word": "有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本杂志里的文章都很有意思，我常常看。", "target_word": "有意思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "有趣味、能引起兴趣的事物或人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87abf8b-582d-4fb7-b060-3655ca7a7a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确答案。yǒu yì si 的意思是有趣、能引起兴趣。"}, {"text": "有意识", "is_correct": false, "explanation": "shí（第二声）与 sī 声母不同（sh 与 s），意思是有意识、自觉。"}, {"text": "有意义", "is_correct": false, "explanation": "第三个音节 yi 与 si 声母不同，意思是有价值、有意义。"}, {"text": "有意志", "is_correct": false, "explanation": "zhì（第四声）与 si 声母不同（zh 与 s），意思是有决心、有毅力。"}], "explanations": {"有意思": "正确答案。yǒu yì si 的意思是有趣、能引起兴趣。", "有意识": "shí（第二声）与 sī 声母不同（sh 与 s），意思是有意识、自觉。", "有意义": "第三个音节 yi 与 si 声母不同，意思是有价值、有意义。", "有意志": "zhì（第四声）与 si 声母不同（zh 与 s），意思是有决心、有毅力。"}, "sentence_index": null, "correct_answer": "有意思"}, "level_3": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确。“很有意思”说书有趣，与“一口气看完了”的投入相符。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”说没意思，与“一口气看完了”的投入矛盾。"}, {"text": "乏味", "is_correct": false, "explanation": "语域：“乏味”偏书面，且与“一口气看完了”的投入矛盾。"}, {"text": "沉闷", "is_correct": false, "explanation": "搭配：“沉闷”多形容气氛、环境，很少用来形容书，且与“一口气看完了”矛盾。"}], "explanations": {"有意思": "正确。“很有意思”说书有趣，与“一口气看完了”的投入相符。", "无聊": "语义：“无聊”说没意思，与“一口气看完了”的投入矛盾。", "乏味": "语域：“乏味”偏书面，且与“一口气看完了”的投入矛盾。", "沉闷": "搭配：“沉闷”多形容气氛、环境，很少用来形容书，且与“一口气看完了”矛盾。"}, "sentence_index": 0, "correct_answer": "有意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了给父亲治病，他卖掉了房子，这件事很有意思。", "explanation": "这里应该用〈有意义〉。有意思指有趣，说人生中重大的、有分量的事情时要用〈有意义〉。"}, {"text": "这种药很有意思，吃了两天病就好了。", "explanation": "这里应该用〈有效〉。有意思指有趣，说药物、治疗的效果要用〈有效〉。"}, {"text": "每天锻炼一小时，对身体很有意思。", "explanation": "这里应该用〈有益〉。有意思指有趣，说对身体、对人有好处要用〈有益〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有意思", "is_correct": true, "explanation": "正确。“很有意思的人”说人风趣，与“总能让大家笑起来”相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”说人态度冷漠，与“总能让大家笑起来”相反。"}, {"text": "木讷", "is_correct": false, "explanation": "语域：“木讷”偏书面，且说人不善言辞，与“总能让大家笑起来”矛盾。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：“呆板”说人死板、不活泼，与“总能让大家笑起来”矛盾。"}], "explanations": {"有意思": "正确。“很有意思的人”说人风趣，与“总能让大家笑起来”相符。", "冷淡": "语义：“冷淡”说人态度冷漠，与“总能让大家笑起来”相反。", "木讷": "语域：“木讷”偏书面，且说人不善言辞，与“总能让大家笑起来”矛盾。", "呆板": "语义：“呆板”说人死板、不活泼，与“总能让大家笑起来”矛盾。"}, "sentence_index": 6, "correct_answer": "有意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场降雨对庄稼很有意思，地里的收成比去年多了一半。", "explanation": "这里应该用〈有利〉。有意思指有趣，说天气、自然条件对庄稼的好处要用〈有利〉。"}, {"text": "这次投资很有意思，公司一分钱也没有赚到。", "explanation": "这里应该用〈有价值〉。有意思指有趣，说投资、工作的回报和值得性要用〈有价值〉。"}, {"text": "这把剪刀很有意思，剪了两下就断了，根本用不了。", "explanation": "这里应该用〈有用〉。有意思指有趣，说工具、物品的作用要用〈有用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在图书馆找到一本很有意思书。", "corrected_sentence": "我在图书馆找到一本很有意思的书。", "error_description": "“很有意思”修饰名词时，后面要加“的”，应说“很有意思的书”，不能说“很有意思书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他觉得学中文是一件很有意思事，每天都想学。", "corrected_sentence": "他觉得学中文是一件很有意思的事，每天都想学。", "error_description": "“很有意思”修饰名词“事”时，中间要加“的”，应说“很有意思的事”，不能说“很有意思事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穷", "is_correct": true, "explanation": "穷：与“有钱”意思相反，指缺少钱财，是“有钱”的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力，与“有钱”的各个义项都没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“有钱”没有反义关系。"}, {"text": "快乐", "is_correct": false, "explanation": "“快乐”形容心情，与“有钱”没有反义关系。"}], "correct_answer": "穷", "explanations": {"穷": "穷：与“有钱”意思相反，指缺少钱财，是“有钱”的反义词。", "聪明": "“聪明”形容智力，与“有钱”的各个义项都没有反义关系。", "安静": "“安静”形容声音或环境，与“有钱”没有反义关系。", "快乐": "“快乐”形容心情，与“有钱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
