INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "拥有许多财产，富裕。", "primary_collocate": null, "pronunciation": "yǒu qián", "ipa": "joʊ̯˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他家很有钱。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老板非常有钱。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不是很有钱，但是很快乐。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有钱的人不一定幸福。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸很有钱，开了三家公司。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前不太有钱，现在有钱了。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住大房子的人，一定很有钱吗？", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里有钱的家庭很多。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他很有钱，可是总坐公共汽车。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看上去很有钱，穿着名牌衣服。", "target_word": "有钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有钱人", "label": "复合"}, {"form": "有钱了", "label": "体标（变化）"}], "register": "中性", "sense_fingerprint": "拥有许多财产，生活富裕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0d37556-ca61-4ff7-a93f-9f6b9ec23596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有钱", "is_correct": true, "explanation": "有钱：拥有许多钱财，即富裕。"}, {"text": "有闲", "is_correct": false, "explanation": "xián（第二声）与 qián（第二声）声母不同（x/q），意思是有空闲，不是有钱财。"}, {"text": "有权", "is_correct": false, "explanation": "quán 与 qián 介音不同（u/i），意思是有权力，不是有钱财。"}, {"text": "有枪", "is_correct": false, "explanation": "qiāng（第一声）与 qián（第二声）韵母与声调都不同，意思是拥有枪支。"}, {"text": "有情", "is_correct": false, "explanation": "qíng 与 qián 韵母不同（ing/ian），意思是有感情、有情义。"}], "explanations": {"有钱": "有钱：拥有许多钱财，即富裕。", "有闲": "xián（第二声）与 qián（第二声）声母不同（x/q），意思是有空闲，不是有钱财。", "有权": "quán 与 qián 介音不同（u/i），意思是有权力，不是有钱财。", "有枪": "qiāng（第一声）与 qián（第二声）韵母与声调都不同，意思是拥有枪支。", "有情": "qíng 与 qián 韵母不同（ing/ian），意思是有感情、有情义。"}, "sentence_index": null, "correct_answer": "有钱"}, "level_3": {"options": [{"text": "有钱", "is_correct": true, "explanation": "“他家很有钱”中，“有钱”作谓语，描述一户人家经济富裕，语义和搭配都正确。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说智力，与“有钱”的经济含义不符。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”是人的心理表现，一户人家不会害羞。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度，不能用来评价一户人家的经济状况。"}], "explanations": {"有钱": "“他家很有钱”中，“有钱”作谓语，描述一户人家经济富裕，语义和搭配都正确。", "聪明": "语义：“聪明”说智力，与“有钱”的经济含义不符。", "害羞": "语义：“害羞”是人的心理表现，一户人家不会害羞。", "冷": "语义：“冷”说温度，不能用来评价一户人家的经济状况。"}, "sentence_index": 0, "correct_answer": "有钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的生活很有钱。", "explanation": "这里应该用〈富裕〉。“有钱”说人或家庭手里的钱多，描写地区和生活水平要用“富裕”。"}, {"text": "农民的日子越来越有钱了。", "explanation": "这里应该用〈富足〉。“有钱”指个人或家庭的钱多，不用来描述日子、生活状况的充裕程度。"}, {"text": "他的精神世界很有钱。", "explanation": "这里应该用〈富有〉。“富有”可以用于精神世界、内容等抽象方面，“有钱”只指手里的钱多，不能用来形容精神世界。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有钱", "is_correct": true, "explanation": "有钱：手里的钱很多。"}, {"text": "有权", "is_correct": false, "explanation": "quán 与 qián 介音不同（u/i），意思是有权力。"}, {"text": "油钱", "is_correct": false, "explanation": "yóu（第二声）与 yǒu（第三声）声调不同，“油钱”指买油、加油的钱。"}, {"text": "右前", "is_correct": false, "explanation": "yòu（第四声）与 yǒu（第三声）声调不同，意思是右边的前方。"}], "explanations": {"有钱": "有钱：手里的钱很多。", "有权": "quán 与 qián 介音不同（u/i），意思是有权力。", "油钱": "yóu（第二声）与 yǒu（第三声）声调不同，“油钱”指买油、加油的钱。", "右前": "yòu（第四声）与 yǒu（第三声）声调不同，意思是右边的前方。"}, "sentence_index": null, "correct_answer": "有钱"}, "level_3": {"options": [{"text": "有钱", "is_correct": true, "explanation": "“住大房子的人，一定很有钱吗？”中，“有钱”与“住大房子”相呼应，表示经济状况，语义和搭配都正确。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不用来形容人。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场所或场面，不用来形容人。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”说身材，与“住大房子”没有关系，语义不搭。"}], "explanations": {"有钱": "“住大房子的人，一定很有钱吗？”中，“有钱”与“住大房子”相呼应，表示经济状况，语义和搭配都正确。", "宽敞": "搭配：“宽敞”形容空间，不用来形容人。", "热闹": "搭配：“热闹”形容场所或场面，不用来形容人。", "胖": "体貌：“胖”说身材，与“住大房子”没有关系，语义不搭。"}, "sentence_index": 6, "correct_answer": "有钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家酒店的大厅很有钱。", "explanation": "这里应该用〈豪华〉。“有钱”只说人或家庭手里钱多，不用来形容大厅的装修和档次。"}, {"text": "这位老教授的知识很有钱。", "explanation": "这里应该用〈渊博〉。“渊博”形容知识丰富，“有钱”只说手里的钱多，不能用来形容知识。"}, {"text": "这位老先生说话很有钱。", "explanation": "这里应该用〈幽默〉。“幽默”形容说话风趣，“有钱”只说人或家庭手里的钱多，不能用来形容说话的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅没很有钱，但是很快乐。", "corrected_sentence": "我舅舅不太有钱，但是很快乐。", "error_description": "错误在否定词：“有钱”作形容词谓语时，否定要用“不”，“没”不用于形容词谓语。“没很有钱”应改为“不太有钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的有钱，朋友很多。", "corrected_sentence": "他很有钱，朋友很多。", "error_description": "结构错误：“的”用在“有钱”前会把它变成定语，作谓语时应在前面加程度副词“很”。“他的有钱”应改为“他很有钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94959, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
