INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94959, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检察是认真查看有没有人犯法。", "primary_collocate": null, "pronunciation": "jiǎn chá", "ipa": "tɕjɛn˨˩˦ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "他们要检察这家公司有没有偷税。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人说他受贿，专门的人员来检察这件事。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家派人检察那些官员有没有违法。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们认真检察了每一笔钱，没有发现问题。", "target_word": "检察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工作人员检察过很多案子。", "target_word": "检察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人举报工厂排污，他们马上检察这家工厂。", "target_word": "检察", "complexity_tier": "T3", "furigana": "yǒu rén jǔbào gōngchǎng páiwū, tāmen mǎshàng jiǎnchá zhè jiā gōngchǎng.", "sentence_source": "generated"}, {"text": "他们仔细检察着这家银行的每一笔交易。", "target_word": "检察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了公平，有人专门检察选举有没有作弊。", "target_word": "检察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民举报小区乱建房，有关部门马上检察这些房子。", "target_word": "检察", "complexity_tier": "T3", "furigana": "shìmín jǔbào xiǎoqū luàn jiàn fáng, yǒuguān bùmén mǎshàng jiǎnchá zhèxiē fángzi.", "sentence_source": "generated"}, {"text": "谁来检察这些人有没有犯法呢？", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "检察了", "label": "体标"}, {"form": "检察过", "label": "体标"}, {"form": "检察着", "label": "体标"}], "register": "书面", "sense_fingerprint": "认真查看有没有人犯法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87abf8b-582d-4fb7-b060-3655ca7a7a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检察", "is_correct": true, "explanation": "正确。“要检察……有没有偷税”指查看是否违法，与语境一致。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”是不去注意，与“要……有没有偷税”的查看目的矛盾。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”要带节日、胜利之类的事件作宾语，不能接“有没有偷税”。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是夸奖，与“有没有偷税”的查看内容矛盾。"}], "explanations": {"检察": "正确。“要检察……有没有偷税”指查看是否违法，与语境一致。", "忽视": "语义：“忽视”是不去注意，与“要……有没有偷税”的查看目的矛盾。", "庆祝": "搭配：“庆祝”要带节日、胜利之类的事件作宾语，不能接“有没有偷税”。", "表扬": "语义：“表扬”是夸奖，与“有没有偷税”的查看内容矛盾。"}, "sentence_index": 0, "correct_answer": "检察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂每天都要检察零件的尺寸。", "explanation": "这里应该用〈检验〉。检察指查看有没有违法行为，零件尺寸、产品质量要用〈检验〉。"}, {"text": "总统检察了仪仗队，士兵们都很精神。", "explanation": "这里应该用〈检阅〉。检察指查看有没有违法行为，检阅指检查队伍、列队。"}, {"text": "医生检察了我的身体，说一切正常。", "explanation": "这里应该用〈检查〉。检察指查看有没有违法行为，身体健康状况要用〈检查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检察", "is_correct": true, "explanation": "正确。“仔细检察着”指认真查看，与语境一致。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏美好的事物，与“仔细……每一笔交易”的查看矛盾。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的宾语多是物品或场所，不能接“交易”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“仔细”相反，与句意矛盾。"}], "explanations": {"检察": "正确。“仔细检察着”指认真查看，与语境一致。", "欣赏": "语义：“欣赏”是赞赏美好的事物，与“仔细……每一笔交易”的查看矛盾。", "装饰": "搭配：“装饰”的宾语多是物品或场所，不能接“交易”。", "忘记": "语义：“忘记”与“仔细”相反，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "检察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人每天都要检察车间的温度，并把数字记在表格上。", "explanation": "这里应该用〈检测〉。检察指查看有没有违法行为，温度等数值的测量要用〈检测〉。"}, {"text": "工人们每周都要检察设备，防止出故障。", "explanation": "这里应该用〈检修〉。检察指查看有没有违法行为，设备的维护检查要用〈检修〉。"}, {"text": "计量员每年都要检察这台秤，保证准确。", "explanation": "这里应该用〈检定〉。检察指查看有没有违法行为，计量仪器的准确度要用〈检定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们检察很仔细，没有漏掉任何一笔。", "corrected_sentence": "他们检察得很仔细，没有漏掉任何一笔。", "error_description": "“检察”后带状态补语时要用“得”连接，应说“检察得很仔细”，不能说“检察很仔细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海关没有检察出了任何违法的物品。", "corrected_sentence": "海关没有检察出任何违法的物品。", "error_description": "否定句用“没有”时，句中不能再用“了”，应说“没有检察出任何违法的物品”，不能说“没有检察出了任何违法的物品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
