INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检查并审查是否有违法行为。", "primary_collocate": null, "pronunciation": "jiǎn chá", "ipa": "tɕjɛn˨˩˦ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "有关部门要检察这批货有没有违法。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们来检察这家店的卫生和价格，看有没有违法。", "target_word": "检察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子需要专门的人员再检察一遍。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经检察了这个公司的所有合同。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保证安全，他们要检察每家工厂有没有违法。", "target_word": "检察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在检察市场上有没有假货。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的账目每年都要检察。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们检察工厂是否违法排放污水。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们没有检察出任何违法的事。", "target_word": "检察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸说有人正在检察这位官员的钱从哪里来。", "target_word": "检察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "检察了", "label": "体标"}, {"form": "检察过", "label": "体标"}, {"form": "检察着", "label": "体标"}], "register": "书面", "sense_fingerprint": "检查并审查是否有违法行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87abf8b-582d-4fb7-b060-3655ca7a7a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检察", "is_correct": true, "explanation": "正确。“要检察……有没有违法”指查看是否违法，与语境一致。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏，与“有没有违法”的查看内容矛盾。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”要带节日、胜利之类的事件作宾语，不能接“有没有违法”。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是夸奖，与“有没有违法”的查看目的矛盾。"}], "explanations": {"检察": "正确。“要检察……有没有违法”指查看是否违法，与语境一致。", "欣赏": "语义：“欣赏”是赞赏，与“有没有违法”的查看内容矛盾。", "庆祝": "搭配：“庆祝”要带节日、胜利之类的事件作宾语，不能接“有没有违法”。", "表扬": "语义：“表扬”是夸奖，与“有没有违法”的查看目的矛盾。"}, "sentence_index": 0, "correct_answer": "检察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "质检员已经检察了这批布料的颜色。", "explanation": "这里应该用〈检验〉。检察指查看有没有违法行为，布料的颜色、质量要用〈检验〉。"}, {"text": "医生已经检察了他的血压，一切正常。", "explanation": "这里应该用〈检测〉。检察指查看有没有违法行为，血压等指标的测量要用〈检测〉。"}, {"text": "护士每天都要检察病房的卫生。", "explanation": "这里应该用〈检查〉。检察指查看有没有违法行为，病房卫生的日常查看要用〈检查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检察", "is_correct": true, "explanation": "正确。“检察”指定期查看是否违法，与“每年都要”相符。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”不能接“账目”作宾语。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是夸奖，与“账目每年都要”的查看义不符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“每年都要”的定期查看矛盾。"}], "explanations": {"检察": "正确。“检察”指定期查看是否违法，与“每年都要”相符。", "装饰": "搭配：“装饰”不能接“账目”作宾语。", "赞美": "语义：“赞美”是夸奖，与“账目每年都要”的查看义不符。", "忘记": "语义：“忘记”与“每年都要”的定期查看矛盾。"}, "sentence_index": 6, "correct_answer": "检察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民每天都要检察庄稼的长势，并把情况记在本子上。", "explanation": "这里应该用〈观察〉。检察指查看有没有违法行为，庄稼长势的日常观察要用〈观察〉。"}, {"text": "电工每周都要检察电梯，防止出故障。", "explanation": "这里应该用〈检修〉。检察指查看有没有违法行为，设备的维修检查要用〈检修〉。"}, {"text": "计量所每年都要检察这些仪表。", "explanation": "这里应该用〈检定〉。检察指查看有没有违法行为，仪表的计量准确度要用〈检定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有关部门检察了完这批货，没有发现违法行为。", "corrected_sentence": "有关部门检察完了这批货，没有发现违法行为。", "error_description": "结果补语“完”要紧跟动词，应说“检察完了”，不能说“检察了完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们检察了过这家公司的账目三次。", "corrected_sentence": "他们检察过这家公司的账目三次。", "error_description": "“了”与“过”不能同时用，“检察过”已表示经历，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
