INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "欺骗是说假话让别人相信。", "primary_collocate": null, "pronunciation": "qī piàn", "ipa": "tɕʰi˥ pʰi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他说假话欺骗妈妈。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么要欺骗我？", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友说了谎，欺骗了他。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不应该欺骗父母。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没欺骗过你。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她欺骗我说自己没有钱。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说假话欺骗别人是不对的。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在欺骗大家，说自己是医生。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友欺骗了我，我很生气。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想再欺骗朋友了。", "target_word": "欺骗", "complexity_tier": "T3", "furigana": "qī piàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "欺骗了", "label": "体标：了"}, {"form": "欺骗过", "label": "体标：过"}, {"form": "欺騙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说假话让别人信以为真", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fbe1663-1e8b-4cb8-871b-99d7fbafc682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94961, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "欺骗", "is_correct": true, "explanation": "正确：欺骗（qī piàn）指说假话让别人相信。"}, {"text": "期限", "is_correct": false, "explanation": "qī xiàn（期限）与 qī piàn 声母不同（x 与 p），意思是规定的时间界限。"}, {"text": "西片", "is_correct": false, "explanation": "xī piàn（西片）与 qī piàn 声母不同（x 与 q），意思是西方电影。"}, {"text": "期票", "is_correct": false, "explanation": "qī piào（期票）与 qī piàn 韵尾不同（o 与 n），意思是一种票据。"}, {"text": "期盼", "is_correct": false, "explanation": "qī pàn（期盼）比 qī piàn 少了介音 i，意思是期待。"}], "explanations": {"欺骗": "正确：欺骗（qī piàn）指说假话让别人相信。", "期限": "qī xiàn（期限）与 qī piàn 声母不同（x 与 p），意思是规定的时间界限。", "西片": "xī piàn（西片）与 qī piàn 声母不同（x 与 q），意思是西方电影。", "期票": "qī piào（期票）与 qī piàn 韵尾不同（o 与 n），意思是一种票据。", "期盼": "qī pàn（期盼）比 qī piàn 少了介音 i，意思是期待。"}, "sentence_index": null, "correct_answer": "欺骗"}, "level_3": {"options": [{"text": "欺骗", "is_correct": true, "explanation": "正确：“他说假话欺骗妈妈”，指用假话让妈妈相信。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与“说假话”不相容，句子读来不通。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”是关心料理，与“说假话”的行为相矛盾。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”多指养育子女，不说“抚养妈妈”。"}], "explanations": {"欺骗": "正确：“他说假话欺骗妈妈”，指用假话让妈妈相信。", "感谢": "语义：“感谢”表示谢意，与“说假话”不相容，句子读来不通。", "照顾": "语义：“照顾”是关心料理，与“说假话”的行为相矛盾。", "抚养": "搭配：“抚养”多指养育子女，不说“抚养妈妈”。"}, "sentence_index": 0, "correct_answer": "欺骗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他欺骗了考试成绩，没有告诉父母。", "explanation": "这里应该用〈隐瞒〉。隐瞒是把事情藏起来，可以搭配“成绩”“真相”；欺骗的对象是人，不说“欺骗成绩”。"}, {"text": "他欺骗了父母的约定，晚上很晚才回家。", "explanation": "这里应该用〈违背〉。违背指不遵守约定，可以搭配“约定”“诺言”；欺骗的对象是人，不说“欺骗约定”。"}, {"text": "他欺骗了偷窃的事实，一直不敢承认。", "explanation": "这里应该用〈掩盖〉。掩盖指遮住事实或罪行，可以搭配“事实”“罪行”；欺骗的对象是人，不说“欺骗事实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欺骗", "is_correct": true, "explanation": "正确：“说假话欺骗别人是不对的”，指用假话使人上当，句子成立。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”表示敬重对方，与“说假话”相矛盾，句子读来不通。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”是身体接触的动作，一般不说“说假话拥抱别人”。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”是仔细看，与“说假话”不构成合理的行为，句子读来不通。"}], "explanations": {"欺骗": "正确：“说假话欺骗别人是不对的”，指用假话使人上当，句子成立。", "尊重": "语义：“尊重”表示敬重对方，与“说假话”相矛盾，句子读来不通。", "拥抱": "搭配：“拥抱”是身体接触的动作，一般不说“说假话拥抱别人”。", "观察": "语义：“观察”是仔细看，与“说假话”不构成合理的行为，句子读来不通。"}, "sentence_index": 6, "correct_answer": "欺骗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他仗着个子高，用拳头欺骗同学。", "explanation": "这里应该用〈欺负〉。欺负指仗势或凭力量压迫别人，可以动手；欺骗是用假话或假象使人上当，不能用拳头。"}, {"text": "他一气之下，用脚欺骗了桌子。", "explanation": "这里应该用〈踢〉。欺骗是用假话或假象使人上当，不能用脚去击打，也不能以桌子为对象。"}, {"text": "他欺骗了朋友的好意，没有赴约。", "explanation": "这里应该用〈辜负〉。辜负指没有领会或对得起别人的好意，常搭配“好意”“期望”；欺骗的对象是人，不说“欺骗好意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他欺骗过我一个，我很伤心。", "corrected_sentence": "他欺骗过我一次，我很伤心。", "error_description": "错误：动量词“个”用错。“欺骗”这类动作的次数应使用动量词“次”，不能用名词量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把我欺骗，我很生气。", "corrected_sentence": "他把我欺骗了，我很生气。", "error_description": "错误：用“把”字句时，动词“欺骗”后漏掉了“了”，句子不完整。应说“把我欺骗了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
