INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94962, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用虚假的言行使人上当。", "primary_collocate": null, "pronunciation": "qī piàn", "ipa": "tɕʰi˥ pʰi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "骗子用假名字欺骗了很多老人。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用假身份欺骗大家。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要相信陌生人，他们可能欺骗你。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店用假货欺骗客人。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现朋友一直在欺骗她。", "target_word": "欺骗", "complexity_tier": "T3", "furigana": "qī piàn", "sentence_source": "generated"}, {"text": "网上有人用假照片欺骗别人。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他假装生病欺骗老师。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子打电话欺骗我，说要帮我退款。", "target_word": "欺骗", "complexity_tier": "T3", "furigana": "qī piàn", "sentence_source": "generated"}, {"text": "这种广告欺骗了不少消费者。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他欺骗了她的感情，她很伤心。", "target_word": "欺骗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欺骗了", "label": "体标：了"}, {"form": "欺骗过", "label": "体标：过"}, {"form": "欺騙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用假身份、假货等虚假手段让人上当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fbe1663-1e8b-4cb8-871b-99d7fbafc682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94962, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "欺骗", "is_correct": true, "explanation": "正确：欺骗（qī piàn）指用虚假的言行使人上当。"}, {"text": "期限", "is_correct": false, "explanation": "qī xiàn（期限）与 qī piàn 声母不同（x 与 p），意思是规定的时间界限。"}, {"text": "西片", "is_correct": false, "explanation": "xī piàn（西片）与 qī piàn 声母不同（x 与 q），意思是西方电影。"}, {"text": "期票", "is_correct": false, "explanation": "qī piào（期票）与 qī piàn 韵尾不同（o 与 n），意思是一种票据。"}, {"text": "期盼", "is_correct": false, "explanation": "qī pàn（期盼）比 qī piàn 少了介音 i，意思是期待。"}], "explanations": {"欺骗": "正确：欺骗（qī piàn）指用虚假的言行使人上当。", "期限": "qī xiàn（期限）与 qī piàn 声母不同（x 与 p），意思是规定的时间界限。", "西片": "xī piàn（西片）与 qī piàn 声母不同（x 与 q），意思是西方电影。", "期票": "qī piào（期票）与 qī piàn 韵尾不同（o 与 n），意思是一种票据。", "期盼": "qī pàn（期盼）比 qī piàn 少了介音 i，意思是期待。"}, "sentence_index": null, "correct_answer": "欺骗"}, "level_3": {"options": [{"text": "欺骗", "is_correct": true, "explanation": "正确：“骗子用假名字欺骗了很多老人”，与语境相符。"}, {"text": "抢劫", "is_correct": false, "explanation": "语义：“抢劫”靠暴力夺取财物，与“用假名字”的手段不符。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示友好接待，与骗子的行为相反，句子读来不通。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”多指养育子女，不说“抚养很多老人”。"}], "explanations": {"欺骗": "正确：“骗子用假名字欺骗了很多老人”，与语境相符。", "抢劫": "语义：“抢劫”靠暴力夺取财物，与“用假名字”的手段不符。", "欢迎": "语义：“欢迎”表示友好接待，与骗子的行为相反，句子读来不通。", "抚养": "搭配：“抚养”多指养育子女，不说“抚养很多老人”。"}, "sentence_index": 0, "correct_answer": "欺骗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一生气就用拳头欺骗弟弟。", "explanation": "这里应该用〈殴打〉。殴打指用拳脚打人，可以说“殴打弟弟”；欺骗是用假话或假象使人上当，不能用拳头实施。"}, {"text": "他欺骗了事故的真相，没有告诉大家。", "explanation": "这里应该用〈隐瞒〉。隐瞒是把真相藏起来，可以搭配“真相”；欺骗的对象是人，不说“欺骗真相”。"}, {"text": "他把书欺骗在桌上，转身走了。", "explanation": "这里应该用〈放〉。欺骗是用假话或假象使人上当，不能用来放置东西，“欺骗在桌上”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欺骗", "is_correct": true, "explanation": "正确：“他假装生病欺骗老师”，指用假象使老师上当。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”是饶恕对方的过错，与“假装生病”的欺瞒行为不搭，句子读来不通。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”的对象是作业或文章，不能说“批改老师”。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“假装生病”的行为不相称，句子读来不通。"}], "explanations": {"欺骗": "正确：“他假装生病欺骗老师”，指用假象使老师上当。", "原谅": "语义：“原谅”是饶恕对方的过错，与“假装生病”的欺瞒行为不搭，句子读来不通。", "批改": "搭配：“批改”的对象是作业或文章，不能说“批改老师”。", "赞美": "语义：“赞美”表示称赞，与“假装生病”的行为不相称，句子读来不通。"}, "sentence_index": 6, "correct_answer": "欺骗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他欺骗了父母的期望，考试又失败了。", "explanation": "这里应该用〈辜负〉。辜负指没有对得起别人的期望或好意，常搭配“期望”；欺骗的对象是人，不说“欺骗期望”。"}, {"text": "他欺骗了自己的错误，一直不肯承认。", "explanation": "这里应该用〈掩饰〉。掩饰指遮盖错误或缺点，可以搭配“错误”；欺骗的对象是人，不说“欺骗错误”。"}, {"text": "他欺骗了诺言，大家都很失望。", "explanation": "这里应该用〈违背〉。违背指不遵守诺言或规定，可以搭配“诺言”；欺骗的对象是人，不说“欺骗诺言”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用假话很欺骗了我，我很生气。", "corrected_sentence": "他用假话欺骗了我，我很生气。", "error_description": "错误：在“欺骗”前加了程度副词“很”。“很”一般不修饰这类动作动词，应直接说“欺骗了我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有欺骗了我，我很相信他。", "corrected_sentence": "他没有欺骗我，我很相信他。", "error_description": "错误：用“没有”否定时，“欺骗”后不能再加“了”。应说“没有欺骗我”，“没有”否定的是过去的动作，与“了”不能同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
