INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不明白或不相信而想弄清楚的问题。", "primary_collocate": null, "pronunciation": "yí wèn", "ipa": "i˧˥ wən˥˩", "syllable_count": 2, "sentences": [{"text": "这个数字让大家产生了疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对他的话有疑问，又查了一次。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事还有几个疑问，要再查一查。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对网上的消息，大家都有疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了三个疑问，经理都回答了。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把这些疑问都弄清楚。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的解释没有消除我的疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生回答了病人所有的疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱从哪里来，大家都有疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中有几处疑问，我想问问作者。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "疑问句", "label": "复合"}, {"form": "疑问词", "label": "复合"}], "register": "中性", "sense_fingerprint": "不明白或不相信而要弄清楚的问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0803c99c-fda8-4e16-9a88-b48c5c697e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送给别人的东西，不能被“产生”，与句意不符。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“产生”多接抽象事物，“房子”不能与“产生”搭配。"}, {"text": "疑问", "is_correct": true, "explanation": "“产生了疑问”指大家心里不明白、想弄清楚，与句意相符。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，“让大家产生了牛奶”说不通。"}], "explanations": {"礼物": "语义：礼物是送给别人的东西，不能被“产生”，与句意不符。", "房子": "搭配：“产生”多接抽象事物，“房子”不能与“产生”搭配。", "疑问": "“产生了疑问”指大家心里不明白、想弄清楚，与句意相符。", "牛奶": "语义：牛奶是饮品，“让大家产生了牛奶”说不通。"}, "sentence_index": 0, "correct_answer": "疑问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "网上有一条疑问，大家都相信了。", "explanation": "这里应该用〈谣言〉。疑问是想弄清楚的问题，不能被大家“相信”；能被相信的是谣言这类说法。"}, {"text": "他提出了一座疑问，大家都没想到。", "explanation": "这里应该用〈个〉。疑问是抽象名词，量词用“个”；“座”用于山、楼等大型物体。"}, {"text": "他每天上班，疑问很辛苦。", "explanation": "这里应该用〈工作〉。“辛苦”形容人或做事的过程，疑问不能“辛苦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肥皂", "is_correct": false, "explanation": "语义：“肥皂”不能被“消除”，句子说不通。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”不是解释能消除的东西，与句意不符。"}, {"text": "疑问", "is_correct": true, "explanation": "“消除疑问”指使不明白、不相信的问题得到解决，与句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“消除”多接问题、误会、疑虑等，不接“体重”。"}], "explanations": {"肥皂": "语义：“肥皂”不能被“消除”，句子说不通。", "电话": "语义：“电话”不是解释能消除的东西，与句意不符。", "疑问": "“消除疑问”指使不明白、不相信的问题得到解决，与句意相符。", "体重": "搭配：“消除”多接问题、误会、疑虑等，不接“体重”。"}, "sentence_index": 6, "correct_answer": "疑问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章有几处疑问，我得改正。", "explanation": "这里应该用〈错别字〉。疑问是想弄清楚的问题，不能被“改正”；错别字才能改正。"}, {"text": "他每天坐疑问上班，很方便。", "explanation": "这里应该用〈地铁〉。“坐”的对象是交通工具，疑问是想弄清楚的问题，不能被坐。"}, {"text": "他最近买了一些疑问。", "explanation": "这里应该用〈股票〉。“买”的对象是股票、东西等，疑问不能被买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向老师买了一个疑问。", "corrected_sentence": "他向老师提出了一个疑问。", "error_description": "动词搭配错误：“买”的对象是商品，“疑问”不能被购买，应说“提出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师一句话就解开了我疑问。", "corrected_sentence": "老师一句话就解开了我的疑问。", "error_description": "结构助词缺失：定语“我”与中心语“疑问”之间需要“的”，应说“我的疑问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94977, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接收", "is_correct": true, "explanation": "正确：接收与“发送”构成反义，发送是把东西寄出，接收是收到寄来的东西。"}, {"text": "购买", "is_correct": false, "explanation": "购买是付钱取得东西，与“发送”不构成反义关系。"}, {"text": "打开", "is_correct": false, "explanation": "打开指把封闭的东西开启，与“发送”不构成反义关系。"}, {"text": "阅读", "is_correct": false, "explanation": "阅读指看文字内容，与“发送”不构成反义关系。"}], "correct_answer": "接收", "explanations": {"接收": "正确：接收与“发送”构成反义，发送是把东西寄出，接收是收到寄来的东西。", "购买": "购买是付钱取得东西，与“发送”不构成反义关系。", "打开": "打开指把封闭的东西开启，与“发送”不构成反义关系。", "阅读": "阅读指看文字内容，与“发送”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94977, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接收", "is_correct": true, "explanation": "正确：接收与“发送”构成反义，发送是把东西寄出，接收是收到寄来的东西。"}, {"text": "整理", "is_correct": false, "explanation": "整理指把东西弄得有条理，与“发送”不构成反义关系。"}, {"text": "丢弃", "is_correct": false, "explanation": "丢弃指扔掉不要的东西，与“发送”不构成反义关系。"}, {"text": "储存", "is_correct": false, "explanation": "储存指把东西存放起来，与“发送”不构成反义关系。"}], "correct_answer": "接收", "explanations": {"接收": "正确：接收与“发送”构成反义，发送是把东西寄出，接收是收到寄来的东西。", "整理": "整理指把东西弄得有条理，与“发送”不构成反义关系。", "丢弃": "丢弃指扔掉不要的东西，与“发送”不构成反义关系。", "储存": "储存指把东西存放起来，与“发送”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发送是把信或东西寄给别人。", "primary_collocate": null, "pronunciation": "fā sòng", "ipa": "fa˥ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我把邮件发送给老师了。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天给朋友发送一条短信。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把文件发送到我的邮箱。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经发送了照片，你收到了吗？", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司明天发送这批货物。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把生日贺卡发送给远方的朋友。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点一下这里就能发送信息。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发送了三次，他都没收到。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在手机上发送了一张地图。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给每位学生发送了通知。", "target_word": "发送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发送了", "label": "体标：了"}, {"form": "发送过", "label": "体标：过"}, {"form": "發送", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把邮件、信息或东西寄给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fbe1663-1e8b-4cb8-871b-99d7fbafc682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发送", "is_correct": true, "explanation": "正确：“我把邮件发送给老师了”，指把邮件寄给老师。"}, {"text": "奖", "is_correct": false, "explanation": "语义：“奖”指奖励，邮件不能作为奖品发给老师，句子读来不通。"}, {"text": "颁发", "is_correct": false, "explanation": "搭配：“颁发”的对象多是证书、奖状，不能说“颁发邮件”。"}, {"text": "赔", "is_correct": false, "explanation": "搭配：“赔”的宾语应是钱物或损失，不能说“赔邮件”。"}], "explanations": {"发送": "正确：“我把邮件发送给老师了”，指把邮件寄给老师。", "奖": "语义：“奖”指奖励，邮件不能作为奖品发给老师，句子读来不通。", "颁发": "搭配：“颁发”的对象多是证书、奖状，不能说“颁发邮件”。", "赔": "搭配：“赔”的宾语应是钱物或损失，不能说“赔邮件”。"}, "sentence_index": 0, "correct_answer": "发送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火箭成功发送了卫星，直冲天空。", "explanation": "这里应该用〈发射〉。发射指把火箭、卫星等射出去，可搭配“卫星”“导弹”；发送指把信息或物品寄出，不说“发送卫星”。"}, {"text": "他在比赛中发送了出色的实力。", "explanation": "这里应该用〈发挥〉。发挥指把自己的能力或水平表现出来，可搭配“实力”“作用”；发送指寄出，不能这样用。"}, {"text": "手机突然发送了一阵响声。", "explanation": "这里应该用〈发出〉。发出指散发或放出声音、光等，可搭配“响声”；发送指寄出信息或物品，不说“发送响声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发送", "is_correct": true, "explanation": "正确：“点一下这里就能发送信息”，指点击后把信息发出去。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是猛击，与“点一下”的轻便操作相反，句子读来不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象是具体物品，信息不能扔。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗实物，与点击操作不符，句子读来不通。"}], "explanations": {"发送": "正确：“点一下这里就能发送信息”，指点击后把信息发出去。", "砸": "语义：“砸”是猛击，与“点一下”的轻便操作相反，句子读来不通。", "扔": "搭配：“扔”的对象是具体物品，信息不能扔。", "洗": "语义：“洗”是清洗实物，与点击操作不符，句子读来不通。"}, "sentence_index": 6, "correct_answer": "发送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天路口突然发送了一起事故。", "explanation": "这里应该用〈发生〉。发生指事情出现或产生，可搭配“事故”“变化”；发送指寄出物品或信息，不说“发送事故”。"}, {"text": "这位工程师发送了一种新机器。", "explanation": "这里应该用〈发明〉。发明指创造出从前没有的东西，可搭配“机器”“技术”；发送指寄出，不能说“发送机器”。"}, {"text": "他把心里的怒气发送在朋友身上。", "explanation": "这里应该用〈发泄〉。发泄指把情绪或怒气释放出来，可搭配“怒气”“不满”；发送指寄出，不说“发送怒气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把报告发送经理了。", "corrected_sentence": "我已经把报告发送给经理了。", "error_description": "错误：“发送”后漏掉了介词“给”。应说“发送给经理”，表示把东西寄给某人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我发送了过这封邮件。", "corrected_sentence": "我发送过这封邮件。", "error_description": "错误：“了”与“过”的顺序颠倒。“过”表示曾经做过，“了”不能放在“过”前面（“发送过了”可以，“发送了过”不行），应说“发送过这封邮件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7067b1c-a9a1-4ead-a212-ab9101953ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
