INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94980, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从空隙或障碍中穿过去；也指跨越时间或空间。", "primary_collocate": null, "pronunciation": "chuān yuè", "ipa": "ʈʂʰwan˥ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "火车穿越了长长的山洞。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河穿越了三个国家。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光穿越云层，照在海面上。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢看穿越时空的电影。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想不想穿越到一千年前？", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机穿越了厚厚的云层。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼穿越水草，游到了石头后面。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部小说写一个人穿越回了唐朝。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光穿越太空要很长时间。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条路穿越了整个森林。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿越了", "label": "体标（完成）"}, {"form": "穿越过", "label": "体标（经历）"}, {"form": "穿越时空", "label": "复合"}, {"form": "穿越者", "label": "复合"}], "register": "中性", "sense_fingerprint": "穿过障碍或空隙，也指跨越时空", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e57d5e-0600-40a5-bf17-17abc02ebec0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿越", "is_correct": true, "explanation": "正确：“穿越”表示火车穿过长长的山洞，符合“穿过障碍或空隙”的义项。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，火车不能吃山洞。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物的离合词，后面不能直接带“山洞”作宾语。"}, {"text": "生病", "is_correct": false, "explanation": "语义：火车不会生病，“生病”也无法与“长长的山洞”搭配。"}], "explanations": {"穿越": "正确：“穿越”表示火车穿过长长的山洞，符合“穿过障碍或空隙”的义项。", "吃": "语义：“吃”的对象应是食物，火车不能吃山洞。", "散步": "配价：“散步”是不及物的离合词，后面不能直接带“山洞”作宾语。", "生病": "语义：火车不会生病，“生病”也无法与“长长的山洞”搭配。"}, "sentence_index": 0, "correct_answer": "穿越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影穿越了同类作品。", "explanation": "这里应该用〈超越〉。穿越指穿过空隙或障碍、跨越时空，超过同类作品要用〈超越〉。"}, {"text": "他穿越了一碗面。", "explanation": "这里应该用〈吃〉。穿越是穿过空隙或障碍、跨越时空，不表示进食，吃面要用〈吃〉。"}, {"text": "这次的开支穿越了预算。", "explanation": "这里应该用〈超出〉。穿越指穿过空隙或障碍、跨越时空，开支超过预算要用〈超出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿越", "is_correct": true, "explanation": "正确：“穿越”表示小鱼从水草中间穿过去，与“游到了石头后面”的动作相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物的离合词，不能直接带“水草”作宾语。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”的对象应是问题或事情，“小鱼讨论水草”说不通。"}, {"text": "解释", "is_correct": false, "explanation": "语义：“解释”的对象是现象或道理，不能用于“水草”。"}], "explanations": {"穿越": "正确：“穿越”表示小鱼从水草中间穿过去，与“游到了石头后面”的动作相符。", "睡觉": "配价：“睡觉”是不及物的离合词，不能直接带“水草”作宾语。", "讨论": "语义：“讨论”的对象应是问题或事情，“小鱼讨论水草”说不通。", "解释": "语义：“解释”的对象是现象或道理，不能用于“水草”。"}, "sentence_index": 6, "correct_answer": "穿越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿越了一台新电脑。", "explanation": "这里应该用〈买〉。穿越是穿过空间或障碍，不表示购买，买电脑要用〈买〉。"}, {"text": "这支球队穿越了去年的冠军。", "explanation": "这里应该用〈击败〉。穿越不表示战胜对方，战胜对方要用〈击败〉。"}, {"text": "这次考试他的成绩穿越了我。", "explanation": "这里应该用〈超过〉。穿越不表示成绩上的超出，这里要用〈超过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一觉醒来，穿越了到古代。", "corrected_sentence": "他一觉醒来，穿越到了古代。", "error_description": "错误：“穿越了到古代”；正确：“穿越到了古代”。动态助词“了”应放在补语“到”之后，表示动作已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条隧道穿越在了山的另一边。", "corrected_sentence": "这条隧道穿越到了山的另一边。", "error_description": "错误：“穿越在了”；正确：“穿越到了”。结果补语应用“到”表示到达的地点，“在”不能表示这一动作的终点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
