INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "近代是离现在不太远的过去。", "primary_collocate": null, "pronunciation": "jìn dài", "ipa": "tɕin˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "近代的人比古代的人生活方便。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种东西是近代才有的。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近代以来，城市变得越来越大。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子是近代盖的。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢看近代的老照片。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近代的很多发明改变了生活。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种风格是近代的。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起古代，近代的路好走多了。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近代以来，医生已经会用机器看病。", "target_word": "近代", "complexity_tier": "T3", "furigana": "jìndài yǐlái, yīshēng yǐjīng huì yòng jīqì kànbìng.", "sentence_source": "generated"}, {"text": "我对近代的音乐很感兴趣。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "近代史", "label": "复合"}], "register": "中性", "sense_fingerprint": "离现在不太远的过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87abf8b-582d-4fb7-b060-3655ca7a7a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94993, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "近代", "is_correct": true, "explanation": "正确。近代指离现在不太远的过去。"}, {"text": "进来", "is_correct": false, "explanation": "近代与进来只有后一个音节不同：dài（第四声）与 lái（第二声）；进来意思是从外面走入。"}, {"text": "近海", "is_correct": false, "explanation": "dài（第四声）与 hǎi（第三声）声母不同（d/h），近海意思是靠近海岸的海域。"}, {"text": "金代", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，金代指金朝的时代，不是离现在不远的过去。"}, {"text": "信贷", "is_correct": false, "explanation": "jìn 与 xìn 声母不同（j/x），信贷意思是银行等机构发放的贷款。"}], "explanations": {"近代": "正确。近代指离现在不太远的过去。", "进来": "近代与进来只有后一个音节不同：dài（第四声）与 lái（第二声）；进来意思是从外面走入。", "近海": "dài（第四声）与 hǎi（第三声）声母不同（d/h），近海意思是靠近海岸的海域。", "金代": "jìn（第四声）与 jīn（第一声）声调不同，金代指金朝的时代，不是离现在不远的过去。", "信贷": "jìn 与 xìn 声母不同（j/x），信贷意思是银行等机构发放的贷款。"}, "sentence_index": null, "correct_answer": "近代"}, "level_3": {"options": [{"text": "近代", "is_correct": true, "explanation": "正确。近代指离现在不太远的过去，与“古代”形成对比，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，不能修饰“的人”，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“电脑的人”不成词组，“人”前不能用“电脑”来限定。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，无法作为指人的定语，“春天的人”不成立。"}], "explanations": {"近代": "正确。近代指离现在不太远的过去，与“古代”形成对比，符合句意。", "石头": "语义：“石头”不是人，不能修饰“的人”，句意不通。", "电脑": "搭配：“电脑的人”不成词组，“人”前不能用“电脑”来限定。", "春天": "语义：“春天”是季节，无法作为指人的定语，“春天的人”不成立。"}, "sentence_index": 0, "correct_answer": "近代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天要去近代旅行。", "explanation": "这里应该用〈未来〉。近代指已经过去的时间，不能指明天要去的时代。"}, {"text": "孔子生活在近代。", "explanation": "这里应该用〈古代〉。近代指离现在不太远的时期，孔子所处的年代远早于此。"}, {"text": "人类在近代就学会了用火。", "explanation": "这里应该用〈上古〉。近代指离现在不太远的过去，人类学会用火远在其前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94993, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "近代", "is_correct": true, "explanation": "正确。近代指离现在不太远的过去。"}, {"text": "近来", "is_correct": false, "explanation": "dài（第四声）与 lái（第二声）声母与声调不同（d/l），近来意思是最近一段时间。"}, {"text": "秦代", "is_correct": false, "explanation": "jìn（第四声）与 qín（第二声）声母不同（j/q），秦代指秦朝的时代。"}, {"text": "今代", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，今代指当今这个时代，属于书面用语。"}], "explanations": {"近代": "正确。近代指离现在不太远的过去。", "近来": "dài（第四声）与 lái（第二声）声母与声调不同（d/l），近来意思是最近一段时间。", "秦代": "jìn（第四声）与 qín（第二声）声母不同（j/q），秦代指秦朝的时代。", "今代": "jìn（第四声）与 jīn（第一声）声调不同，今代指当今这个时代，属于书面用语。"}, "sentence_index": null, "correct_answer": "近代"}, "level_3": {"options": [{"text": "近代", "is_correct": true, "explanation": "正确。近代指离现在不太远的过去，“这种风格是……的”中指一个不太久远的时代。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“中午”是一天中的时刻，不是时代，“这种风格是中午的”句意不通。"}, {"text": "星期一", "is_correct": false, "explanation": "语义：“星期一”是一周中的某一天，不是时代，“这种风格是星期一的”句意不通。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是时刻，不是时代，“这种风格是下午的”句意不通。"}], "explanations": {"近代": "正确。近代指离现在不太远的过去，“这种风格是……的”中指一个不太久远的时代。", "中午": "语义：“中午”是一天中的时刻，不是时代，“这种风格是中午的”句意不通。", "星期一": "语义：“星期一”是一周中的某一天，不是时代，“这种风格是星期一的”句意不通。", "下午": "语义：“下午”是时刻，不是时代，“这种风格是下午的”句意不通。"}, "sentence_index": 6, "correct_answer": "近代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近代的人类住在山洞里。", "explanation": "这里应该用〈远古〉。近代指离现在不太远的过去，住在山洞里的时代远在其前。"}, {"text": "近代年轻人都在火星上生活。", "explanation": "这里应该用〈未来〉。近代指已经过去的时间，当时人类还没有在火星上生活，不能用于此。"}, {"text": "近代的汽车会自动驾驶。", "explanation": "这里应该用〈未来〉。近代指已经过去的时间，不能指还没有到来的未来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近代来，人们的生活发生了很大变化。", "corrected_sentence": "近代以来，人们的生活发生了很大变化。", "error_description": "错误：“近代来”；正确：“近代以来”。“以来”是固定说法“……以来”，不能省略，应说“近代以来”，表示从近代至今的时间段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些老家具都是近代，很有特色。", "corrected_sentence": "这些老家具都是近代的，很有特色。", "error_description": "错误：“都是近代”；正确：“都是近代的”。“是……的”结构中，“的”不能省略，应说“是近代的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
