INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "离现在较近的时代，在历史上指鸦片战争到五四运动期间。", "primary_collocate": null, "pronunciation": "jìn dài", "ipa": "tɕin˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "鸦片战争以后，中国进入了近代。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近代的中国经历了很多困难。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家生活在中国近代。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五四运动是近代的一件大事。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近代的中国人开始学习外国的东西。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老楼是中国近代留下来的。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，近代从一八四〇年开始。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近代的上海有很多外国人。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读过近代的故事。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近代的中国，工厂越来越多。", "target_word": "近代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "近代史", "label": "复合"}], "register": "中性", "sense_fingerprint": "历史上鸦片战争到五四运动的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87abf8b-582d-4fb7-b060-3655ca7a7a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "近代", "is_correct": true, "explanation": "正确。近代特指历史上从鸦片战争到五四运动的时期。"}, {"text": "近来", "is_correct": false, "explanation": "dài（第四声）与 lái（第二声）声母与声调不同（d/l），近来指最近一段时间。"}, {"text": "近海", "is_correct": false, "explanation": "dài（第四声）与 hǎi（第三声）声母不同（d/h），近海指靠近海岸的海域。"}, {"text": "金代", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，金代指金朝的历史时期。"}, {"text": "秦代", "is_correct": false, "explanation": "jìn 与 qín 声母不同（j/q），秦代指秦朝的历史时期。"}], "explanations": {"近代": "正确。近代特指历史上从鸦片战争到五四运动的时期。", "近来": "dài（第四声）与 lái（第二声）声母与声调不同（d/l），近来指最近一段时间。", "近海": "dài（第四声）与 hǎi（第三声）声母不同（d/h），近海指靠近海岸的海域。", "金代": "jìn（第四声）与 jīn（第一声）声调不同，金代指金朝的历史时期。", "秦代": "jìn 与 qín 声母不同（j/q），秦代指秦朝的历史时期。"}, "sentence_index": null, "correct_answer": "近代"}, "level_3": {"options": [{"text": "近代", "is_correct": true, "explanation": "正确。鸦片战争以后中国进入的正是近代这一历史时期。"}, {"text": "古代", "is_correct": false, "explanation": "语义：鸦片战争发生在近代，“以后”不可能进入古代。"}, {"text": "石器时代", "is_correct": false, "explanation": "语义：石器时代远早于鸦片战争，与“以后”的时间关系矛盾。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：“进入了……”后接的是历史时期，“周末”是时间段，“中国进入了周末”不成立。"}], "explanations": {"近代": "正确。鸦片战争以后中国进入的正是近代这一历史时期。", "古代": "语义：鸦片战争发生在近代，“以后”不可能进入古代。", "石器时代": "语义：石器时代远早于鸦片战争，与“以后”的时间关系矛盾。", "周末": "搭配：“进入了……”后接的是历史时期，“周末”是时间段，“中国进入了周末”不成立。"}, "sentence_index": 0, "correct_answer": "近代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近代的中国人天天都用手机。", "explanation": "这里应该用〈现代〉。近代特指鸦片战争到五四运动的历史时期，不能用来指现在的人。"}, {"text": "秦朝的长城是近代修建的。", "explanation": "这里应该用〈古代〉。秦朝早于鸦片战争两千多年，不属于近代这一历史时期。"}, {"text": "恐龙是近代灭绝的。", "explanation": "这里应该用〈远古〉。近代指离现在较近的时代，恐龙灭绝于远古时期，相差数千万年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94994, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "近代", "is_correct": true, "explanation": "正确。近代特指历史上从鸦片战争到五四运动的时期。"}, {"text": "进来", "is_correct": false, "explanation": "近代与进来只有后一个音节不同：dài（第四声）与 lái（第二声）；进来意思是从外面走入。"}, {"text": "信贷", "is_correct": false, "explanation": "jìn 与 xìn 声母不同（j/x），信贷意思是银行等机构发放的贷款。"}, {"text": "今代", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，今代指当今这个时代，属于书面用语。"}], "explanations": {"近代": "正确。近代特指历史上从鸦片战争到五四运动的时期。", "进来": "近代与进来只有后一个音节不同：dài（第四声）与 lái（第二声）；进来意思是从外面走入。", "信贷": "jìn 与 xìn 声母不同（j/x），信贷意思是银行等机构发放的贷款。", "今代": "jìn（第四声）与 jīn（第一声）声调不同，今代指当今这个时代，属于书面用语。"}, "sentence_index": null, "correct_answer": "近代"}, "level_3": {"options": [{"text": "近代", "is_correct": true, "explanation": "正确。“近代从一八四〇年开始”指的是历史分期中的近代。"}, {"text": "春秋", "is_correct": false, "explanation": "语义：春秋时期远早于一八四〇年，不可能从那时开始。"}, {"text": "战国", "is_correct": false, "explanation": "语义：战国也远早于一八四〇年，与句中的时间矛盾。"}, {"text": "星期一", "is_correct": false, "explanation": "搭配：“从……开始”后接时间，但“星期一”不能指一个历史时期的起始。"}], "explanations": {"近代": "正确。“近代从一八四〇年开始”指的是历史分期中的近代。", "春秋": "语义：春秋时期远早于一八四〇年，不可能从那时开始。", "战国": "语义：战国也远早于一八四〇年，与句中的时间矛盾。", "星期一": "搭配：“从……开始”后接时间，但“星期一”不能指一个历史时期的起始。"}, "sentence_index": 6, "correct_answer": "近代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近代的人们还不会用火。", "explanation": "这里应该用〈上古〉。近代特指鸦片战争到五四运动的时期，远远晚于上古。"}, {"text": "近代的孩子都在用手机上网。", "explanation": "这里应该用〈当代〉。近代特指已经过去的历史时期，那时还没有手机，这句话只能描述当代的孩子。"}, {"text": "近代的孩子都在学英语。", "explanation": "这里应该用〈当代〉。近代特指已经过去的历史时期，不能用来形容现在的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近代来，中国的工业发展得很快。", "corrected_sentence": "近代以来，中国的工业发展得很快。", "error_description": "错误：“近代来”；正确：“近代以来”。“以来”是固定说法“……以来”，不能省略，应说“近代以来”，表示从近代至今的时间段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上海在近代地变得越来越热闹。", "corrected_sentence": "上海在近代变得越来越热闹。", "error_description": "错误：“近代地”；正确：“近代”。“近代”是时间名词，不能带“地”修饰后面的“变得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
