INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "紧接着，立刻。", "primary_collocate": null, "pronunciation": "suí jí", "ipa": "sweɪ˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "灯一亮，大家随即安静下来。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到电话响，她随即拿起了手机。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了一句话，大家随即笑了。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，太阳随即出来了。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生来了，随即给病人检查。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理走进来，大家随即站了起来。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铃声响了，学生们随即回到座位。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔倒了，旁边的人随即跑过去帮他。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发了一条信息，朋友随即回复了。", "target_word": "随即", "complexity_tier": "T3", "furigana": "wǒ fā le yì tiáo xìnxī, péngyou suíjí huífù le.", "sentence_source": "generated"}, {"text": "看到火，他随即大声叫了起来。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "紧接着前一件事，立刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87abf8b-582d-4fb7-b060-3655ca7a7a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "随即", "is_correct": true, "explanation": "正确。随即表示紧接着前一件事，立刻发生。"}, {"text": "随时", "is_correct": false, "explanation": "jí 与 shí 声母不同（j/sh），随时指在任何时候。"}, {"text": "随之", "is_correct": false, "explanation": "jí 与 zhī 声母不同（j/zh），随之表示跟着、接着，不指“立刻”。"}, {"text": "随意", "is_correct": false, "explanation": "jí 与 yì 声母与声调都不同，随意指任凭自己的心意，不拘束。"}], "explanations": {"随即": "正确。随即表示紧接着前一件事，立刻发生。", "随时": "jí 与 shí 声母不同（j/sh），随时指在任何时候。", "随之": "jí 与 zhī 声母不同（j/zh），随之表示跟着、接着，不指“立刻”。", "随意": "jí 与 yì 声母与声调都不同，随意指任凭自己的心意，不拘束。"}, "sentence_index": null, "correct_answer": "随即"}, "level_3": {"options": [{"text": "随即", "is_correct": true, "explanation": "正确。“灯一亮，大家随即安静下来”表示灯亮后立刻安静。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未如此，与“灯一亮”后大家立刻安静的变化矛盾。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：“始终”表示一直如此，不能与“安静下来”这种表示开始变化的补语搭配。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态延续，与“安静下来”所表示的开始变化矛盾。"}], "explanations": {"随即": "正确。“灯一亮，大家随即安静下来”表示灯亮后立刻安静。", "从来": "语义：“从来”表示从未如此，与“灯一亮”后大家立刻安静的变化矛盾。", "始终": "搭配：“始终”表示一直如此，不能与“安静下来”这种表示开始变化的补语搭配。", "仍然": "语义：“仍然”表示状态延续，与“安静下来”所表示的开始变化矛盾。"}, "sentence_index": 0, "correct_answer": "随即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气慢慢变暖，春天随即来了。", "explanation": "这里应该用〈后来〉。随即要求紧接着、立刻发生，与“慢慢变暖”的渐进过程矛盾。"}, {"text": "他写了信，过了三天，随即收到了回信。", "explanation": "这里应该用〈后来〉。随即表示紧接着、立刻，“过了三天”之后才收到，与之矛盾。"}, {"text": "我放下碗，过了好一会儿随即去洗碗了。", "explanation": "这里应该用〈随后〉。随即表示立刻，“过了好一会儿”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "随即", "is_correct": true, "explanation": "正确。随即表示紧接着前一件事，立刻发生。"}, {"text": "随机", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，随机指没有规律、任意。"}, {"text": "随地", "is_correct": false, "explanation": "jí 与 dì 声母不同（j/d），随地指在任何地方，多用于随地吐痰等行为。"}, {"text": "随笔", "is_correct": false, "explanation": "jí 与 bǐ 声母不同（j/b），随笔指随手写下的文章或文字。"}], "explanations": {"随即": "正确。随即表示紧接着前一件事，立刻发生。", "随机": "jí（第二声）与 jī（第一声）声调不同，随机指没有规律、任意。", "随地": "jí 与 dì 声母不同（j/d），随地指在任何地方，多用于随地吐痰等行为。", "随笔": "jí 与 bǐ 声母不同（j/b），随笔指随手写下的文章或文字。"}, "sentence_index": null, "correct_answer": "随即"}, "level_3": {"options": [{"text": "随即", "is_correct": true, "explanation": "正确。“铃声响了，学生们随即回到座位”表示铃一响就回座位。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示习惯性的否定，与“铃声响了”这一次的事件矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“回到座位”这种一次性动作搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与铃声一响就回座位的紧接关系矛盾。"}], "explanations": {"随即": "正确。“铃声响了，学生们随即回到座位”表示铃一响就回座位。", "从不": "语义：“从不”表示习惯性的否定，与“铃声响了”这一次的事件矛盾。", "一直": "搭配：“一直”表示持续，不能与“回到座位”这种一次性动作搭配。", "偶尔": "语义：“偶尔”表示不经常，与铃声一响就回座位的紧接关系矛盾。"}, "sentence_index": 6, "correct_answer": "随即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火还在烧，他随即在一旁站着。", "explanation": "这里应该用〈仍然〉。随即表示紧接着前一件事，不能描述状态延续。"}, {"text": "他还在哭，过了半天随即笑了起来。", "explanation": "这里应该用〈终于〉。随即表示紧接着、立刻，“过了半天”之后才笑，与之矛盾。"}, {"text": "他跑了一个小时，过了很久随即到达了学校。", "explanation": "这里应该用〈最终〉。随即表示紧接着、立刻，“过了很久”之后才到达，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门一开，猫随即的跑了出去。", "corrected_sentence": "门一开，猫随即跑了出去。", "error_description": "错误：“随即的跑了出去”；正确：“随即跑了出去”。“随即”是副词，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈一叫，孩子随即地跑了过来。", "corrected_sentence": "妈妈一叫，孩子随即跑了过来。", "error_description": "错误：“随即地”；正确：“随即”。“随即”是副词，后面不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1047dd84-1326-4e86-bea1-ec017b277fb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改变", "is_correct": true, "explanation": "「改变」与「不变」意思相反，表示变得和以前不一样。"}, {"text": "生长", "is_correct": false, "explanation": "「生长」与「不变」没有反义关系，指生物长大。"}, {"text": "移动", "is_correct": false, "explanation": "「移动」与「不变」没有反义关系，指位置改变。"}, {"text": "游泳", "is_correct": false, "explanation": "「游泳」与「不变」没有反义关系，指在水中活动。"}], "correct_answer": "改变", "explanations": {"改变": "「改变」与「不变」意思相反，表示变得和以前不一样。", "生长": "「生长」与「不变」没有反义关系，指生物长大。", "移动": "「移动」与「不变」没有反义关系，指位置改变。", "游泳": "「游泳」与「不变」没有反义关系，指在水中活动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改变", "is_correct": true, "explanation": "「改变」与「不变」意思相反，表示变得和以前不一样。"}, {"text": "跳舞", "is_correct": false, "explanation": "「跳舞」与「不变」没有反义关系，指舞动身体。"}, {"text": "哭泣", "is_correct": false, "explanation": "「哭泣」与「不变」没有反义关系，指流泪哭出声。"}, {"text": "睡觉", "is_correct": false, "explanation": "「睡觉」与「不变」没有反义关系，指入睡休息。"}], "correct_answer": "改变", "explanations": {"改变": "「改变」与「不变」意思相反，表示变得和以前不一样。", "跳舞": "「跳舞」与「不变」没有反义关系，指舞动身体。", "哭泣": "「哭泣」与「不变」没有反义关系，指流泪哭出声。", "睡觉": "「睡觉」与「不变」没有反义关系，指入睡休息。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "不变是还和以前一样。", "primary_collocate": null, "pronunciation": "bù biàn", "ipa": "pu˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他的习惯多年不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的地址三年不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的味道二十年不变，老顾客都很喜欢。", "target_word": "不变", "complexity_tier": "T3", "furigana": "bú biàn", "sentence_source": "generated"}, {"text": "老师的办公室一直不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格今年保持不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对我的态度不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的名字一直不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友的笑容十年不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上跑步，这个习惯不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电话号码不变，你可以放心。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一成不变", "label": "复合"}], "register": "中性", "sense_fingerprint": "不变：还和以前一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0803c99c-fda8-4e16-9a88-b48c5c697e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不变", "is_correct": true, "explanation": "「不变」表示还和以前一样，是这里要选的词。"}, {"text": "普遍", "is_correct": false, "explanation": "「pǔ（第三声）」与 bù（第四声）声母不同（p 与 b），意思是普遍。"}, {"text": "不办", "is_correct": false, "explanation": "「bàn」与 biàn 韵母不同（少了 i），意思是不办理。"}, {"text": "不搬", "is_correct": false, "explanation": "「bān」与 biàn 韵母不同（少了 i）且声调不同，意思是不搬动。"}], "explanations": {"不变": "「不变」表示还和以前一样，是这里要选的词。", "普遍": "「pǔ（第三声）」与 bù（第四声）声母不同（p 与 b），意思是普遍。", "不办": "「bàn」与 biàn 韵母不同（少了 i），意思是不办理。", "不搬": "「bān」与 biàn 韵母不同（少了 i）且声调不同，意思是不搬动。"}, "sentence_index": null, "correct_answer": "不变"}, "level_3": {"options": [{"text": "不变", "is_correct": true, "explanation": "「不变」表示还和以前一样，与“多年”的持续义相符。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：「增加」说数量，不能与“习惯”搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "配价：「忘记」需要带宾语，“习惯多年忘记”不成立。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：「生长」只用于生物，不能与“习惯”搭配。"}], "explanations": {"不变": "「不变」表示还和以前一样，与“多年”的持续义相符。", "增加": "搭配：「增加」说数量，不能与“习惯”搭配。", "忘记": "配价：「忘记」需要带宾语，“习惯多年忘记”不成立。", "生长": "搭配：「生长」只用于生物，不能与“习惯”搭配。"}, "sentence_index": 0, "correct_answer": "不变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的旋律每次都不变，所以听起来很新鲜。", "explanation": "这里应该用〈变换〉。「不变」指没有变化，与“新鲜”矛盾，表示花样不断变化要用〈变换〉。"}, {"text": "他的体重这半年都不变，却瘦了好几斤。", "explanation": "这里应该用〈减轻〉。「不变」表示没有变化，与“瘦了好几斤”矛盾，体重减少要用〈减轻〉。"}, {"text": "他说话的声音一直不变，却越来越小。", "explanation": "这里应该用〈变小〉。「不变」表示没有变化，与“越来越小”矛盾，声音变小要用〈变小〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不变", "is_correct": true, "explanation": "「不变」表示还和以前一样，与“一直”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：路的名字不会游泳，与语境矛盾。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：名字不能增长，「增长」多用于数量或规模。"}, {"text": "参观", "is_correct": false, "explanation": "配价：「参观」需要带宾语，“这条路的名字一直参观”不成立。"}], "explanations": {"不变": "「不变」表示还和以前一样，与“一直”相符。", "游泳": "语义：路的名字不会游泳，与语境矛盾。", "增长": "搭配：名字不能增长，「增长」多用于数量或规模。", "参观": "配价：「参观」需要带宾语，“这条路的名字一直参观”不成立。"}, "sentence_index": 6, "correct_answer": "不变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气一天一个样，每天都不变。", "explanation": "这里应该用〈多变〉。「不变」指和以前一样，说脾气“一天一个样”要用〈多变〉。"}, {"text": "这家店的装修每个月都在变，但是一直不变。", "explanation": "这里应该用〈翻新〉。「不变」表示没有变化，与“每个月都在变”矛盾，装修经常更换要用〈翻新〉。"}, {"text": "他一年比一年高，身高却每年都不变。", "explanation": "这里应该用〈长高〉。「不变」表示没有变化，与“一年比一年高”矛盾，身高随年龄变化要用〈长高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的友谊多年来始终不变了。", "corrected_sentence": "我们的友谊多年来始终不变。", "error_description": "「不变」表示没有变化，后面加“了”表示已经发生变化，与语境矛盾，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的样子几十年都被不变。", "corrected_sentence": "这个小镇的样子几十年都不变。", "error_description": "「不变」是不及物的状态词，不能用“被”字句，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
