INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中心点是正中间的那一个点。", "primary_collocate": null, "pronunciation": "zhōng xīn diǎn", "ipa": "ʈʂʊŋ˥ ɕin˥ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个圆的中心点在哪里？", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用尺子找到了纸的中心点。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在线段的中心点画一个小圆。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的中心点放着一盆花。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆的中心点到圆周上每一点的距离都相等。", "target_word": "中心点", "complexity_tier": "T3", "furigana": "yuán de zhōng xīn diǎn dào yuán zhōu shàng měi yì diǎn de jù lí dōu xiāng děng.", "sentence_source": "generated"}, {"text": "我们把绳子的中心点系在树上。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说正方形的中心点在两条线中间。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把球放在球场的中心点。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟的中心点上有三根针。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在盒子盖的中心点贴一张画。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个中心点", "label": "量词"}], "register": "中性", "sense_fingerprint": "正中间的那一个点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa43149-2bed-4ace-a420-196d5d97c406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“在哪里”问的是位置，“颜色”不能用来问位置。"}, {"text": "三角形", "is_correct": false, "explanation": "语义：圆与三角形相互矛盾，“这个圆的三角形”说不通。"}, {"text": "中心点", "is_correct": true, "explanation": "中心点是圆正中间的那一个点，句子问它在哪里，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“在哪里”问地点，“时间”不能用来提问位置。"}], "explanations": {"颜色": "搭配：“在哪里”问的是位置，“颜色”不能用来问位置。", "三角形": "语义：圆与三角形相互矛盾，“这个圆的三角形”说不通。", "中心点": "中心点是圆正中间的那一个点，句子问它在哪里，符合句意。", "时间": "搭配：“在哪里”问地点，“时间”不能用来提问位置。"}, "sentence_index": 0, "correct_answer": "中心点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在中心点开了一家店。", "explanation": "这里应该用〈市中心〉。中心点是一个点，没有面积，不能用来开店。"}, {"text": "比赛的中心点有十分钟休息。", "explanation": "这里应该用〈中间〉。表示一段时间的正中间要说〈中间〉，“中心点”只指一个点。"}, {"text": "这个广场的中心点很大。", "explanation": "这里应该用〈中心区〉。中心点是一个点，没有大小，不能说“很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是正方形上的点，“正方形的天空”说不通。"}, {"text": "中心点", "is_correct": true, "explanation": "正方形的中心点是正中间的点，位于两条线之间，符合句意。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“在……中间”描述空间位置，“上午”是时间词，不能这样搭配。"}, {"text": "圆", "is_correct": false, "explanation": "语义：正方形与圆相互矛盾，“正方形的圆”说不通。"}], "explanations": {"天空": "语义：天空不是正方形上的点，“正方形的天空”说不通。", "中心点": "正方形的中心点是正中间的点，位于两条线之间，符合句意。", "上午": "搭配：“在……中间”描述空间位置，“上午”是时间词，不能这样搭配。", "圆": "语义：正方形与圆相互矛盾，“正方形的圆”说不通。"}, "sentence_index": 6, "correct_answer": "中心点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用尺子在纸上画了一条中心点。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，如线、路，不能用来数“中心点”。"}, {"text": "桌上放着一朵中心点。", "explanation": "这里应该用〈个〉。“朵”用于花、云等，不用于“中心点”。"}, {"text": "墙上挂着一座中心点。", "explanation": "这里应该用〈个〉。“座”用于山、桥、建筑等大型物，不能用来数“中心点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在纸上画了一只中心点。", "corrected_sentence": "我在纸上画了一个中心点。", "error_description": "错误形式“一只中心点”，正确形式“一个中心点”：“只”常用于动物，不能用来数“中心点”，“中心点”应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈到桌子的中心点摆了一个花瓶。", "corrected_sentence": "妈妈在桌子的中心点摆了一个花瓶。", "error_description": "错误形式“到桌子的中心点摆”，正确形式“在桌子的中心点摆”：表示放置在某处，动词前的地点要用“在”引出；“到”通常放在动词后，如“摆到桌子上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
