INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95023, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像话是说的做的合适，没有错。", "primary_collocate": null, "pronunciation": "xiàng huà", "ipa": "ɕjɑŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "他这样处理问题，做得很像话。", "target_word": "像话", "complexity_tier": "T3", "furigana": "tā zhèyàng chǔlǐ wèntí, zuò de hěn xiànghuà.", "sentence_source": "generated"}, {"text": "你先道歉，再解释，这样才像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说得很像话，我们都同意。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子做完作业再玩，这才像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对客人又热情又有礼貌，这才像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家的意见他都听了，这样处理才像话。", "target_word": "像话", "complexity_tier": "T3", "furigana": "dàjiā de yìjiàn tā dōu tīng le, zhèyàng chǔlǐ cái xiànghuà.", "sentence_source": "generated"}, {"text": "这次比赛他很守规矩，表现得很像话。", "target_word": "像话", "complexity_tier": "T3", "furigana": "zhè cì bǐsài tā hěn shǒu guīju, biǎoxiàn de hěn xiànghuà.", "sentence_source": "generated"}, {"text": "她说的每句话都很像话，大家都服气。", "target_word": "像话", "complexity_tier": "T3", "furigana": "tā shuō de měi jù huà dōu hěn xiànghuà, dàjiā dōu fúqì.", "sentence_source": "generated"}, {"text": "借了别人的东西，按时还回去才像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这次的回答比上次像话多了。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "说话做事合适得体、挑不出错，多作肯定评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3b264aa-b95b-40a2-9864-e252a279c2f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95023, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话（xiàng huà）：说的做的合适、没有错，正是本词的意思。"}, {"text": "讲话", "is_correct": false, "explanation": "讲话（jiǎng huà）与“像话”的声母和声调都不同（j 与 x，第三声与第四声），意思是说话、发言。"}, {"text": "墙画", "is_correct": false, "explanation": "墙画（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是画在墙上的画。"}, {"text": "香花", "is_correct": false, "explanation": "香花（xiāng huā）两个音节的声调都与“像话”不同（第一声与第四声），意思是芳香的花。"}, {"text": "闲话", "is_correct": false, "explanation": "闲话（xián huà）与“像话”的韵母不同（an 与 ang），声调也不同，意思是闲聊或背后议论。"}], "explanations": {"像话": "像话（xiàng huà）：说的做的合适、没有错，正是本词的意思。", "讲话": "讲话（jiǎng huà）与“像话”的声母和声调都不同（j 与 x，第三声与第四声），意思是说话、发言。", "墙画": "墙画（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是画在墙上的画。", "香花": "香花（xiāng huā）两个音节的声调都与“像话”不同（第一声与第四声），意思是芳香的花。", "闲话": "闲话（xián huà）与“像话”的韵母不同（an 与 ang），声调也不同，意思是闲聊或背后议论。"}, "sentence_index": null, "correct_answer": "像话"}, "level_3": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话：说的做的合适、没有错，正符合这里对处理方式的肯定。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，不能用来评价处理问题是否得当。"}, {"text": "好看", "is_correct": false, "explanation": "体貌：“好看”描述外观或样子，不能用来评价处理问题是否合适。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”多形容声音，不说“做得很响亮”来评价处理问题。"}], "explanations": {"像话": "像话：说的做的合适、没有错，正符合这里对处理方式的肯定。", "热闹": "语义：“热闹”形容场面喧闹，不能用来评价处理问题是否得当。", "好看": "体貌：“好看”描述外观或样子，不能用来评价处理问题是否合适。", "响亮": "搭配：“响亮”多形容声音，不说“做得很响亮”来评价处理问题。"}, "sentence_index": 0, "correct_answer": "像话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的装修很像话。", "explanation": "这里应该用〈像样〉。像话用来评价人的言行是否合情理，装修这类物件的质量要说像样。"}, {"text": "这件外套的尺码很像话。", "explanation": "这里应该用〈合适〉。像话只评价人的言行，衣服尺码这类物件要说合适。"}, {"text": "这次他按时完成作业，真不像话。", "explanation": "这里用的是“不像话”的批评义（言行不合情理，表示不满）。句中要表扬他按时完成作业，批评义与语境相反，所以不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95023, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话（xiàng huà）：说的做的合适、没有错，正是本词的意思。"}, {"text": "强化", "is_correct": false, "explanation": "强化（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是加强、巩固。"}, {"text": "量化", "is_correct": false, "explanation": "量化（liàng huà）的声母与“像话”不同（l 与 x），声调相同（第四声），意思是用数量来表示。"}, {"text": "香滑", "is_correct": false, "explanation": "香滑（xiāng huá）两个音节的声调都与“像话”不同，意思是又香又滑，多形容食物。"}], "explanations": {"像话": "像话（xiàng huà）：说的做的合适、没有错，正是本词的意思。", "强化": "强化（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是加强、巩固。", "量化": "量化（liàng huà）的声母与“像话”不同（l 与 x），声调相同（第四声），意思是用数量来表示。", "香滑": "香滑（xiāng huá）两个音节的声调都与“像话”不同，意思是又香又滑，多形容食物。"}, "sentence_index": null, "correct_answer": "像话"}, "level_3": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话：言行合乎规矩、没有错，与“很守规矩”的表现相符。"}, {"text": "散漫", "is_correct": false, "explanation": "语义：“散漫”与前一句“很守规矩”相矛盾，表现得很散漫不能用于此句。"}, {"text": "顽皮", "is_correct": false, "explanation": "语义：“顽皮”指爱闹、不听话，与“很守规矩”相矛盾。"}, {"text": "凶", "is_correct": false, "explanation": "搭配：“表现”后多接“好”“差”“出色”等评价，“凶”不用于这类评价。"}], "explanations": {"像话": "像话：言行合乎规矩、没有错，与“很守规矩”的表现相符。", "散漫": "语义：“散漫”与前一句“很守规矩”相矛盾，表现得很散漫不能用于此句。", "顽皮": "语义：“顽皮”指爱闹、不听话，与“很守规矩”相矛盾。", "凶": "搭配：“表现”后多接“好”“差”“出色”等评价，“凶”不用于这类评价。"}, "sentence_index": 6, "correct_answer": "像话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她今天长得很像话。", "explanation": "这里应该用〈漂亮〉。像话评价言行是否合情理，人的长相好看要说漂亮。"}, {"text": "这座山很像话。", "explanation": "这里应该用〈雄伟〉。像话评价言行是否合情理，山的壮观要说雄伟。"}, {"text": "他的身高很像话，已经超过了爸爸。", "explanation": "这里应该用〈高〉。像话评价言行，身高是身体特征，不能用它，身材高要说高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这次的回答没像话。", "corrected_sentence": "他这次的回答很像话。", "error_description": "副词错误：“像话”作谓语表示评价，应与程度副词“很”搭配，说“很像话”；“没”用于否定动作或已发生的事，不能说“没像话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这次帮忙搬家，做很像话。", "corrected_sentence": "他这次帮忙搬家，做得很像话。", "error_description": "补语错误：表示“做得怎样”要用“做得……”，“得”不能省，应说“做得很像话”，不能说“做很像话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
