INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "言行不合情理，令人不满。", "primary_collocate": null, "pronunciation": "xiàng huà", "ipa": "ɕjɑŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "这么晚了还不回家，像话吗？", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你让老人站着，自己坐着，像话吗？", "target_word": "像话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班总是迟到，真不像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生在课堂上大声打电话，太不像话了。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借了钱不还，还说是我的错，这不像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人还没来，你们就先吃了，像话吗？", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个大人跟小孩抢东西，真不像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对自己的父母那么冷淡，实在不像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人说话你一直打断，这像话吗？", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间乱成这样你都不收拾，不像话！", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不像话", "label": "否定"}], "register": "口语", "sense_fingerprint": "言行不合情理、令人不满，多用于否定式或反问式批评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3b264aa-b95b-40a2-9864-e252a279c2f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话（xiàng huà）：言行不合情理、令人不满，正是本词的意思。"}, {"text": "讲话", "is_correct": false, "explanation": "讲话（jiǎng huà）与“像话”的声母和声调都不同（j 与 x，第三声与第四声），意思是说话、发言。"}, {"text": "墙画", "is_correct": false, "explanation": "墙画（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是画在墙上的画。"}, {"text": "香花", "is_correct": false, "explanation": "香花（xiāng huā）两个音节的声调都与“像话”不同（第一声与第四声），意思是芳香的花。"}, {"text": "闲话", "is_correct": false, "explanation": "闲话（xián huà）与“像话”的韵母不同（an 与 ang），声调也不同，意思是闲聊或背后议论。"}], "explanations": {"像话": "像话（xiàng huà）：言行不合情理、令人不满，正是本词的意思。", "讲话": "讲话（jiǎng huà）与“像话”的声母和声调都不同（j 与 x，第三声与第四声），意思是说话、发言。", "墙画": "墙画（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是画在墙上的画。", "香花": "香花（xiāng huā）两个音节的声调都与“像话”不同（第一声与第四声），意思是芳香的花。", "闲话": "闲话（xián huà）与“像话”的韵母不同（an 与 ang），声调也不同，意思是闲聊或背后议论。"}, "sentence_index": null, "correct_answer": "像话"}, "level_3": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话：言行是否合乎情理，这里用反问来批评，正符合语境。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容味道，与晚归、不回家无关。"}, {"text": "好看", "is_correct": false, "explanation": "体貌：“好看”描述外观，不能用来评价作息和回家的时间。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多用于表演、比赛、故事，不能用来评价晚归的行为。"}], "explanations": {"像话": "像话：言行是否合乎情理，这里用反问来批评，正符合语境。", "好吃": "语义：“好吃”形容味道，与晚归、不回家无关。", "好看": "体貌：“好看”描述外观，不能用来评价作息和回家的时间。", "精彩": "搭配：“精彩”多用于表演、比赛、故事，不能用来评价晚归的行为。"}, "sentence_index": 0, "correct_answer": "像话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生在课堂上大声打电话，这样做很像话。", "explanation": "这里用的是“像话”的表扬义（言行合乎情理、没有错），与句中的批评语境相反，本句要的是批评义。"}, {"text": "他的眼睛很不像话，看东西总是模糊。", "explanation": "这里应该用〈近视〉。像话只用于批评人的言行，视力不好要说近视。"}, {"text": "他的牙齿很不像话，笑起来特别难看。", "explanation": "这里应该用〈整齐〉。像话只用于批评人的言行，牙齿的排列要说整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话（xiàng huà）：言行不合情理、令人不满，正是本词的意思。"}, {"text": "强化", "is_correct": false, "explanation": "强化（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是加强、巩固。"}, {"text": "量化", "is_correct": false, "explanation": "量化（liàng huà）的声母与“像话”不同（l 与 x），声调相同（第四声），意思是用数量来表示。"}, {"text": "香滑", "is_correct": false, "explanation": "香滑（xiāng huá）两个音节的声调都与“像话”不同，意思是又香又滑，多形容食物。"}], "explanations": {"像话": "像话（xiàng huà）：言行不合情理、令人不满，正是本词的意思。", "强化": "强化（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是加强、巩固。", "量化": "量化（liàng huà）的声母与“像话”不同（l 与 x），声调相同（第四声），意思是用数量来表示。", "香滑": "香滑（xiāng huá）两个音节的声调都与“像话”不同，意思是又香又滑，多形容食物。"}, "sentence_index": null, "correct_answer": "像话"}, "level_3": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话：言行不合情理，这里用来批评大人抢小孩东西的行为。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容温度舒适，不能用来评价抢东西的行为。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，与抢东西的行为毫无关系。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”多用于物体或身体，不说人的行为“不结实”。"}], "explanations": {"像话": "像话：言行不合情理，这里用来批评大人抢小孩东西的行为。", "凉快": "语义：“凉快”形容温度舒适，不能用来评价抢东西的行为。", "甜": "语义：“甜”形容味道，与抢东西的行为毫无关系。", "结实": "搭配：“结实”多用于物体或身体，不说人的行为“不结实”。"}, "sentence_index": 6, "correct_answer": "像话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子很不像话，坐在后排也看不清。", "explanation": "这里应该用〈矮〉。像话评价言行，身高等身体特征不能用它，个子矮要说矮。"}, {"text": "他的身体很不像话，每天都去跑步。", "explanation": "这里应该用〈健康〉。像话评价言行是否合情理，身体状况要说健康。"}, {"text": "他的手很不像话，做的木工活很精致。", "explanation": "这里应该用〈巧〉。像话不能评价手的灵巧程度，手艺灵巧要说巧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这样插队，真不像话地。", "corrected_sentence": "他这样插队，真不像话。", "error_description": "词类错误：“不像话”是形容词，后面不加“地”。“地”用于修饰动词的副词，应说“真不像话”，不能说“真不像话地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是乱发脾气，实在像话。", "corrected_sentence": "他总是乱发脾气，实在不像话。", "error_description": "否定词漏掉：“不像话”是批评的说法，漏掉“不”后句子变成表扬，与语境相反，应说“实在不像话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
