INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95045, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外围是最外面的一圈。", "primary_collocate": null, "pronunciation": "wài wéi", "ipa": "waɪ˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "房子的外围有一圈小树。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市外围是大片农田。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球场外围坐满了人。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先在外围走一圈。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园外围有一条小河。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校外围种了很多花。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山的外围很安静。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察守在大楼外围。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖的外围是一条跑步路。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园外围有一道白墙。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外围赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "外围：最外面的一圈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0803c99c-fda8-4e16-9a88-b48c5c697e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外围", "is_correct": true, "explanation": "正确：外围是最外面的一圈，“房子的外围有一圈小树”指房子最外面的一圈有小树。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是房子的一部分，“房子的钢琴”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不能有一圈小树围绕它。"}, {"text": "星期", "is_correct": false, "explanation": "配价：“有”的主语要是处所或事物，“星期”是时间词，不能作“房子的……”的成分。"}], "explanations": {"外围": "正确：外围是最外面的一圈，“房子的外围有一圈小树”指房子最外面的一圈有小树。", "钢琴": "语义：钢琴是乐器，不是房子的一部分，“房子的钢琴”说不通。", "窗户": "语义：窗户是墙上的开口，不能有一圈小树围绕它。", "星期": "配价：“有”的主语要是处所或事物，“星期”是时间词，不能作“房子的……”的成分。"}, "sentence_index": 0, "correct_answer": "外围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先坐在会场的外围，正好是会场的正中间。", "explanation": "这里应该用〈中心〉。外围指最外面的一圈，正中间不能说外围。"}, {"text": "这个工厂的外围有一间办公室，就在生产车间里面。", "explanation": "这里应该用〈内部〉。外围指最外面的一圈，车间里面不能说外围。"}, {"text": "他站在队伍的外围，正好是队伍的中枢位置。", "explanation": "这里应该用〈核心〉。外围指最外面的一圈，中枢位置不能说外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外围", "is_correct": true, "explanation": "正确：外围是最外面的一圈，“这座山的外围很安静”指山的外围一带很安静。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是室内的房间，不是山的一部分，“这座山的厨房”说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室的设备，不能用来描述一座山。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：“很安静”形容地方或声音，不能用来形容鸡蛋。"}], "explanations": {"外围": "正确：外围是最外面的一圈，“这座山的外围很安静”指山的外围一带很安静。", "厨房": "语义：厨房是室内的房间，不是山的一部分，“这座山的厨房”说不通。", "黑板": "语义：黑板是教室的设备，不能用来描述一座山。", "鸡蛋": "搭配：“很安静”形容地方或声音，不能用来形容鸡蛋。"}, "sentence_index": 6, "correct_answer": "外围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题的核心就在花园外围，我们要先弄清楚它。", "explanation": "这里应该用〈中心〉。外围指最外面的一圈，问题的核心不能说在外围。"}, {"text": "花园的外围正好是中央的喷泉。", "explanation": "这里应该用〈中心〉。外围指最外面的一圈，位于正中的喷泉不能说外围。"}, {"text": "我们的房子在花园外围，就在院子最里面。", "explanation": "这里应该用〈内侧〉。外围指最外面的一圈，院子最里面不能说外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只狗院子外围叫个不停。", "corrected_sentence": "那只狗在院子外围叫个不停。", "error_description": "错误：表示处所的“在”漏掉了。正确说法是“在院子外围叫个不停”，“在+处所”要放在动词前，表示动作发生的位置，不能直接说“院子外围叫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们外围进入花园。", "corrected_sentence": "我们从外围进入花园。", "error_description": "错误：表示起点的“从”漏掉了。正确说法是“从外围进入花园”，“从+处所”要引出动作的起点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
