INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某一范围周围的部分；最外面一层。", "primary_collocate": null, "pronunciation": "wài wéi", "ipa": "waɪ˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这个问题先从外围了解。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司外围的工作由我来做。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先看外围的情况。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是队员，只是球队外围的朋友。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外围的人不知道里面的事。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查先从外围开始。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店外围的路很堵。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在人群外围看热闹。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外围的小店生意不错。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只在比赛外围帮忙。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外围赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "外围：某一范围周围的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0803c99c-fda8-4e16-9a88-b48c5c697e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外围", "is_correct": true, "explanation": "正确：外围指某一范围周围的部分，“从外围了解”指从周边的情况入手了解。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是了解问题的途径，“从钢琴了解”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能作为了解问题的途径，“从窗户了解”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“了解”需要表示途径或方面的成分，“厨房”是空间，不能充当。"}], "explanations": {"外围": "正确：外围指某一范围周围的部分，“从外围了解”指从周边的情况入手了解。", "钢琴": "语义：钢琴不是了解问题的途径，“从钢琴了解”说不通。", "窗户": "语义：窗户不能作为了解问题的途径，“从窗户了解”说不通。", "厨房": "配价：“了解”需要表示途径或方面的成分，“厨房”是空间，不能充当。"}, "sentence_index": 0, "correct_answer": "外围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不是队员，他在球队的外围，是球队的核心成员。", "explanation": "这里应该用〈内层〉。外围指周围的一层，核心成员属于内层，不能说在外围。"}, {"text": "他不是队员，他是球队外围的内部人员，在更衣室工作。", "explanation": "这里应该用〈里层〉。外围指周围的部分，在更衣室工作的人员属于里层，不能说外围。"}, {"text": "他不是队员，他在球队外围，是整支球队的正中心。", "explanation": "这里应该用〈中间〉。外围指周围的部分，正中心不能说外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外围", "is_correct": true, "explanation": "正确：外围指某一范围周围的部分，“商店外围的路很堵”指商店周边的路很堵。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不能用来修饰商店周边的路。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室的设备，不能用来修饰商店的路。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“路很堵”描述道路，“星期”是时间词，不能与“路”构成修饰关系。"}], "explanations": {"外围": "正确：外围指某一范围周围的部分，“商店外围的路很堵”指商店周边的路很堵。", "鸡蛋": "语义：鸡蛋是食物，不能用来修饰商店周边的路。", "黑板": "语义：黑板是教室的设备，不能用来修饰商店的路。", "星期": "搭配：“路很堵”描述道路，“星期”是时间词，不能与“路”构成修饰关系。"}, "sentence_index": 6, "correct_answer": "外围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只在比赛的外围，坐在场地的中央发号施令。", "explanation": "这里应该用〈中心〉。外围指周围的部分，场地的中心不能说外围。"}, {"text": "他只在比赛的外围，一直坐在观众席的正中心。", "explanation": "这里应该用〈核心〉。外围指周围的部分，观众席的正中心不能说外围。"}, {"text": "他坐在比赛的外围指挥，正好在球场的正中央。", "explanation": "这里应该用〈中心〉。外围指周围的部分，球场的正中央不能说外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只外围帮忙，不参加正式比赛。", "corrected_sentence": "我只在外围帮忙，不参加正式比赛。", "error_description": "错误：表示处所的“在”漏掉了。正确说法是“在外围帮忙”，“在+处所”要放在动词前面，引出动作发生的处所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们外围开始调查这件事。", "corrected_sentence": "我们从外围开始调查这件事。", "error_description": "错误：表示起点的“从”漏掉了。正确说法是“从外围开始调查”，“从+处所”要引出起点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3596f873-e279-43e7-a9f8-4d9923db7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95051, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "正确：“热闹”与“孤独”构成反义，一个指人多有生气，一个指无人作伴。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”与“孤独”没有反义关系，它描述光线。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”与“孤独”没有反义关系，它描述内容或经验。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”与“孤独”没有反义关系，它描述速度。"}], "correct_answer": "热闹", "explanations": {"热闹": "正确：“热闹”与“孤独”构成反义，一个指人多有生气，一个指无人作伴。", "明亮": "“明亮”与“孤独”没有反义关系，它描述光线。", "丰富": "“丰富”与“孤独”没有反义关系，它描述内容或经验。", "迅速": "“迅速”与“孤独”没有反义关系，它描述速度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
