INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95051, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "孤独是一个人，心里觉得没有人陪。", "primary_collocate": null, "pronunciation": "gū dú", "ipa": "ku˥˥ tu˧˥", "syllable_count": 2, "sentences": [{"text": "他一个人住，觉得很孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了新的城市，我常常感到孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的生活很孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上一个人在家，她有点孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不说话，看起来很孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有朋友的日子真孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不怕孤独，一个人也过得很好。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都走了，家里只剩下孤独的老人。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他孤独地坐在窗边看雨。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国第一年，他觉得特别孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "孤独地", "label": "状语形式"}, {"form": "孤独感", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人，心里觉得没有人陪伴的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05603155-7014-437f-be97-76a86cc3743a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95051, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孤独", "is_correct": true, "explanation": "正确答案：gū dú，指独自一人、缺少陪伴而寂寞。"}, {"text": "古都", "is_correct": false, "explanation": "gǔ（第三声）与 gū（第一声）声调不同，dū（第一声）与 dú（第二声）声调也不同，意思是古代的都城。"}, {"text": "古渡", "is_correct": false, "explanation": "gǔ（第三声）与 gū（第一声）声调不同，dù（第四声）与 dú（第二声）声调也不同，意思是古老的渡口。"}, {"text": "咕嘟", "is_correct": false, "explanation": "gū 相同，dū（第一声）与 dú（第二声）声调不同，形容水沸腾的声音。"}, {"text": "故都", "is_correct": false, "explanation": "gù（第四声）与 gū（第一声）声调不同，dū（第一声）与 dú（第二声）声调也不同，意思是从前的都城。"}], "explanations": {"孤独": "正确答案：gū dú，指独自一人、缺少陪伴而寂寞。", "古都": "gǔ（第三声）与 gū（第一声）声调不同，dū（第一声）与 dú（第二声）声调也不同，意思是古代的都城。", "古渡": "gǔ（第三声）与 gū（第一声）声调不同，dù（第四声）与 dú（第二声）声调也不同，意思是古老的渡口。", "咕嘟": "gū 相同，dū（第一声）与 dú（第二声）声调不同，形容水沸腾的声音。", "故都": "gù（第四声）与 gū（第一声）声调不同，dū（第一声）与 dú（第二声）声调也不同，意思是从前的都城。"}, "sentence_index": null, "correct_answer": "孤独"}, "level_3": {"options": [{"text": "孤独", "is_correct": true, "explanation": "正确：“孤独”形容人的寂寞心情，与“一个人住”及“觉得很”搭配，符合句意。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有声音，与“一个人住”的情境矛盾。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”指事态的程度，与“一个人住”而“觉得很”所指的心情不合。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或眼神，不能用来描述人的内心感受。"}], "explanations": {"孤独": "正确：“孤独”形容人的寂寞心情，与“一个人住”及“觉得很”搭配，符合句意。", "热闹": "语义：“热闹”指人多、有声音，与“一个人住”的情境矛盾。", "严重": "语义：“严重”指事态的程度，与“一个人住”而“觉得很”所指的心情不合。", "明亮": "体貌：“明亮”形容光线或眼神，不能用来描述人的内心感受。"}, "sentence_index": 0, "correct_answer": "孤独"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们没有别的选择，这是孤独的答案。", "explanation": "语义：这里把“孤独”用成了“唯一、单一”的意思，但它只表示心里缺少陪伴的寂寞，不能修饰“答案”。"}, {"text": "这次比赛，他拿到了孤独的第一名。", "explanation": "语义：这里把“孤独”用成了“唯一、单独”的意思，但它只表示心里缺少陪伴的寂寞，不能修饰名次。"}, {"text": "他的孤独很贵。", "explanation": "语义：这里把“孤独”当成了可以论价的东西，但它只表示心里缺少陪伴的感受，不能用“贵”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95051, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "孤独", "is_correct": true, "explanation": "正确答案：gū dú，指独自一人、缺少陪伴而寂寞。"}, {"text": "苦读", "is_correct": false, "explanation": "kǔ（第三声）与 gū（第一声）声母和声调都不同，dú 相同，意思是下苦功学习。"}, {"text": "蛊毒", "is_correct": false, "explanation": "gǔ（第三声）与 gū（第一声）声调不同，dú 相同，意思是用巫术制成的毒。"}, {"text": "酷毒", "is_correct": false, "explanation": "kù（第四声）与 gū（第一声）声母和声调都不同，dú 相同，意思是极其狠毒。"}], "explanations": {"孤独": "正确答案：gū dú，指独自一人、缺少陪伴而寂寞。", "苦读": "kǔ（第三声）与 gū（第一声）声母和声调都不同，dú 相同，意思是下苦功学习。", "蛊毒": "gǔ（第三声）与 gū（第一声）声调不同，dú 相同，意思是用巫术制成的毒。", "酷毒": "kù（第四声）与 gū（第一声）声母和声调都不同，dú 相同，意思是极其狠毒。"}, "sentence_index": null, "correct_answer": "孤独"}, "level_3": {"options": [{"text": "孤独", "is_correct": true, "explanation": "正确：“孤独”形容人的寂寞心情，与“不怕”及“一个人也过得很好”的语境相合。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容待人的态度，不能说“不怕热情”。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”说经济条件，与“一个人也过得很好”没有关联，不能作“不怕”的对象。"}, {"text": "雄伟", "is_correct": false, "explanation": "语义：“雄伟”形容建筑或山川的气势，不能用来描述人的心情。"}], "explanations": {"孤独": "正确：“孤独”形容人的寂寞心情，与“不怕”及“一个人也过得很好”的语境相合。", "热情": "搭配：“热情”形容待人的态度，不能说“不怕热情”。", "富裕": "语义：“富裕”说经济条件，与“一个人也过得很好”没有关联，不能作“不怕”的对象。", "雄伟": "语义：“雄伟”形容建筑或山川的气势，不能用来描述人的心情。"}, "sentence_index": 6, "correct_answer": "孤独"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一瓶孤独，放在书桌上。", "explanation": "量词：“孤独”指心理感受，不能用“瓶”来计量，这里应该用〈种〉，说“一种孤独”。"}, {"text": "这幅画的色彩很孤独，独一无二。", "explanation": "语义：这里把“孤独”用成了“独特”的意思，但它只表示心里缺少陪伴的寂寞，不能用来评价画的色彩。"}, {"text": "这次考试，他交上了一份孤独的答卷。", "explanation": "语义：这里把“孤独”用成了“唯一、单独”的意思，但它只表示心里的寂寞，不能修饰“答卷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一个人在国外生活，显得很的孤独。", "corrected_sentence": "她一个人在国外生活，显得很孤独。", "error_description": "错误：很的孤独。正确：很孤独。程度副词“很”修饰形容词后面不能加“的”，应直接说“很孤独”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
