INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95052, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "正确：“热闹”与“孤独”构成反义，一个指人多有生气，一个指无人作伴。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”与“孤独”没有反义关系，它描述光线。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”与“孤独”没有反义关系，它描述速度。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”与“孤独”没有反义关系，它描述事物显现的程度。"}], "correct_answer": "热闹", "explanations": {"热闹": "正确：“热闹”与“孤独”构成反义，一个指人多有生气，一个指无人作伴。", "明亮": "“明亮”与“孤独”没有反义关系，它描述光线。", "迅速": "“迅速”与“孤独”没有反义关系，它描述速度。", "清晰": "“清晰”与“孤独”没有反义关系，它描述事物显现的程度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
