INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95052, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "独自一人，缺少陪伴而感到寂寞。", "primary_collocate": null, "pronunciation": "gū dú", "ipa": "ku˥˥ tu˧˥", "syllable_count": 2, "sentences": [{"text": "她孤独地走在回家的路上。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个孤独的人。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孤独的孩子没有朋友。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节的时候，他一个人，格外孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写信，是因为心里太孤独了。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤独的时候，我就听音乐。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在山里的老人很孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢孤独，常常找朋友聊天。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸去世后，妈妈变得很孤独。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他孤独了很久，终于有了朋友。", "target_word": "孤独", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "孤独地", "label": "状语形式"}, {"form": "孤独感", "label": "复合"}], "register": "中性", "sense_fingerprint": "独自一人、缺少陪伴而寂寞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05603155-7014-437f-be97-76a86cc3743a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95052, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孤独", "is_correct": true, "explanation": "正确答案：gū dú，指独自一人、缺少陪伴而寂寞。"}, {"text": "古渡", "is_correct": false, "explanation": "gǔ（第三声）与 gū（第一声）声调不同，dù（第四声）与 dú（第二声）声调也不同，意思是古老的渡口。"}, {"text": "故都", "is_correct": false, "explanation": "gù（第四声）与 gū（第一声）声调不同，dū（第一声）与 dú（第二声）声调也不同，意思是从前的都城。"}, {"text": "蛊毒", "is_correct": false, "explanation": "gǔ（第三声）与 gū（第一声）声调不同，dú 相同，意思是用巫术制成的毒。"}, {"text": "咕嘟", "is_correct": false, "explanation": "gū 相同，dú（第二声）与 dū（第一声）声调不同，形容水沸腾的声音。"}], "explanations": {"孤独": "正确答案：gū dú，指独自一人、缺少陪伴而寂寞。", "古渡": "gǔ（第三声）与 gū（第一声）声调不同，dù（第四声）与 dú（第二声）声调也不同，意思是古老的渡口。", "故都": "gù（第四声）与 gū（第一声）声调不同，dū（第一声）与 dú（第二声）声调也不同，意思是从前的都城。", "蛊毒": "gǔ（第三声）与 gū（第一声）声调不同，dú 相同，意思是用巫术制成的毒。", "咕嘟": "gū 相同，dú（第二声）与 dū（第一声）声调不同，形容水沸腾的声音。"}, "sentence_index": null, "correct_answer": "孤独"}, "level_3": {"options": [{"text": "孤独", "is_correct": true, "explanation": "正确：“孤独”形容人独自一人时的心情，与“地走在回家的路上”相合。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”形容空间大，不能用来形容走路的样子。"}, {"text": "富裕", "is_correct": false, "explanation": "搭配：“富裕”说经济条件，不能修饰走路的动作。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：“繁华”形容地方的热闹，不能用来形容一个人走路。"}], "explanations": {"孤独": "正确：“孤独”形容人独自一人时的心情，与“地走在回家的路上”相合。", "宽敞": "语义：“宽敞”形容空间大，不能用来形容走路的样子。", "富裕": "搭配：“富裕”说经济条件，不能修饰走路的动作。", "繁华": "语义：“繁华”形容地方的热闹，不能用来形容一个人走路。"}, "sentence_index": 0, "correct_answer": "孤独"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他没有别的选择，只能选择孤独的答案来完成这道题。", "explanation": "语义：这里把“孤独”用成了“唯一、单一”的意思，但它指独自一人而寂寞，不能用来修饰“答案”。"}, {"text": "他的孤独跑得最快，拿了金牌。", "explanation": "语义：这里把“孤独”当成了可以比快慢的主体，但它只表示心里的寂寞，不能形容速度或名次。"}, {"text": "他收拾了一块孤独，放进了箱子里。", "explanation": "量词：“孤独”指心理感受，不能用“块”来计量，这里应该用〈种〉，说“一种孤独”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95052, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "孤独", "is_correct": true, "explanation": "正确答案：gū dú，指独自一人、缺少陪伴而寂寞。"}, {"text": "古都", "is_correct": false, "explanation": "gǔ（第三声）与 gū（第一声）声调不同，dū（第一声）与 dú（第二声）声调也不同，意思是古代的都城。"}, {"text": "苦度", "is_correct": false, "explanation": "kǔ（第三声）与 gū（第一声）声母和声调都不同，dù（第四声）与 dú（第二声）声调也不同，意思是经历艰苦的日子。"}, {"text": "酷毒", "is_correct": false, "explanation": "kù（第四声）与 gū（第一声）声母和声调都不同，dú 相同，意思是极其狠毒。"}], "explanations": {"孤独": "正确答案：gū dú，指独自一人、缺少陪伴而寂寞。", "古都": "gǔ（第三声）与 gū（第一声）声调不同，dū（第一声）与 dú（第二声）声调也不同，意思是古代的都城。", "苦度": "kǔ（第三声）与 gū（第一声）声母和声调都不同，dù（第四声）与 dú（第二声）声调也不同，意思是经历艰苦的日子。", "酷毒": "kù（第四声）与 gū（第一声）声母和声调都不同，dú 相同，意思是极其狠毒。"}, "sentence_index": null, "correct_answer": "孤独"}, "level_3": {"options": [{"text": "孤独", "is_correct": true, "explanation": "正确：“孤独”形容人的寂寞心情，与“住在山里的老人很”搭配，符合句意。"}, {"text": "丰富", "is_correct": false, "explanation": "搭配：“丰富”修饰内容、经验，不能用来形容老人。"}, {"text": "雄伟", "is_correct": false, "explanation": "语义：“雄伟”形容建筑或山川的气势，不能用来形容老人。"}, {"text": "宽广", "is_correct": false, "explanation": "语义：“宽广”形容空间辽阔，不能用来形容人的状态。"}], "explanations": {"孤独": "正确：“孤独”形容人的寂寞心情，与“住在山里的老人很”搭配，符合句意。", "丰富": "搭配：“丰富”修饰内容、经验，不能用来形容老人。", "雄伟": "语义：“雄伟”形容建筑或山川的气势，不能用来形容老人。", "宽广": "语义：“宽广”形容空间辽阔，不能用来形容人的状态。"}, "sentence_index": 6, "correct_answer": "孤独"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一斤孤独，回家慢慢熬汤。", "explanation": "量词：“孤独”是心理感受，不能用“斤”来计量，这里应该用〈种〉，说“一种孤独”。"}, {"text": "他的孤独很高，连门都进不去。", "explanation": "语义：这里把“孤独”当成了可以测量高矮的东西，但它只表示心里缺少陪伴的寂寞，不能形容高度。"}, {"text": "这个孩子的孤独很厚，一摸就知道。", "explanation": "语义：这里把“孤独”当成了可以触摸、有厚度的东西，但它只表示心里的寂寞，不能形容厚薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一个人坐在窗前，觉得很孤独地。", "corrected_sentence": "她一个人坐在窗前，觉得很孤独。", "error_description": "错误：很孤独地。正确：很孤独。作谓语的形容词后面不加“地”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个老人一个人住在山里，很孤独很。", "corrected_sentence": "这个老人一个人住在山里，很孤独。", "error_description": "错误：很孤独很。正确：很孤独。“很”只能放在形容词前面，句末不能再加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95054, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穷", "is_correct": true, "explanation": "“穷”与“富”相对，指没有钱财，是本义项的反义词。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“富”没有反义关系，高与低、矮相对。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“富”没有反义关系，快与慢相对。"}, {"text": "新", "is_correct": false, "explanation": "“新”与“富”没有反义关系，新与旧相对。"}], "correct_answer": "穷", "explanations": {"穷": "“穷”与“富”相对，指没有钱财，是本义项的反义词。", "高": "“高”与“富”没有反义关系，高与低、矮相对。", "快": "“快”与“富”没有反义关系，快与慢相对。", "新": "“新”与“富”没有反义关系，新与旧相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95054, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穷", "is_correct": true, "explanation": "“穷”与“富”相对，指没有钱财，是本义项的反义词。"}, {"text": "低", "is_correct": false, "explanation": "“低”与“富”没有反义关系，低与高相对。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“富”没有反义关系，慢与快相对。"}, {"text": "旧", "is_correct": false, "explanation": "“旧”与“富”没有反义关系，旧与新相对。"}], "correct_answer": "穷", "explanations": {"穷": "“穷”与“富”相对，指没有钱财，是本义项的反义词。", "低": "“低”与“富”没有反义关系，低与高相对。", "慢": "“慢”与“富”没有反义关系，慢与快相对。", "旧": "“旧”与“富”没有反义关系，旧与新相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95054, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "拥有的财产很多；与“穷”相对。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu˥˩", "syllable_count": 1, "sentences": [{"text": "他家以前很穷，现在很富。", "target_word": "富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子的人都不富。", "target_word": "富", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不是很富，但是过得很快乐。", "target_word": "富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王做生意，十年后就富了。", "target_word": "富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人富，有人穷，这很正常。", "target_word": "富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家比我们家富得多。", "target_word": "富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友家里很富，有三辆车。", "target_word": "富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想只自己富，也想帮别人。", "target_word": "富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想努力工作，早点变富。", "target_word": "富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家很富，路上的车都很新。", "target_word": "富", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "富裕", "label": "复合"}, {"form": "富有", "label": "复合"}], "register": "中性", "sense_fingerprint": "财产多、有钱，与穷相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa43149-2bed-4ace-a420-196d5d97c406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95054, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富", "is_correct": true, "explanation": "富 fù（第四声）是本词，意思是拥有的钱财多。"}, {"text": "福", "is_correct": false, "explanation": "福 fú（第二声）与 fù（第四声）声调不同，意思是福气。"}, {"text": "府", "is_correct": false, "explanation": "府 fǔ（第三声）与 fù 声调不同，意思是官府或住宅。"}, {"text": "户", "is_correct": false, "explanation": "户 hù（第四声）与 fù 声母不同（h 与 f），意思是家庭或户口。"}, {"text": "腐", "is_correct": false, "explanation": "腐 fǔ（第三声）与 fù 声调不同，意思是腐烂。"}, {"text": "扶", "is_correct": false, "explanation": "扶 fú（第二声）与 fù 声调不同，意思是搀扶。"}], "explanations": {"富": "富 fù（第四声）是本词，意思是拥有的钱财多。", "福": "福 fú（第二声）与 fù（第四声）声调不同，意思是福气。", "府": "府 fǔ（第三声）与 fù 声调不同，意思是官府或住宅。", "户": "户 hù（第四声）与 fù 声母不同（h 与 f），意思是家庭或户口。", "腐": "腐 fǔ（第三声）与 fù 声调不同，意思是腐烂。", "扶": "扶 fú（第二声）与 fù 声调不同，意思是搀扶。"}, "sentence_index": null, "correct_answer": "富"}, "level_3": {"options": [{"text": "富", "is_correct": true, "explanation": "“富”与“很穷”相对，表示钱财多，正好接在“现在很”后面。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，与家里的钱财无关。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”形容价格或物品，不能说人家“很贵”。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”指温度，与“穷”的对比毫无关系。"}], "explanations": {"富": "“富”与“很穷”相对，表示钱财多，正好接在“现在很”后面。", "矮": "体貌：“矮”形容身高，与家里的钱财无关。", "贵": "搭配：“贵”形容价格或物品，不能说人家“很贵”。", "冷": "语义：“冷”指温度，与“穷”的对比毫无关系。"}, "sentence_index": 0, "correct_answer": "富"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的内容很富，值得一读。", "explanation": "这里应该用〈丰富〉。富指钱财多，说内容多要用丰富。"}, {"text": "这片土地很富，庄稼长得很好。", "explanation": "这里应该用〈富饶〉。富饶指土地、物产多；富指拥有的财产多，不能用来说土地“富”。"}, {"text": "现在我的时间很富，可以多陪家人。", "explanation": "这里应该用〈充裕〉。充裕指时间、资金够用，富指拥有很多钱，不能形容时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95054, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "富", "is_correct": true, "explanation": "富 fù（第四声）是本词，意思是拥有的钱财多。"}, {"text": "符", "is_correct": false, "explanation": "符 fú（第二声）与 fù（第四声）声调不同，意思是符号。"}, {"text": "服", "is_correct": false, "explanation": "服 fú（第二声）与 fù 声调不同，意思是衣服。"}, {"text": "斧", "is_correct": false, "explanation": "斧 fǔ（第三声）与 fù 声调不同，意思是斧子。"}, {"text": "辅", "is_correct": false, "explanation": "辅 fǔ（第三声）与 fù 声调不同，意思是辅助。"}], "explanations": {"富": "富 fù（第四声）是本词，意思是拥有的钱财多。", "符": "符 fú（第二声）与 fù（第四声）声调不同，意思是符号。", "服": "服 fú（第二声）与 fù 声调不同，意思是衣服。", "斧": "斧 fǔ（第三声）与 fù 声调不同，意思是斧子。", "辅": "辅 fǔ（第三声）与 fù 声调不同，意思是辅助。"}, "sentence_index": null, "correct_answer": "富"}, "level_3": {"options": [{"text": "富", "is_correct": true, "explanation": "“富”指家里钱财多，与“有三辆车”相符。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人的体形，不能说家里很瘦。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指想吃东西，不能用来形容家里。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能用来形容家里的情况。"}], "explanations": {"富": "“富”指家里钱财多，与“有三辆车”相符。", "瘦": "体貌：“瘦”形容人的体形，不能说家里很瘦。", "饿": "语义：“饿”指想吃东西，不能用来形容家里。", "甜": "语义：“甜”指味道，不能用来形容家里的情况。"}, "sentence_index": 6, "correct_answer": "富"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位画家的作品很富，很有想象力。", "explanation": "这里的“富”是“富于”的意思，指想象力丰富，不指钱财多，不能用来形容作品。"}, {"text": "这首歌的旋律很富，听起来很好听。", "explanation": "这里的“富”是“富于变化”的意思，指旋律变化多，与“拥有很多钱财”的义项无关。"}, {"text": "这种蔬菜很富，含有很多铁。", "explanation": "这里的“富”是“富含”的意思，指所含成分多，与本义项“拥有很多钱财”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇这几年富下来了，街上多了很多新店。", "corrected_sentence": "这个小镇这几年富起来了，街上多了很多新店。", "error_description": "补语错误：“富”表示变得有钱，应说“富起来”，不能说“富下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家富很，城市里到处是高楼。", "corrected_sentence": "这个国家很富，城市里到处是高楼。", "error_description": "位置错误：程度副词“很”应放在“富”前面，说“富很”是错误的，正确说法是“很富”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
