INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95059, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "常用是常常会用到。", "primary_collocate": null, "pronunciation": "cháng yòng", "ipa": "ʈʂʰɑŋ˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个词在生活里很常用。", "target_word": "常用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种方法在工作中特别常用。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时，这句话特别常用。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些表达在口语里最常用。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个按钮很常用，所以做得很大。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学校里，这种笔很常用。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，这个公式考试时很常用。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的问法很常用，你要记住。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个功能不太常用，可以放在后面。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字在日常生活中十分常用。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "常用词", "label": "复合"}, {"form": "常用字", "label": "复合"}], "register": "中性", "sense_fingerprint": "常用：常常会用到，作谓语说明事物使用频繁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05603155-7014-437f-be97-76a86cc3743a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95059, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "常用", "is_correct": true, "explanation": "正确答案。常用：常常会用到。"}, {"text": "重用", "is_correct": false, "explanation": "chóng 与 cháng 韵母不同（ong 与 ang），意思是任用、提拔。"}, {"text": "长泳", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是长距离游泳。"}, {"text": "厂用", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂使用的，如厂用电。"}, {"text": "乘用", "is_correct": false, "explanation": "chéng 与 cháng 韵母不同（eng 与 ang），意思是供乘坐用的，如乘用车。"}], "explanations": {"常用": "正确答案。常用：常常会用到。", "重用": "chóng 与 cháng 韵母不同（ong 与 ang），意思是任用、提拔。", "长泳": "yǒng（第三声）与 yòng（第四声）声调不同，意思是长距离游泳。", "厂用": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂使用的，如厂用电。", "乘用": "chéng 与 cháng 韵母不同（eng 与 ang），意思是供乘坐用的，如乘用车。"}, "sentence_index": null, "correct_answer": "常用"}, "level_3": {"options": [{"text": "常用", "is_correct": true, "explanation": "正确。“很”后作谓语，表示这个词经常会用到。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说形状，词不能是圆的。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”说味道，词不能是咸的。"}, {"text": "陡", "is_correct": false, "explanation": "搭配：“陡”用于坡道等，不能说这个词很陡。"}], "explanations": {"常用": "正确。“很”后作谓语，表示这个词经常会用到。", "圆": "语义：“圆”说形状，词不能是圆的。", "咸": "语义：“咸”说味道，词不能是咸的。", "陡": "搭配：“陡”用于坡道等，不能说这个词很陡。"}, "sentence_index": 0, "correct_answer": "常用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种现象在城市里很常用。", "explanation": "这里应该用〈普遍〉。常用说被经常使用，现象在范围内多见要用普遍。"}, {"text": "这种病在农村很常用。", "explanation": "这里应该用〈常见〉。常用指被经常使用，不能用来说病的多见。"}, {"text": "他的生活很常用。", "explanation": "这里应该用〈平常〉。常用不能用来形容生活普通，形容普通要用平常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常用", "is_correct": true, "explanation": "正确。“很”后作谓语，表示这个公式考试时经常会用到。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”说味道，公式不能是辣的。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”说味道，不能说公式很苦。"}, {"text": "哑", "is_correct": false, "explanation": "搭配：“哑”说声音，不能用于公式。"}], "explanations": {"常用": "正确。“很”后作谓语，表示这个公式考试时经常会用到。", "辣": "语义：“辣”说味道，公式不能是辣的。", "苦": "语义：“苦”说味道，不能说公式很苦。", "哑": "搭配：“哑”说声音，不能用于公式。"}, "sentence_index": 6, "correct_answer": "常用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人很常用。", "explanation": "这里不能用〈常用〉，误把它当成“被人经常利用”的意思。常用只说东西常会用到，不用来形容人。"}, {"text": "这片云很常用。", "explanation": "这里不能用〈常用〉，误把它当成“时常出现”的意思。常用只说东西常会用到，不能用于云。"}, {"text": "这阵风很常用。", "explanation": "这里不能用〈常用〉，误把它当成“时常刮起”的意思。常用只说东西常会用到，不能用于风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个词在工作里常用很。", "corrected_sentence": "这个词在工作里常用得很。", "error_description": "错误形式：“常用很”，应为“常用得很”。“常用”后作程度补语要用“得”连接“很”，漏掉“得”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
