INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事后觉得自己做错了而感到懊恼。", "primary_collocate": null, "pronunciation": "hòu huǐ", "ipa": "xoʊ˥˩ xweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我后悔昨天说了那句话。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做错了事，现在很后悔。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她后悔没有早点告诉妈妈。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你会后悔的，别这样做。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试没学好，我真后悔。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他后悔自己骂了朋友。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从来没有后悔过这个决定。", "target_word": "后悔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弄坏了她的书，我很后悔。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说错话以后，他一直很后悔。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他后悔得一晚上没睡。", "target_word": "后悔", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "后悔了", "label": "体标"}, {"form": "后悔过", "label": "体标"}, {"form": "后悔药", "label": "复合"}, {"form": "後悔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事后觉得自己做错而懊恼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a9e6c79-9a64-4e29-86b7-f0772555b1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后悔", "is_correct": true, "explanation": "正确。“后悔”表示事后觉得自己做错而懊恼，与“昨天说了那句话”相合。"}, {"text": "期待", "is_correct": false, "explanation": "语义：“期待”指对将来的事抱有希望，与“昨天”已经发生的事冲突。"}, {"text": "打算", "is_correct": false, "explanation": "语义：“打算”表示对将来的计划，不能用来说已经完成的“昨天说了那句话”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般接食物，不能接“说了那句话”这样的言语行为，句意不通。"}], "explanations": {"后悔": "正确。“后悔”表示事后觉得自己做错而懊恼，与“昨天说了那句话”相合。", "期待": "语义：“期待”指对将来的事抱有希望，与“昨天”已经发生的事冲突。", "打算": "语义：“打算”表示对将来的计划，不能用来说已经完成的“昨天说了那句话”。", "吃": "搭配：“吃”一般接食物，不能接“说了那句话”这样的言语行为，句意不通。"}, "sentence_index": 0, "correct_answer": "后悔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我常常后悔小时候住的那条街。", "explanation": "这里应该用〈怀念〉。后悔指对自己做过的事感到懊恼；对小时候住过的街道应该说怀念。"}, {"text": "我们都后悔这位老人。", "explanation": "这里应该用〈感激〉。后悔指对自己做过的事感到懊恼，对别人的好意要用感激，不能用后悔来表达对人的感谢。"}, {"text": "我很后悔他会游泳。", "explanation": "这里应该用〈羡慕〉。后悔的内容是自己做过的事，对别人的能力要用羡慕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后悔", "is_correct": true, "explanation": "正确。“后悔”表示对做过的决定感到懊恼，与“从来没有……过”搭配。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑或设施，不能接“这个决定”，句意不通。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”是不及物动词，后面不能带“这个决定”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般接食物，不能接“这个决定”。"}], "explanations": {"后悔": "正确。“后悔”表示对做过的决定感到懊恼，与“从来没有……过”搭配。", "拆除": "搭配：“拆除”的对象是建筑或设施，不能接“这个决定”，句意不通。", "出发": "配价：“出发”是不及物动词，后面不能带“这个决定”作宾语。", "吃": "搭配：“吃”一般接食物，不能接“这个决定”。"}, "sentence_index": 6, "correct_answer": "后悔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很后悔明天的考试。", "explanation": "这里应该用〈担心〉。后悔指对已经做过的事感到懊恼，明天的考试还没有发生，只能说担心。"}, {"text": "他很后悔今天的天气。", "explanation": "这里应该用〈喜欢〉。后悔针对自己做过的事，对天气的喜好要说喜欢，不能说后悔今天的天气。"}, {"text": "大家都后悔他的新婚。", "explanation": "这里应该用〈祝福〉。后悔针对自己做过的事，对别人的喜事要用祝福，不能说后悔他的新婚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天说了那句话，现在后悔很。", "corrected_sentence": "我昨天说了那句话，现在后悔得很。", "error_description": "错误：「后悔」后面作程度补语时，要加助词「得」，应说「后悔得很」，不说「后悔很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有后悔了那件事。", "corrected_sentence": "他没有后悔过那件事。", "error_description": "错误：表示否定的经历时，要用「没有……过」，不能用「了」。「过」表示经历，应放在动词「后悔」后面，说「没有后悔过」，不说「没有后悔了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
