INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95067, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "技术学校是教人学做手艺的学校。", "primary_collocate": null, "pronunciation": "jì shù xué xiào", "ipa": "tɕi˥˩ ʂu˥˩ ɕɥe˧˥ ɕjɑʊ̯˥˩", "syllable_count": 4, "sentences": [{"text": "他初中毕业后去技术学校学做菜。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所技术学校教学生修汽车。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在技术学校学了两年电工。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术学校的老师是有二十年经验的师傅。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去技术学校学做衣服。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多想学手艺的年轻人都选择技术学校。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术学校里有很多做木工的工具。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸送我去技术学校，说学手艺不会没饭吃。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在技术学校学会了怎么做面包。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术学校的学生每天都要动手练习做东西。", "target_word": "技术学校", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "技術學校", "label": "繁体"}], "register": "中性", "sense_fingerprint": "技术学校：教人学做手艺（如做菜、修车、木工）的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95067, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术学校", "is_correct": true, "explanation": "正确：“技术学校”是教人学手艺的学校，去那里学做菜合乎句意。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅书籍的地方，不教做菜。"}, {"text": "大学", "is_correct": false, "explanation": "搭配：“初中毕业后”不能直接读大学，大学也不专门教做菜，“去大学学做菜”搭配不当。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，不教人学做菜。"}], "explanations": {"技术学校": "正确：“技术学校”是教人学手艺的学校，去那里学做菜合乎句意。", "图书馆": "语义：图书馆是借阅书籍的地方，不教做菜。", "大学": "搭配：“初中毕业后”不能直接读大学，大学也不专门教做菜，“去大学学做菜”搭配不当。", "医院": "语义：医院是治病的地方，不教人学做菜。"}, "sentence_index": 0, "correct_answer": "技术学校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这家公司的技术学校。", "explanation": "这里应该用〈技术人员〉。技术学校是机构，不能指人；说某人的职业要用“技术人员”。"}, {"text": "这位专家下午在礼堂做了一场技术学校。", "explanation": "这里应该用〈讲座〉。“做一场”搭配讲座、演出等活动；技术学校是机构，不能当作一场活动。"}, {"text": "他每天早上喝一杯技术学校。", "explanation": "这里应该用〈牛奶〉。“喝”的对象是饮品；技术学校是学校，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95067, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术学校", "is_correct": true, "explanation": "正确：“技术学校”是可以放置木工工具的学校场所，符合句意。"}, {"text": "游泳馆", "is_correct": false, "explanation": "语义：游泳馆是供人游泳的场所，不会放很多木工工具。"}, {"text": "电影院", "is_correct": false, "explanation": "语义：电影院是放映电影的场所，不会有很多做木工的工具。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园是饲养和展示动物的地方，不放做木工的工具。"}], "explanations": {"技术学校": "正确：“技术学校”是可以放置木工工具的学校场所，符合句意。", "游泳馆": "语义：游泳馆是供人游泳的场所，不会放很多木工工具。", "电影院": "语义：电影院是放映电影的场所，不会有很多做木工的工具。", "动物园": "语义：动物园是饲养和展示动物的地方，不放做木工的工具。"}, "sentence_index": 6, "correct_answer": "技术学校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在河边钓了一所技术学校。", "explanation": "这里应该用〈鱼〉。“钓”的对象是鱼；技术学校是学校，不能被钓。"}, {"text": "她每天早上煮一个技术学校当早餐。", "explanation": "这里应该用〈鸡蛋〉。“煮”的对象是食物；技术学校是学校，不能煮来吃。"}, {"text": "他在周末洗了一个技术学校。", "explanation": "这里应该用〈汽车〉。“洗”的对象是车、衣物等；技术学校不能洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐在一只技术学校学了三年会计。", "corrected_sentence": "我姐姐在一所技术学校学了三年会计。", "error_description": "量词错误：“只”用于动物，学校应用量词“所”，应说“一所技术学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把技术学校学会了开车。", "corrected_sentence": "他在技术学校学会了开车。", "error_description": "介词误用：“把”不能引出学习的场所，表示学习地点应用“在”，应说“他在技术学校学会了开车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
