INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拥有；拿着。", "primary_collocate": null, "pronunciation": "chí yǒu", "ipa": "ʈʂʰɻ̩˧˥ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他持有这家公司百分之十的股票。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷持有一些很早买的股票。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她持有两家公司的股份。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人持有现金，不敢把钱放进股市。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他持有三套房产，每年收房租。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她持有美国护照，去很多国家不用办签证。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司持有这块地已经二十年了。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他持有过这家公司的股票，后来都卖了。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李持有着公司百分之五的股份，却从不管事。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "持有这种股票的人，今年都赚了不少钱。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "持有着", "label": "着（持续体）"}, {"form": "持有过", "label": "过（经历体）"}, {"form": "持有了", "label": "了（完成体）"}, {"form": "持有者", "label": "复合词"}, {"form": "持有人", "label": "复合词"}], "register": "书面", "sense_fingerprint": "持有：拥有股票、股份、房产、护照等财产或证件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持有", "is_correct": true, "explanation": "正确：“持有”指拥有股份、股票，与“这家公司百分之十的股票”相合。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是遗失，丢了股票就不再是持有，与百分之十的持股描述矛盾。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能搭配股票。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是焚毁，烧掉的股票不再持有，与句子的持股描述相悖。"}], "explanations": {"持有": "正确：“持有”指拥有股份、股票，与“这家公司百分之十的股票”相合。", "丢": "语义：“丢”是遗失，丢了股票就不再是持有，与百分之十的持股描述矛盾。", "喝": "搭配：“喝”的对象是饮品，不能搭配股票。", "烧": "语义：“烧”是焚毁，烧掉的股票不再持有，与句子的持股描述相悖。"}, "sentence_index": 0, "correct_answer": "持有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会上持有了一场演讲。", "explanation": "这里应该用〈发表〉。“发表”搭配演讲、意见；“持有”用于物品、股份、财产。"}, {"text": "她一直持有着微笑。", "explanation": "这里应该用〈保持〉。“保持”搭配状态、微笑；“持有”的对象是物品或财产，不能用于表情。"}, {"text": "他持有了大学。", "explanation": "这里应该用〈进入〉。“进入”表示走进或加入某处；“持有”不能用于机构或地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持有", "is_correct": true, "explanation": "正确：“持有”指长期拥有某块地，可以与“已经二十年了”连用。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能搭配地块，句子说的是持有这块地。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能搭配地块。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”不能搭配地块，句子说的是持有这块地。"}], "explanations": {"持有": "正确：“持有”指长期拥有某块地，可以与“已经二十年了”连用。", "唱": "搭配：“唱”不能搭配地块，句子说的是持有这块地。", "喝": "搭配：“喝”的对象是饮品，不能搭配地块。", "读": "搭配：“读”不能搭配地块，句子说的是持有这块地。"}, "sentence_index": 6, "correct_answer": "持有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目持有很大的潜力。", "explanation": "这里应该用〈具有〉。“持有”指拥有股份、财产或证件；说潜力、特点要用“具有”。"}, {"text": "她持有很强的领导能力。", "explanation": "这里应该用〈具备〉。“具备”指拥有能力或条件，“持有”不用于能力。"}, {"text": "这所大学持有很高的声誉。", "explanation": "这里应该用〈享有〉。“享有”指得到声誉，“持有”用于股份、财产、证件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她以前持有了过这家公司的股份。", "corrected_sentence": "她以前持有过这家公司的股份。", "error_description": "体标叠用：“了”与“过”不能同时使用；表示过去的经历只用“过”，应说“她以前持有过这家公司的股份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直在持有这家公司的股份。", "corrected_sentence": "他一直持有这家公司的股份。", "error_description": "状态动词误用：“持有”是状态动词，不能加“在”表示进行，应说“他一直持有这家公司的股份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
