INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95071, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "据有是占住一个地方，当成自己的。", "primary_collocate": null, "pronunciation": "jù yǒu", "ipa": "tɕy˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他据有这块地已经十年了。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司据有城里最大的一块地。", "target_word": "据有", "complexity_tier": "T3", "furigana": "jù yǒu", "sentence_source": "generated"}, {"text": "那个国王据有整座山谷。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人据有了河边的小城。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居据有了我家门前的空地。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个人据有着山上的树林。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人据有三间大房子。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，大官常常据有很多土地。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个将军据有了山腰上的一座寨子。", "target_word": "据有", "complexity_tier": "T3", "furigana": "jù yǒu", "sentence_source": "generated"}, {"text": "谁据有这座小岛？", "target_word": "据有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "据有了", "label": "体标"}, {"form": "据有着", "label": "体标"}], "register": "书面", "sense_fingerprint": "据有：占住一个地方，当成自己的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05603155-7014-437f-be97-76a86cc3743a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "据有", "is_correct": true, "explanation": "正确。“据有”表示占住这块地，当成自己的。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的宾语是食物，地不能吃。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应为饮料，不能说喝地。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能说穿地。"}], "explanations": {"据有": "正确。“据有”表示占住这块地，当成自己的。", "吃": "语义：“吃”的宾语是食物，地不能吃。", "喝": "搭配：“喝”的宾语应为饮料，不能说喝地。", "穿": "搭配：“穿”的宾语是衣物，不能说穿地。"}, "sentence_index": 0, "correct_answer": "据有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我据有很多朋友。", "explanation": "这里应该用〈拥有〉。据有指占住地方当成自己的，人与人之间的关系不能说据有。"}, {"text": "这件事据有了我一个小时。", "explanation": "这里应该用〈占用〉。据有用于占住地方或地盘，时间不能说据有。"}, {"text": "他据有了一支笔。", "explanation": "这里应该用〈拿〉。据有指占住较大的地方当成自己的，一支笔这样的小东西要说拿到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "据有", "is_correct": true, "explanation": "正确。“据有”表示占住三间房子，当成自己的。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的宾语多是可以移动的东西，房子不能搬。"}, {"text": "扛", "is_correct": false, "explanation": "语义：一个人扛不动三间大房子，与句中条件不合。"}, {"text": "举", "is_correct": false, "explanation": "语义：一个人举不起三间大房子，与“一个人”不合。"}], "explanations": {"据有": "正确。“据有”表示占住三间房子，当成自己的。", "搬": "搭配：“搬”的宾语多是可以移动的东西，房子不能搬。", "扛": "语义：一个人扛不动三间大房子，与句中条件不合。", "举": "语义：一个人举不起三间大房子，与“一个人”不合。"}, "sentence_index": 6, "correct_answer": "据有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我据有一双旧鞋子。", "explanation": "这里不能用〈据有〉，误把它当成“穿着、拥有”的意思。据有指占住地方当成自己的，一双鞋不是占住的地方，不能这样说。"}, {"text": "他据有了一个想法。", "explanation": "这里不能用〈据有〉，误把它当成“产生、想到”的意思。据有只用于占住地方，想法要说想出。"}, {"text": "这个房间据有很多阳光。", "explanation": "这里不能用〈据有〉，误把它当成“充满、包含”的意思。据有指占住地方当成自己的，阳光不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
