INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占有，占据。", "primary_collocate": null, "pronunciation": "jù yǒu", "ipa": "tɕy˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家据有大片肥沃的土地。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们据有这座城市已经三年。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店据有街角最好的位置。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队据有了山上的高地。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人据有着河边所有的码头。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想据有这块地，可是别人不卖。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家大公司据有了一半的市场。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一棵大树据有了院子的中间。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家据有村里最好的水田。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的王常据有大片山林。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "据有了", "label": "体标"}, {"form": "据有着", "label": "体标"}], "register": "书面", "sense_fingerprint": "据有：占有，占据某地或某种位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05603155-7014-437f-be97-76a86cc3743a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_er