INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95075, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "明年是今年过去后的下一年。", "primary_collocate": null, "pronunciation": "míng nián", "ipa": "miŋ˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "明年我想去中国学习汉语。", "target_word": "明年", "sentence_source": "generated"}, {"text": "我哥哥明年就要大学毕业了。", "target_word": "明年", "sentence_source": "generated"}, {"text": "今年太忙了，明年再去旅行吧。", "target_word": "明年", "sentence_source": "generated"}, {"text": "明年夏天，我们全家想去海边玩。", "target_word": "明年", "sentence_source": "generated"}, {"text": "他们打算明年结婚。", "target_word": "明年", "sentence_source": "generated"}, {"text": "这家公司明年会招很多新人。", "target_word": "明年", "sentence_source": "generated"}, {"text": "我的女儿明年上小学。", "target_word": "明年", "sentence_source": "generated"}, {"text": "明年的今天，我们还要一起吃饭。", "target_word": "明年", "sentence_source": "generated"}, {"text": "妹妹说明年她要学开车。", "target_word": "明年", "sentence_source": "generated"}, {"text": "这个房子明年才能盖好。", "target_word": "明年", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "日常说法：今年过去后的下一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d36763-8831-45a5-9b61-1e9a276bb895') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95075, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "明年", "is_correct": true, "explanation": "明年 míngnián 指今年过去后的下一年，是听到的词。"}, {"text": "明天", "is_correct": false, "explanation": "tiān（第一声）与 nián（第二声）的声母与声调都不同（t 与 n；一声与二声），意思是明天。"}, {"text": "明显", "is_correct": false, "explanation": "xiǎn（第三声）与 nián 声母不同（x 与 n），声调也不同，意思是明显。"}, {"text": "平年", "is_correct": false, "explanation": "píng（第二声）与 míng 声母不同（p 与 m），意思是非闰年的普通一年。"}, {"text": "定年", "is_correct": false, "explanation": "dìng（第四声）与 míng 声母不同（d 与 m），声调也不同，意思是规定的退休年龄。"}], "explanations": {"明年": "明年 míngnián 指今年过去后的下一年，是听到的词。", "明天": "tiān（第一声）与 nián（第二声）的声母与声调都不同（t 与 n；一声与二声），意思是明天。", "明显": "xiǎn（第三声）与 nián 声母不同（x 与 n），声调也不同，意思是明显。", "平年": "píng（第二声）与 míng 声母不同（p 与 m），意思是非闰年的普通一年。", "定年": "dìng（第四声）与 míng 声母不同（d 与 m），声调也不同，意思是规定的退休年龄。"}, "sentence_index": null, "correct_answer": "明年"}, "level_3": {"options": [{"text": "明年", "is_correct": true, "explanation": "明年是今年过去后的下一年，与“想去中国学习汉语”的打算相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：昨天已经过去，不能与表示将来打算的“想去”相配。"}, {"text": "上周", "is_correct": false, "explanation": "语义：上周已经过去，与将要去中国学习的计划矛盾。"}, {"text": "每天", "is_correct": false, "explanation": "语义：每天表示经常，不能与一次性的留学计划相配。"}], "explanations": {"明年": "明年是今年过去后的下一年，与“想去中国学习汉语”的打算相符。", "昨天": "语义：昨天已经过去，不能与表示将来打算的“想去”相配。", "上周": "语义：上周已经过去，与将要去中国学习的计划矛盾。", "每天": "语义：每天表示经常，不能与一次性的留学计划相配。"}, "sentence_index": 0, "correct_answer": "明年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试定在明年九点开始。", "explanation": "这里应该用〈明天〉。“明年”指下一个年份，不能与具体的钟点连用。"}, {"text": "他每天明年都去跑步。", "explanation": "这里应该用〈每年〉。“明年”指某一个特定的年份，不能表示经常发生的动作；表示每年都去做要用“每年”。"}, {"text": "我刚才明年到家。", "explanation": "这里应该删去〈明年〉，说“我刚才到家”。“明年”指将来的年份，与“刚才”刚发生的时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明年", "is_correct": true, "explanation": "明年是下一年，女儿在这一年开始上小学，符合句意。"}, {"text": "凌晨", "is_correct": false, "explanation": "搭配：“上小学”指白天按时到校，不与“凌晨”搭配。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：小学不会在半夜上课，与“上小学”的时间不符。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜不是上学的时间，句子无法成立。"}], "explanations": {"明年": "明年是下一年，女儿在这一年开始上小学，符合句意。", "凌晨": "搭配：“上小学”指白天按时到校，不与“凌晨”搭配。", "半夜": "语义：小学不会在半夜上课，与“上小学”的时间不符。", "深夜": "语义：深夜不是上学的时间，句子无法成立。"}, "sentence_index": 6, "correct_answer": "明年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这周我明年要参加考试。", "explanation": "“明年”指下一年，不能与“这周”同时使用，这里应该用〈下周〉。"}, {"text": "我明年半个小时就能到学校。", "explanation": "这里应该用〈一会儿〉。“明年”指一个年份，不能与“半个小时”这样的时段连用；表示很快的将来要用“一会儿”。"}, {"text": "这个房子明年已经盖好。", "explanation": "这里应该用〈去年〉。“明年”指将来的年份，与“已经”表示的已经完成矛盾；说已经完成的事要用过去的年份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明年的要去北京旅游。", "corrected_sentence": "我们明年要去北京旅游。", "error_description": "错误：“明年的要”中多了“的”；正确：“明年要”。“明年”后加“的”再接动词不通顺，应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年了我们去北京学习。", "corrected_sentence": "明年我们去北京学习。", "error_description": "“明年”是时间词，后面不能加“了”。应去掉“了”，说“明年我们去北京学习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
