INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木是树干做成的材料，可以用来做桌子和椅子。", "primary_collocate": null, "pronunciation": "mù", "ipa": "mu˥˩", "syllable_count": 1, "sentences": [{"text": "这张桌子是木的。", "target_word": "木", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家的椅子都是木做的。", "target_word": "木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船是用木做的，不是用铁做的。", "target_word": "木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小碗是木做的，用起来很舒服。", "target_word": "木", "complexity_tier": "T3", "furigana": "zhè gè xiǎo wǎn shì mù zuò de, yòng qǐ lái hěn shū fu", "sentence_source": "generated"}, {"text": "这个盒子是木的，很轻。", "target_word": "木", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喜欢木的玩具，不喜欢塑料的。", "target_word": "木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把勺子是木的，不怕热。", "target_word": "木", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块地板是木的，怕潮湿，也怕火。", "target_word": "木", "complexity_tier": "T3", "furigana": "zhè kuài dì bǎn shì mù de, pà cháo shī, yě pà huǒ", "sentence_source": "generated"}, {"text": "房子的门是木做的，不是铁做的。", "target_word": "木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要买木的，还是买塑料的？", "target_word": "木", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "木头", "label": "复合词"}, {"form": "木材", "label": "复合词"}], "register": "中性", "sense_fingerprint": "木：树干做成的材料，用来做桌子、椅子等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa434ef8-d894-447b-8602-18a3814af4db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95079, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "木", "is_correct": true, "explanation": "木（第四声）：树干做成的材料，正是听到的词。"}, {"text": "母", "is_correct": false, "explanation": "mǔ（第三声）与 mù（第四声）声调不同，意思是母亲。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 mù 声母不同（n/m），意思是愤怒。"}, {"text": "布", "is_correct": false, "explanation": "bù 与 mù 声母不同（b/m），意思是布。"}], "explanations": {"木": "木（第四声）：树干做成的材料，正是听到的词。", "母": "mǔ（第三声）与 mù（第四声）声调不同，意思是母亲。", "怒": "nù 与 mù 声母不同（n/m），意思是愤怒。", "布": "bù 与 mù 声母不同（b/m），意思是布。"}, "sentence_index": null, "correct_answer": "木"}, "level_3": {"options": [{"text": "木", "is_correct": true, "explanation": "木：树干做成的材料，符合“是…的”表示材料。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“是…的”后接材料时，“水”不能做桌子的材料。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，不能用来做桌子。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪没有固定形状，不能用来做桌子。"}], "explanations": {"木": "木：树干做成的材料，符合“是…的”表示材料。", "水": "搭配：“是…的”后接材料时，“水”不能做桌子的材料。", "云": "语义：云是天上的水汽，不能用来做桌子。", "雪": "语义：雪没有固定形状，不能用来做桌子。"}, "sentence_index": 0, "correct_answer": "木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木很好吃。", "explanation": "这里应该用〈肉〉。“木”指树干做成的材料，不能吃，“这块肉很好吃”才对。"}, {"text": "他用木写了一封信。", "explanation": "这里应该用〈笔〉。“木”是材料，不能用来写字，“他用笔写了一封信”才对。"}, {"text": "他穿了一件木，走路很轻松。", "explanation": "这里应该用〈衣服〉。“木”是材料，不能穿在身上，“他穿了一件衣服”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95079, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "木", "is_correct": true, "explanation": "木（第四声）：树干做成的材料，正是听到的词。"}, {"text": "骂", "is_correct": false, "explanation": "mà 与 mù 韵母不同（a/u），意思是骂。"}, {"text": "父", "is_correct": false, "explanation": "fù 与 mù 声母不同（f/m），意思是父亲。"}, {"text": "步", "is_correct": false, "explanation": "bù 与 mù 声母不同（b/m），意思是步。"}, {"text": "度", "is_correct": false, "explanation": "dù 与 mù 声母不同（d/m），意思是程度。"}], "explanations": {"木": "木（第四声）：树干做成的材料，正是听到的词。", "骂": "mà 与 mù 韵母不同（a/u），意思是骂。", "父": "fù 与 mù 声母不同（f/m），意思是父亲。", "步": "bù 与 mù 声母不同（b/m），意思是步。", "度": "dù 与 mù 声母不同（d/m），意思是程度。"}, "sentence_index": null, "correct_answer": "木"}, "level_3": {"options": [{"text": "木", "is_correct": true, "explanation": "木：树干做成的材料，不易导热，符合“不怕热”。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料遇热易软化变形，与“不怕热”矛盾。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸遇热易烧焦，与“不怕热”矛盾。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰遇热会融化，与“不怕热”矛盾。"}], "explanations": {"木": "木：树干做成的材料，不易导热，符合“不怕热”。", "塑料": "语义：塑料遇热易软化变形，与“不怕热”矛盾。", "纸": "语义：纸遇热易烧焦，与“不怕热”矛盾。", "冰": "语义：冰遇热会融化，与“不怕热”矛盾。"}, "sentence_index": 6, "correct_answer": "木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名木，做了很多家具。", "explanation": "这里应该用〈木工〉。“木”是材料名，不能指做木工活的人。"}, {"text": "我喝了一杯木，觉得很解渴。", "explanation": "这里应该用〈水〉。“木”是固体材料，不能喝，“我喝了一杯水”才对。"}, {"text": "山上有一座木，住着一家人。", "explanation": "这里应该用〈木屋〉。“座”用于建筑，“木”是材料，不能用来称量房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这杯木很沉，我们搬不动。", "corrected_sentence": "这块木很沉，我们搬不动。", "error_description": "量词错误：“杯”用于盛装液体的容器，木材成块应用“块”，不能用“杯”称量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一张桌木，很结实。", "corrected_sentence": "这是一张木桌，很结实。", "error_description": "语序错误：“木”修饰“桌”，要放在“桌”前，说“木桌”，不能说“桌木”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95081, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲观", "is_correct": true, "explanation": "正确：“悲观”与“乐观”是反义词，都可以形容人的心态。"}, {"text": "紧张", "is_correct": false, "explanation": "“紧张”形容心理不安，与“乐观”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力，与“乐观”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“乐观”没有反义关系。"}], "correct_answer": "悲观", "explanations": {"悲观": "正确：“悲观”与“乐观”是反义词，都可以形容人的心态。", "紧张": "“紧张”形容心理不安，与“乐观”没有反义关系。", "聪明": "“聪明”形容智力，与“乐观”没有反义关系。", "热情": "“热情”形容待人的态度，与“乐观”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95081, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲观", "is_correct": true, "explanation": "正确：“悲观”与“乐观”是反义词，都可以形容人的心态。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“乐观”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌，与“乐观”没有反义关系。"}, {"text": "幽默", "is_correct": false, "explanation": "“幽默”形容说话风趣，与“乐观”没有反义关系。"}], "correct_answer": "悲观", "explanations": {"悲观": "正确：“悲观”与“乐观”是反义词，都可以形容人的心态。", "安静": "“安静”形容声音或环境，与“乐观”没有反义关系。", "漂亮": "“漂亮”形容外貌，与“乐观”没有反义关系。", "幽默": "“幽默”形容说话风趣，与“乐观”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95081, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "乐观是觉得以后会很好，心里很开心。", "primary_collocate": null, "pronunciation": "lè guān", "ipa": "lɤ˥˩ kwan˥", "syllable_count": 2, "sentences": [{"text": "他总是笑着说，以后会越来越好，真乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶很乐观，每天都开开心心的。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友是个乐观的人，从不为小事难过。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得明天一定更好，所以很乐观。", "target_word": "乐观", "complexity_tier": "T3", "furigana": "lè guān", "sentence_source": "generated"}, {"text": "考试没考好，可他很乐观，觉得下次会更好。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐观的人遇到问题，总是先笑一笑。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生病了，但她一点儿也不难过，还是那么乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想着以后的好日子，整个人乐观又开心。", "target_word": "乐观", "complexity_tier": "T3", "furigana": "lè guān", "sentence_source": "generated"}, {"text": "小明很乐观，什么事都往好处想。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们那么乐观，看着他们，我也高兴起来了。", "target_word": "乐观", "complexity_tier": "T3", "furigana": "lè guān", "sentence_source": "generated"}], "morphological_forms": [{"form": "乐观地", "label": "副词形式"}, {"form": "乐观主义", "label": "复合词"}, {"form": "樂觀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "乐观：性格或心情上觉得以后会更好、心里开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95081, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐观", "is_correct": true, "explanation": "正确：“乐观”形容心态积极、觉得以后会更好，符合“笑着说”的语境。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容神情庄重，与“笑着说”的语境相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来评价说话的态度。"}, {"text": "小气", "is_correct": false, "explanation": "语义：“小气”说对钱财或待人的吝啬，与“以后会越来越好”的语气不合。"}], "explanations": {"乐观": "正确：“乐观”形容心态积极、觉得以后会更好，符合“笑着说”的语境。", "严肃": "语义：“严肃”形容神情庄重，与“笑着说”的语境相反。", "漂亮": "体貌：“漂亮”形容外貌，不能用来评价说话的态度。", "小气": "语义：“小气”说对钱财或待人的吝啬，与“以后会越来越好”的语气不合。"}, "sentence_index": 0, "correct_answer": "乐观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很乐观，一下子就算出了答案。", "explanation": "这里应该用〈聪明〉。“乐观”指觉得以后会好、心里开心，不表示思维敏捷；算出答案要说“聪明”。"}, {"text": "她乐观地洗了三遍碗。", "explanation": "这里应该用〈高兴〉。“乐观”形容的是觉得以后会好的心态，描写洗碗这类动作的心情应说“高兴”。"}, {"text": "这盘菜很乐观，我一口气吃光了。", "explanation": "这里应该用〈好吃〉。“乐观”形容人对以后的看法和心情，不用于评价食物；评价一盘菜应说“好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐观", "is_correct": true, "explanation": "正确：“乐观”形容心态积极，符合“还是那么”与“不难过”的语境。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”与“生病了”的语境相矛盾。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”形容食物，不能用来形容人的心态。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容身材，与心情无关。"}], "explanations": {"乐观": "正确：“乐观”形容心态积极，符合“还是那么”与“不难过”的语境。", "健康": "语义：“健康”与“生病了”的语境相矛盾。", "好吃": "搭配：“好吃”形容食物，不能用来形容人的心态。", "高": "体貌：“高”形容身材，与心情无关。"}, "sentence_index": 6, "correct_answer": "乐观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很乐观，每天第一个到办公室。", "explanation": "这里应该用〈勤快〉。“乐观”指觉得以后会好、心里开心，不表示勤快；每天早到要说“勤快”。"}, {"text": "这次晚会很乐观，我们玩得很开心。", "explanation": "这里应该用〈精彩〉。“乐观”形容人的心态，不能用来评价晚会本身；评价晚会应说“精彩”。"}, {"text": "这个孩子很乐观，从不说谎。", "explanation": "这里应该用〈诚实〉。“乐观”指觉得以后会好、心里开心，不表示诚实；“从不说谎”要说“诚实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对待生活很乐观地，每天都笑呵呵的。", "corrected_sentence": "她对待生活很乐观，每天都笑呵呵的。", "error_description": "错误形式：“很乐观地，”；正确形式：“很乐观，”。“乐观”作谓语时后面不加“地”；“地”只用于修饰后面的动词，如“很乐观地面对生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听了这个好消息，他也乐观下来了。", "corrected_sentence": "听了这个好消息，他也乐观起来了。", "error_description": "错误形式：“乐观下来”；正确形式：“乐观起来”。表示开始变得乐观要用趋向补语“起来”，“下来”不能这样用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95082, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲观", "is_correct": true, "explanation": "正确：“悲观”与“乐观”是反义词，都指对事情发展的看法。"}, {"text": "紧张", "is_correct": false, "explanation": "“紧张”形容心理不安，与“乐观”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力，与“乐观”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“乐观”没有反义关系。"}], "correct_answer": "悲观", "explanations": {"悲观": "正确：“悲观”与“乐观”是反义词，都指对事情发展的看法。", "紧张": "“紧张”形容心理不安，与“乐观”没有反义关系。", "聪明": "“聪明”形容智力，与“乐观”没有反义关系。", "热情": "“热情”形容待人的态度，与“乐观”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95082, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲观", "is_correct": true, "explanation": "正确：“悲观”与“乐观”是反义词，都指对事情发展的看法。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“乐观”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌，与“乐观”没有反义关系。"}, {"text": "幽默", "is_correct": false, "explanation": "“幽默”形容说话风趣，与“乐观”没有反义关系。"}], "correct_answer": "悲观", "explanations": {"悲观": "正确：“悲观”与“乐观”是反义词，都指对事情发展的看法。", "安静": "“安静”形容声音或环境，与“乐观”没有反义关系。", "漂亮": "“漂亮”形容外貌，与“乐观”没有反义关系。", "幽默": "“幽默”形容说话风趣，与“乐观”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95082, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对事物的发展抱有积极的看法，充满信心。", "primary_collocate": null, "pronunciation": "lè guān", "ipa": "lɤ˥˩ kwan˥", "syllable_count": 2, "sentences": [{"text": "医生对他的病情很乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家对明年的经济比较乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这次比赛的结果很乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然遇到了困难，他对比赛的结果还是很乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司老板对新产品的销量十分乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件事，大家都不太乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能太乐观，后面还有很多事要做。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的未来一直很乐观，从不害怕。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到数据变好了，经理乐观起来了。", "target_word": "乐观", "complexity_tier": "T3", "furigana": "lè guān", "sentence_source": "generated"}, {"text": "看天气这么差，大家对明天的活动不乐观。", "target_word": "乐观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乐观地", "label": "副词形式"}, {"form": "乐观主义", "label": "复合词"}, {"form": "樂觀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "乐观：对事情的发展和结果抱有积极看法、充满信心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐观", "is_correct": true, "explanation": "正确：“乐观”指对病情的发展抱有积极看法，符合句意。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容对人的态度，不说对病情热情。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容食物的味道，与医生谈病情的语境不合。"}, {"text": "牛", "is_correct": false, "explanation": "语域：“牛”是口语俚语，不适合医生谈病情的正式语境。"}], "explanations": {"乐观": "正确：“乐观”指对病情的发展抱有积极看法，符合句意。", "热情": "搭配：“热情”形容对人的态度，不说对病情热情。", "好吃": "语义：“好吃”形容食物的味道，与医生谈病情的语境不合。", "牛": "语域：“牛”是口语俚语，不适合医生谈病情的正式语境。"}, "sentence_index": 0, "correct_answer": "乐观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行已经结束了，我对整个安排很乐观。", "explanation": "这里应该用〈满意〉。旅行已经结束，应当用“满意”评价整体安排；“乐观”只用于对尚未发生或仍在发展中的事情的看法。"}, {"text": "他乐观地吃了三碗饭。", "explanation": "这里应该用〈高兴〉。“乐观”指对事情发展的积极看法，不描写吃饭时的心情，应说“高高兴兴地吃”。"}, {"text": "我对这把椅子很乐观。", "explanation": "这里应该用〈舒服〉。“乐观”针对事情的发展，椅子没有发展过程；评价椅子应说“舒服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐观", "is_correct": true, "explanation": "正确：“乐观”指对事情过于看好，这里说“不能太乐观”，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，与“后面还有很多事要做”的语境无关。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄，不能用来说做事的态度。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写体形，与做事的语境不合。"}], "explanations": {"乐观": "正确：“乐观”指对事情过于看好，这里说“不能太乐观”，符合句意。", "漂亮": "体貌：“漂亮”形容外貌，与“后面还有很多事要做”的语境无关。", "年轻": "语义：“年轻”说年龄，不能用来说做事的态度。", "胖": "体貌：“胖”描写体形，与做事的语境不合。"}, "sentence_index": 6, "correct_answer": "乐观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很乐观，每次都抢着付钱。", "explanation": "这里应该用〈大方〉。“乐观”指对事情发展的积极看法，不表示慷慨；抢着付钱要说“大方”。"}, {"text": "这块蛋糕很乐观，大家都爱吃。", "explanation": "这里应该用〈好吃〉。“乐观”针对事情的发展，不能用来评价食物；评价蛋糕应说“好吃”。"}, {"text": "这场马拉松很乐观，他跑完了全程。", "explanation": "这里应该用〈艰苦〉。“乐观”说对事情发展的看法，不能用来形容比赛本身；形容比赛的艰辛应说“艰苦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把前景很乐观。", "corrected_sentence": "我对前景很乐观。", "error_description": "错误形式：“把前景很乐观”；正确形式：“对前景很乐观”。“乐观”作谓语时，前面引出对象一般用介词“对”，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们对明年的市场地乐观。", "corrected_sentence": "他们对明年的市场很乐观。", "error_description": "结构助词误用：“地”不能直接放在谓语形容词“乐观”之前，“地”用于修饰后面的动词。此处可用程度副词“很”修饰，说“很乐观”，不能说“地乐观”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
