INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "欠是拿了别人的东西，还没还。", "primary_collocate": null, "pronunciation": "qiàn", "ipa": "tɕʰjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "我欠他一百块钱。", "target_word": "欠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他欠了朋友很多钱，还没还。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你欠我的书，什么时候还？", "target_word": "欠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我欠同学一本书，明天还他。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他欠过房租，后来都还了。", "target_word": "欠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我欠哥哥两百块，下个月还。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别欠别人的东西，要快点还。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她欠我一杯咖啡。", "target_word": "欠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "欠了钱就要还，这是应该的。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他欠着银行的钱，每个月还一点。", "target_word": "欠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欠了", "label": "体标"}, {"form": "欠过", "label": "体标"}, {"form": "欠着", "label": "体标"}, {"form": "欠钱", "label": "复合"}, {"form": "欠债", "label": "复合"}], "register": "中性", "sense_fingerprint": "欠：拿了别人的钱或东西，还没有归还", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa434ef8-d894-447b-8602-18a3814af4db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95083, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "欠", "is_correct": true, "explanation": "qiàn：拿了别人的钱或东西还没还，正是听到的词。"}, {"text": "千", "is_correct": false, "explanation": "qiān（第一声）与 qiàn（第四声）声调不同，意思是一千。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 qiàn（第四声）声调不同，意思是钱。"}, {"text": "件", "is_correct": false, "explanation": "jiàn 与 qiàn 声母不同（j/q），意思是件（量词）。"}, {"text": "线", "is_correct": false, "explanation": "xiàn 与 qiàn 声母不同（x/q），意思是线。"}, {"text": "浅", "is_correct": false, "explanation": "qiǎn（第三声）与 qiàn（第四声）声调不同，意思是浅。"}], "explanations": {"欠": "qiàn：拿了别人的钱或东西还没还，正是听到的词。", "千": "qiān（第一声）与 qiàn（第四声）声调不同，意思是一千。", "钱": "qián（第二声）与 qiàn（第四声）声调不同，意思是钱。", "件": "jiàn 与 qiàn 声母不同（j/q），意思是件（量词）。", "线": "xiàn 与 qiàn 声母不同（x/q），意思是线。", "浅": "qiǎn（第三声）与 qiàn（第四声）声调不同，意思是浅。"}, "sentence_index": null, "correct_answer": "欠"}, "level_3": {"options": [{"text": "欠", "is_correct": true, "explanation": "欠：拿了他的钱没有归还，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞咽食物，“吃他一百块钱”说不通。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责备，不能用来表示拿了别人的钱，句意不通。"}, {"text": "谢", "is_correct": false, "explanation": "配价：“谢”只能带人作宾语，不能再接“一百块钱”。"}], "explanations": {"欠": "欠：拿了他的钱没有归还，符合句意。", "吃": "语义：“吃”指吞咽食物，“吃他一百块钱”说不通。", "骂": "语义：“骂”是责备，不能用来表示拿了别人的钱，句意不通。", "谢": "配价：“谢”只能带人作宾语，不能再接“一百块钱”。"}, "sentence_index": 0, "correct_answer": "欠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书欠给他，他很高兴。", "explanation": "这里应该用〈给〉。“欠”指欠着别人的东西没还，把书交给别人要用“给”，不能说“欠给”。"}, {"text": "他把桌子欠到了墙角。", "explanation": "这里应该用〈挪〉。“欠”表示欠债或欠缺，不表示搬动，应说“把桌子挪到墙角”。"}, {"text": "她欠着头，走出了教室。", "explanation": "这里应该用〈低〉。“欠”没有“低头”的意思，应说“她低着头，走出了教室。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95083, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "欠", "is_correct": true, "explanation": "qiàn：拿了别人的钱或东西还没还，正是听到的词。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 qiàn（第四声）声调不同，意思是前面。"}, {"text": "签", "is_correct": false, "explanation": "qiān（第一声）与 qiàn（第四声）声调不同，意思是签（名）。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 qiàn 声母不同（j/q），意思是看见。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 qiàn 声母不同（x/q），意思是现在。"}], "explanations": {"欠": "qiàn：拿了别人的钱或东西还没还，正是听到的词。", "前": "qián（第二声）与 qiàn（第四声）声调不同，意思是前面。", "签": "qiān（第一声）与 qiàn（第四声）声调不同，意思是签（名）。", "见": "jiàn 与 qiàn 声母不同（j/q），意思是看见。", "现": "xiàn 与 qiàn 声母不同（x/q），意思是现在。"}, "sentence_index": null, "correct_answer": "欠"}, "level_3": {"options": [{"text": "欠", "is_correct": true, "explanation": "欠：没有归还的钱或东西，符合“要快点还”。"}, {"text": "送", "is_correct": false, "explanation": "语义：送出去的东西不需要归还，与“要快点还”矛盾。"}, {"text": "卖", "is_correct": false, "explanation": "语义：卖出去的东西不能再还，与“要快点还”矛盾。"}, {"text": "催", "is_correct": false, "explanation": "搭配：“催”不接“东西”作宾语，应说“催人”或“催事”。"}], "explanations": {"欠": "欠：没有归还的钱或东西，符合“要快点还”。", "送": "语义：送出去的东西不需要归还，与“要快点还”矛盾。", "卖": "语义：卖出去的东西不能再还，与“要快点还”矛盾。", "催": "搭配：“催”不接“东西”作宾语，应说“催人”或“催事”。"}, "sentence_index": 6, "correct_answer": "欠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他欠了我一阵风。", "explanation": "这里应该用〈吹〉。“欠”指欠着别人的东西没还，风不能被欠，应说“吹了一阵风”。"}, {"text": "他把钱欠到银行里了。", "explanation": "这里应该用〈存〉。“欠”指欠着别人的钱没还，把钱放进银行要说〈存〉，不能说“欠到”。"}, {"text": "她欠了一份工作。", "explanation": "这里应该用〈得到〉。“欠”指欠了别人的东西还没还，找到工作是获得，不能说“欠”，应说“得到一份工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他欠我两根钱，一直没还。", "corrected_sentence": "他欠我两块钱，一直没还。", "error_description": "量词错误：“钱”应用“块”称量，“根”用于细长的东西，不能用来称量钱。正确说法是“两块钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前欠了过他很多钱。", "corrected_sentence": "我以前欠过他很多钱。", "error_description": "体标错误：“了”和“过”不能同时用在同一个动词后，表示曾经欠过只用“欠过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
