INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被外国占领并统治、掠夺的地区。", "primary_collocate": null, "pronunciation": "zhí mín dì", "ipa": "ʈʂɻ̩˧˥ min˧˥ ti˥˩", "syllable_count": 3, "sentences": [{"text": "他们占领小岛，把它变成殖民地。", "target_word": "殖民地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把殖民地的矿都运走了。", "target_word": "殖民地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殖民地的农民生活很苦。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王派军队去管理殖民地。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书讲殖民地的历史。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "殖民地的人要给外国交很多税。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一百年前，这里是殖民地。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "殖民者在殖民地建了很多港口。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "殖民地人民开始反对外国统治。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束后，殖民地变成了独立国家。", "target_word": "殖民地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "半殖民地", "label": "复合"}], "register": "书面", "sense_fingerprint": "被外国占领统治掠夺的地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a9e6c79-9a64-4e29-86b7-f0772555b1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殖民地", "is_correct": true, "explanation": "正确。“变成殖民地”指小岛被外国占领统治，与句意相合。"}, {"text": "老师", "is_correct": false, "explanation": "语义：小岛不能变成人，“把它变成老师”句意不通。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“变成”后要接由小岛转化而来的事物，“乐器”不能这样搭配。"}, {"text": "饭", "is_correct": false, "explanation": "语义：小岛不能变成饭，句意不通。"}], "explanations": {"殖民地": "正确。“变成殖民地”指小岛被外国占领统治，与句意相合。", "老师": "语义：小岛不能变成人，“把它变成老师”句意不通。", "乐器": "搭配：“变成”后要接由小岛转化而来的事物，“乐器”不能这样搭配。", "饭": "语义：小岛不能变成饭，句意不通。"}, "sentence_index": 0, "correct_answer": "殖民地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国王派军队去管理一条殖民地。", "explanation": "这里应该用〈块〉。殖民地是一片地区，“条”用于细长的东西，不能用来计量殖民地。"}, {"text": "殖民地在田里工作。", "explanation": "这里应该用〈农民〉。殖民地是地区，不能做“工作”这样的动作；做工的人要说农民。"}, {"text": "殖民地保卫这座城市。", "explanation": "这里应该用〈士兵〉。殖民地是地区，不能保卫城市；保卫城市的是士兵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殖民地", "is_correct": true, "explanation": "正确。“一百年前，这里是殖民地”指这里曾被外国统治，与句意相合。"}, {"text": "学生", "is_correct": false, "explanation": "语义：这里是地方，不能是人，“这里是学生”句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：这里不能是一部手机，句意不通。"}, {"text": "大衣", "is_correct": false, "explanation": "搭配：“这里是”后面接的应是地点或场所类名词，“大衣”不能这样搭配。"}], "explanations": {"殖民地": "正确。“一百年前，这里是殖民地”指这里曾被外国统治，与句意相合。", "学生": "语义：这里是地方，不能是人，“这里是学生”句意不通。", "手机": "语义：这里不能是一部手机，句意不通。", "大衣": "搭配：“这里是”后面接的应是地点或场所类名词，“大衣”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "殖民地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "殖民地很认真地读书。", "explanation": "这里应该用〈学生〉。殖民地是地区，不能读书；读书的是学生。"}, {"text": "殖民地在公园里散步。", "explanation": "这里应该用〈老人〉。殖民地是地区，不能散步；散步的是人，应说老人。"}, {"text": "殖民地写了一本好书。", "explanation": "这里应该用〈作家〉。殖民地不能写书，写书的人是作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们殖民地运走了粮食。", "corrected_sentence": "他们从殖民地运走了粮食。", "error_description": "“殖民地”作动作的起点时，前面要加介词“从”，应说“从殖民地运走”，不能省略“从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条殖民地很大。", "corrected_sentence": "那片殖民地很大。", "error_description": "“殖民地”的量词应用“片”，不能用“条”；“条”用于细长的东西，地区要用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
