INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95089, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "泡是把东西放在水里一会儿。", "primary_collocate": null, "pronunciation": "pào", "ipa": "pʰau⁵¹", "syllable_count": 1, "sentences": [{"text": "先把豆子泡一个晚上。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这块布泡一下。", "target_word": "泡", "complexity_tier": "T3", "furigana": "wǒ xiǎng bǎ zhè kuài bù pào yí xià", "sentence_source": "generated"}, {"text": "他把脚泡在热水里，很舒服。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米要先泡一会儿再煮。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把脏衣服泡在水里。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把衣服泡了一晚上。", "target_word": "泡", "complexity_tier": "T3", "furigana": "tā bǎ yī fu pào le yì wǎn shang", "sentence_source": "generated"}, {"text": "他每晚睡前都泡脚。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些红枣要泡半个小时。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把银耳泡在温水里。", "target_word": "泡", "complexity_tier": "T3", "furigana": "tā bǎ yín ěr pào zài wēn shuǐ lǐ", "sentence_source": "generated"}, {"text": "水太烫了，别泡太久。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "泡了", "label": "体标"}, {"form": "泡着", "label": "体标"}, {"form": "泡过", "label": "体标"}, {"form": "泡一泡", "label": "重叠"}, {"form": "泡茶", "label": "复合"}, {"form": "泡脚", "label": "复合"}], "register": "口语", "sense_fingerprint": "把东西放在水里泡一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95089, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "泡", "is_correct": true, "explanation": "泡（pào）：把东西放在水里浸一段时间。"}, {"text": "跑", "is_correct": false, "explanation": "跑（pǎo，第三声）与 pào（第四声）声调不同，意思是跑步。"}, {"text": "抱", "is_correct": false, "explanation": "抱（bào）与 pào 声母不同（b / p），意思是拥抱。"}, {"text": "报", "is_correct": false, "explanation": "报（bào）与 pào 声母不同（b / p），意思是报纸或报告。"}, {"text": "抛", "is_correct": false, "explanation": "抛（pāo，第一声）与 pào（第四声）声调不同，意思是抛掷。"}], "explanations": {"泡": "泡（pào）：把东西放在水里浸一段时间。", "跑": "跑（pǎo，第三声）与 pào（第四声）声调不同，意思是跑步。", "抱": "抱（bào）与 pào 声母不同（b / p），意思是拥抱。", "报": "报（bào）与 pào 声母不同（b / p），意思是报纸或报告。", "抛": "抛（pāo，第一声）与 pào（第四声）声调不同，意思是抛掷。"}, "sentence_index": null, "correct_answer": "泡"}, "level_3": {"options": [{"text": "泡", "is_correct": true, "explanation": "“泡”在此表示把豆子浸在水里一段时间，与“先把豆子泡一个晚上”的语境相符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”表示移动位置，不能指把豆子浸在水里。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指把东西分开，不能与“一个晚上”这样的时段搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示抛掷，不能指把豆子放在水里过夜。"}], "explanations": {"泡": "“泡”在此表示把豆子浸在水里一段时间，与“先把豆子泡一个晚上”的语境相符。", "搬": "语义：“搬”表示移动位置，不能指把豆子浸在水里。", "切": "搭配：“切”指把东西分开，不能与“一个晚上”这样的时段搭配。", "扔": "语义：“扔”表示抛掷，不能指把豆子放在水里过夜。"}, "sentence_index": 0, "correct_answer": "泡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在阳台上泡太阳，很舒服。", "explanation": "这里应该用〈晒〉。“泡”指把东西浸在水里，不能说“泡太阳”，晒太阳要用“晒”。"}, {"text": "他用湿布把桌子泡干净了。", "explanation": "这里应该用〈擦〉。“泡”是浸在水里，不能用来清洁桌子，擦桌子要用“擦”。"}, {"text": "这块面包要泡得很脆才好吃。", "explanation": "这里应该用〈烤〉。“泡”会使食物变软，不能让面包变脆，要做脆面包应用“烤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95089, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "泡", "is_correct": true, "explanation": "泡（pào）：把东西放在水里浸一段时间。"}, {"text": "胖", "is_correct": false, "explanation": "胖（pàng）与 pào 韵母不同（ang / ao），意思是胖。"}, {"text": "盼", "is_correct": false, "explanation": "盼（pàn）与 pào 韵母不同（an / ao），意思是盼望。"}, {"text": "袍", "is_correct": false, "explanation": "袍（páo，第二声）与 pào（第四声）声调不同，意思是长袍。"}, {"text": "刨", "is_correct": false, "explanation": "刨（bào）与 pào 声母不同（b / p），意思是用刨子削平。"}], "explanations": {"泡": "泡（pào）：把东西放在水里浸一段时间。", "胖": "胖（pàng）与 pào 韵母不同（ang / ao），意思是胖。", "盼": "盼（pàn）与 pào 韵母不同（an / ao），意思是盼望。", "袍": "袍（páo，第二声）与 pào（第四声）声调不同，意思是长袍。", "刨": "刨（bào）与 pào 声母不同（b / p），意思是用刨子削平。"}, "sentence_index": null, "correct_answer": "泡"}, "level_3": {"options": [{"text": "泡", "is_correct": true, "explanation": "“泡”在此表示把脚浸在水里，与“每晚睡前都泡脚”的日常习惯相符。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”的常见对象是头发、指甲，不说“剪脚”。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用力切断，与睡前的日常护理动作不符。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打，不能表示把脚浸在水里。"}], "explanations": {"泡": "“泡”在此表示把脚浸在水里，与“每晚睡前都泡脚”的日常习惯相符。", "剪": "搭配：“剪”的常见对象是头发、指甲，不说“剪脚”。", "砍": "语义：“砍”指用力切断，与睡前的日常护理动作不符。", "踢": "语义：“踢”是用脚击打，不能表示把脚浸在水里。"}, "sentence_index": 6, "correct_answer": "泡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鸡蛋要泡十分钟才能熟。", "explanation": "这里应该用〈煮〉。“泡”只是把东西浸在水里，不能把鸡蛋泡熟，煮鸡蛋要用“煮”。"}, {"text": "馒头要泡二十分钟才熟。", "explanation": "这里应该用〈蒸〉。“泡”不能使馒头变熟，蒸馒头要用“蒸”。"}, {"text": "鱼要泡五分钟才熟。", "explanation": "这里应该用〈煎〉。“泡”不能使鱼熟，煎鱼要用“煎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上都脚泡，很舒服。", "corrected_sentence": "我每天晚上都泡脚，很舒服。", "error_description": "错误形式：“脚泡”；正确形式：“泡脚”。“泡脚”是动宾结构，宾语放在动词后；“脚泡”的语序不成立（宾语前置需用“把”，如“把脚泡在热水里”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把衣服泡了干净了。", "corrected_sentence": "他把衣服泡干净了。", "error_description": "错误形式：“他把衣服泡了干净了”；正确形式：“他把衣服泡干净了”。动词“泡”与结果补语“干净”之间不能插入“了”，多余的这个“了”应删去，句末的“了”保留。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
