INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95090, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西浸在液体中。", "primary_collocate": null, "pronunciation": "pào", "ipa": "pʰau⁵¹", "syllable_count": 1, "sentences": [{"text": "爷爷把杨梅泡在白酒里。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把面包泡在牛奶里吃。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服要泡在洗衣液里半小时。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手泡在冷水里，不那么疼了。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在浴缸里泡了半个小时。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶酒里泡着很多枸杞。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把脏碗泡在洗洁精水里，更好洗。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢把饼干泡在咖啡里吃。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋泡在醋里，壳会变软。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把种子泡在水里一晚上。", "target_word": "泡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "泡了", "label": "体标"}, {"form": "泡着", "label": "体标"}, {"form": "泡过", "label": "体标"}, {"form": "泡一泡", "label": "重叠"}, {"form": "泡酒", "label": "复合"}], "register": "口语", "sense_fingerprint": "把东西浸在酒、牛奶等液体里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95090, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "泡", "is_correct": true, "explanation": "泡（pào）：把东西浸在液体里。"}, {"text": "跑", "is_correct": false, "explanation": "跑（pǎo，第三声）与 pào（第四声）声调不同，意思是跑步。"}, {"text": "抱", "is_correct": false, "explanation": "抱（bào）与 pào 声母不同（b / p），意思是拥抱。"}, {"text": "报", "is_correct": false, "explanation": "报（bào）与 pào 声母不同（b / p），意思是报纸或报告。"}, {"text": "抛", "is_correct": false, "explanation": "抛（pāo，第一声）与 pào（第四声）声调不同，意思是抛掷。"}], "explanations": {"泡": "泡（pào）：把东西浸在液体里。", "跑": "跑（pǎo，第三声）与 pào（第四声）声调不同，意思是跑步。", "抱": "抱（bào）与 pào 声母不同（b / p），意思是拥抱。", "报": "报（bào）与 pào 声母不同（b / p），意思是报纸或报告。", "抛": "抛（pāo，第一声）与 pào（第四声）声调不同，意思是抛掷。"}, "sentence_index": null, "correct_answer": "泡"}, "level_3": {"options": [{"text": "泡", "is_correct": true, "explanation": "“泡”在此表示把杨梅浸在白酒里，与“把杨梅泡在白酒里”的做法相符。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”表示把东西分开，不能表示把杨梅浸在酒里。"}, {"text": "削", "is_correct": false, "explanation": "语义：“削”指去掉外皮，与“泡在白酒里”的做法不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗在白酒里”不成立，白酒不是用来清洗的液体。"}], "explanations": {"泡": "“泡”在此表示把杨梅浸在白酒里，与“把杨梅泡在白酒里”的做法相符。", "切": "语义：“切”表示把东西分开，不能表示把杨梅浸在酒里。", "削": "语义：“削”指去掉外皮，与“泡在白酒里”的做法不符。", "洗": "搭配：“洗在白酒里”不成立，白酒不是用来清洗的液体。"}, "sentence_index": 0, "correct_answer": "泡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天在窗边泡太阳，很舒服。", "explanation": "这里应该用〈晒〉。“泡”指浸在液体中，不能说“泡太阳”，晒太阳要用“晒”。"}, {"text": "他把地板泡得很干净。", "explanation": "这里应该用〈扫〉。“泡”是浸在液体中，不能用来清洁地板，扫地板要用“扫”。"}, {"text": "我用湿布把窗户泡干净了。", "explanation": "这里应该用〈擦〉。“泡”指浸在液体中，不能用来清洁窗户，擦窗户要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95090, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "泡", "is_correct": true, "explanation": "泡（pào）：把东西浸在液体里。"}, {"text": "胖", "is_correct": false, "explanation": "胖（pàng）与 pào 韵母不同（ang / ao），意思是胖。"}, {"text": "盼", "is_correct": false, "explanation": "盼（pàn）与 pào 韵母不同（an / ao），意思是盼望。"}, {"text": "袍", "is_correct": false, "explanation": "袍（páo，第二声）与 pào（第四声）声调不同，意思是长袍。"}, {"text": "刨", "is_correct": false, "explanation": "刨（bào）与 pào 声母不同（b / p），意思是用刨子削平。"}], "explanations": {"泡": "泡（pào）：把东西浸在液体里。", "胖": "胖（pàng）与 pào 韵母不同（ang / ao），意思是胖。", "盼": "盼（pàn）与 pào 韵母不同（an / ao），意思是盼望。", "袍": "袍（páo，第二声）与 pào（第四声）声调不同，意思是长袍。", "刨": "刨（bào）与 pào 声母不同（b / p），意思是用刨子削平。"}, "sentence_index": null, "correct_answer": "泡"}, "level_3": {"options": [{"text": "泡", "is_correct": true, "explanation": "“泡”在此表示把碗浸在洗洁精水里，使碗更好洗，与语境相符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”指猛击，不能表示把碗放进水里。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒”表示把东西从容器中倒出，与“放在水里”的动作不符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是表面，不说“擦在水里”。"}], "explanations": {"泡": "“泡”在此表示把碗浸在洗洁精水里，使碗更好洗，与语境相符。", "砸": "语义：“砸”指猛击，不能表示把碗放进水里。", "倒": "语义：“倒”表示把东西从容器中倒出，与“放在水里”的动作不符。", "擦": "搭配：“擦”的对象是表面，不说“擦在水里”。"}, "sentence_index": 6, "correct_answer": "泡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面包要泡十分钟才熟。", "explanation": "这里应该用〈烤〉。“泡”不能使面包变熟，烤面包要用“烤”。"}, {"text": "鸡翅要泡十分钟才熟。", "explanation": "这里应该用〈炸〉。“泡”不能使鸡翅变熟，炸鸡翅要用“炸”。"}, {"text": "青菜要泡两分钟才熟。", "explanation": "这里应该用〈炒〉。“泡”不能使青菜炒熟，炒菜要用“炒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天都把燕麦泡了在牛奶里。", "corrected_sentence": "妈妈每天都把燕麦泡在牛奶里。", "error_description": "错误形式：“泡了在牛奶里”；正确形式：“泡在牛奶里”。“了”不能插在动词“泡”与介词短语“在牛奶里”之间；完成态的“了”应放在句末，如“泡在牛奶里了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把手软泡了。", "corrected_sentence": "他把手泡软了。", "error_description": "“软”是结果补语，应放在动词“泡”之后，说“泡软”，不能放在动词前说“软泡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
