INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95097, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "爽是觉得很舒服，很痛快。", "primary_collocate": null, "pronunciation": "shuǎng", "ipa": "ʂwaŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "赢了比赛，大家心里都很爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步洗个热水澡，真爽！", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试考完了，今天玩得真爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把话说出来，心里一下子爽了。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，我爽极了。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板今天请客，同事们吃得很爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打完游戏，他觉得特别爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "终于说出心里话，他觉得很爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末睡到自然醒，真是太爽了！", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一口气把作业写完，我爽了一整天。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爽快", "label": "复合"}], "register": "口语", "sense_fingerprint": "心里觉得舒服痛快、很满足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d36763-8831-45a5-9b61-1e9a276bb895') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95097, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爽", "is_correct": true, "explanation": "爽 shuǎng 指心里或身体舒服痛快，是听到的词。"}, {"text": "双", "is_correct": false, "explanation": "shuāng（第一声）与 shuǎng 只有声调不同，意思是两个、成对。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng（第三声）与 shuǎng 少了介音 u，意思是欣赏或奖赏。"}, {"text": "耍", "is_correct": false, "explanation": "shuǎ（第三声）与 shuǎng 少了韵尾 ng，意思是玩耍。"}], "explanations": {"爽": "爽 shuǎng 指心里或身体舒服痛快，是听到的词。", "双": "shuāng（第一声）与 shuǎng 只有声调不同，意思是两个、成对。", "赏": "shǎng（第三声）与 shuǎng 少了介音 u，意思是欣赏或奖赏。", "耍": "shuǎ（第三声）与 shuǎng 少了韵尾 ng，意思是玩耍。"}, "sentence_index": null, "correct_answer": "爽"}, "level_3": {"options": [{"text": "爽", "is_correct": true, "explanation": "爽表示心里舒服痛快，符合赢得比赛后大家的心情。"}, {"text": "难受", "is_correct": false, "explanation": "语义：难受是不舒服的感觉，与赢了比赛的心情相反。"}, {"text": "郁闷", "is_correct": false, "explanation": "语义：郁闷表示心情压抑，不能与赢了比赛后的心情相配。"}, {"text": "慌", "is_correct": false, "explanation": "搭配：“慌”表示慌张，与赢得比赛后大家“都很”的心情不搭配。"}], "explanations": {"爽": "爽表示心里舒服痛快，符合赢得比赛后大家的心情。", "难受": "语义：难受是不舒服的感觉，与赢了比赛的心情相反。", "郁闷": "语义：郁闷表示心情压抑，不能与赢了比赛后的心情相配。", "慌": "搭配：“慌”表示慌张，与赢得比赛后大家“都很”的心情不搭配。"}, "sentence_index": 0, "correct_answer": "爽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨晚发烧了一夜，今天浑身都觉得爽。", "explanation": "这里应该用〈难受〉。“爽”表示舒服痛快，与发烧后浑身不适的感觉正好相反。"}, {"text": "他摔了一跤，疼得直叫，心里却觉得很爽。", "explanation": "这里应该用〈痛苦〉。“爽”表示舒服痛快，与摔跤后疼得直叫的感受矛盾。"}, {"text": "他的手指被门夹破了，一碰就觉得很爽。", "explanation": "这里应该用〈疼〉。“爽”表示舒服痛快，与手指夹破后一碰就疼的感受正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95097, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爽", "is_correct": true, "explanation": "爽 shuǎng 指心里或身体舒服痛快，是听到的词。"}, {"text": "霜", "is_correct": false, "explanation": "shuāng（第一声）与 shuǎng 只有声调不同，意思是霜。"}, {"text": "刷", "is_correct": false, "explanation": "shuā（第一声）与 shuǎng 少了韵尾 ng，意思是刷子或刷牙。"}, {"text": "上", "is_correct": false, "explanation": "shàng（第四声）与 shuǎng 少了介音 u，声调也不同，意思是上面。"}], "explanations": {"爽": "爽 shuǎng 指心里或身体舒服痛快，是听到的词。", "霜": "shuāng（第一声）与 shuǎng 只有声调不同，意思是霜。", "刷": "shuā（第一声）与 shuǎng 少了韵尾 ng，意思是刷子或刷牙。", "上": "shàng（第四声）与 shuǎng 少了介音 u，声调也不同，意思是上面。"}, "sentence_index": null, "correct_answer": "爽"}, "level_3": {"options": [{"text": "爽", "is_correct": true, "explanation": "爽表示心里舒服痛快，符合打完游戏后的感觉。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“饱”指吃得足，不能用来形容打完游戏后的感觉。"}, {"text": "撑", "is_correct": false, "explanation": "搭配：“撑”形容吃得过多的胀感，与打完游戏不搭配。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”指温度低，与打完游戏后的感觉不符。"}], "explanations": {"爽": "爽表示心里舒服痛快，符合打完游戏后的感觉。", "饱": "搭配：“饱”指吃得足，不能用来形容打完游戏后的感觉。", "撑": "搭配：“撑”形容吃得过多的胀感，与打完游戏不搭配。", "凉": "语义：“凉”指温度低，与打完游戏后的感觉不符。"}, "sentence_index": 6, "correct_answer": "爽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大冬天里他冻得直发抖，觉得很爽。", "explanation": "这里应该用〈难受〉。“爽”表示舒服痛快，与冻得直发抖的感受相反。"}, {"text": "他被蚊子咬了一夜，全身又痒又肿，却觉得很爽。", "explanation": "这里应该用〈难受〉。“爽”表示舒服痛快，与被蚊子咬后又痒又肿的感觉相反。"}, {"text": "刚打完针，胳膊又酸又疼，他却觉得很爽。", "explanation": "这里应该用〈不舒服〉。“爽”表示舒服痛快，与打针后胳膊酸痛的感受相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到这个好消息，他爽的跳了起来。", "corrected_sentence": "听到这个好消息，他爽得跳了起来。", "error_description": "“爽”后面带动作补语时要用“得”，不能用“的”。应说“爽得跳了起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运动完洗个澡，我整个人都觉得爽很。", "corrected_sentence": "运动完洗个澡，我整个人都觉得很爽。", "error_description": "“很”是程度副词，应放在形容词“爽”前面，不能放在后面。应说“觉得很爽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
