INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95098, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "清凉，舒服；痛快。", "primary_collocate": null, "pronunciation": "shuǎng", "ipa": "ʂwaŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "夏天喝冰水，又凉又爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹在脸上，感觉好爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里开了空调，一进来就觉得爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冲个冷水澡，浑身都爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的风吹在身上，特别爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热天吃一块冰西瓜，真爽！", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在树下乘凉，微风吹着，很爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完脸，用凉毛巾一擦，好爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泳池里的水不冷不热，游起来很爽。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大热天里喝冰啤酒，爽得很。", "target_word": "爽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凉爽", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体感到清凉舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d36763-8831-45a5-9b61-1e9a276bb895') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95098, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爽", "is_correct": true, "explanation": "爽 shuǎng 指身体感到清凉舒服，是听到的词。"}, {"text": "霜", "is_correct": false, "explanation": "shuāng（第一声）与 shuǎng 只有声调不同，意思是霜。"}, {"text": "刷", "is_correct": false, "explanation": "shuā（第一声）与 shuǎng 少了韵尾 ng，意思是刷子或刷牙。"}, {"text": "上", "is_correct": false, "explanation": "shàng（第四声）与 shuǎng 少了介音 u，声调也不同，意思是上面。"}], "explanations": {"爽": "爽 shuǎng 指身体感到清凉舒服，是听到的词。", "霜": "shuāng（第一声）与 shuǎng 只有声调不同，意思是霜。", "刷": "shuā（第一声）与 shuǎng 少了韵尾 ng，意思是刷子或刷牙。", "上": "shàng（第四声）与 shuǎng 少了介音 u，声调也不同，意思是上面。"}, "sentence_index": null, "correct_answer": "爽"}, "level_3": {"options": [{"text": "爽", "is_correct": true, "explanation": "爽表示身体清凉舒服，与“又凉又爽”的描述相符。"}, {"text": "热", "is_correct": false, "explanation": "语义：“热”与“凉”相反，不能与“又凉又”并列。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”形容温度过高，不与“冰水”搭配。"}, {"text": "闷", "is_correct": false, "explanation": "语义：“闷”表示空气不流通、不舒畅，与冰水的清凉感不符。"}], "explanations": {"爽": "爽表示身体清凉舒服，与“又凉又爽”的描述相符。", "热": "语义：“热”与“凉”相反，不能与“又凉又”并列。", "烫": "搭配：“烫”形容温度过高，不与“冰水”搭配。", "闷": "语义：“闷”表示空气不流通、不舒畅，与冰水的清凉感不符。"}, "sentence_index": 0, "correct_answer": "爽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子又闷又热，他觉得浑身特别爽。", "explanation": "这里应该用〈难受〉。“爽”指清凉舒服，与又闷又热的感觉正好相反。"}, {"text": "大热天里喝一口热汤，他觉得很爽。", "explanation": "这里应该用〈烫〉。“爽”指清凉舒服，热汤带来的是灼热的烫感，不能用“爽”。"}, {"text": "这双新鞋把脚磨出了血，他却觉得很爽。", "explanation": "这里应该用〈痛苦〉。“爽”指清凉舒服，与脚磨出血的疼痛感受相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95098, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爽", "is_correct": true, "explanation": "爽 shuǎng 指身体感到清凉舒服，是听到的词。"}, {"text": "双", "is_correct": false, "explanation": "shuāng（第一声）与 shuǎng 只有声调不同，意思是两个、成对。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng（第三声）与 shuǎng 少了介音 u，意思是欣赏或奖赏。"}, {"text": "耍", "is_correct": false, "explanation": "shuǎ（第三声）与 shuǎng 少了韵尾 ng，意思是玩耍。"}], "explanations": {"爽": "爽 shuǎng 指身体感到清凉舒服，是听到的词。", "双": "shuāng（第一声）与 shuǎng 只有声调不同，意思是两个、成对。", "赏": "shǎng（第三声）与 shuǎng 少了介音 u，意思是欣赏或奖赏。", "耍": "shuǎ（第三声）与 shuǎng 少了韵尾 ng，意思是玩耍。"}, "sentence_index": null, "correct_answer": "爽"}, "level_3": {"options": [{"text": "爽", "is_correct": true, "explanation": "爽表示身体清凉舒服，与树下乘凉、微风吹拂的感觉相符。"}, {"text": "烦", "is_correct": false, "explanation": "语义：“烦”指心里不痛快，与乘凉时身体的清凉感不符。"}, {"text": "燥", "is_correct": false, "explanation": "搭配：“燥”指干而不湿润，不与“微风吹着”搭配。"}, {"text": "腻", "is_correct": false, "explanation": "语义：“腻”指油腻或黏滞，与乘凉的清凉感不符。"}], "explanations": {"爽": "爽表示身体清凉舒服，与树下乘凉、微风吹拂的感觉相符。", "烦": "语义：“烦”指心里不痛快，与乘凉时身体的清凉感不符。", "燥": "搭配：“燥”指干而不湿润，不与“微风吹着”搭配。", "腻": "语义：“腻”指油腻或黏滞，与乘凉的清凉感不符。"}, "sentence_index": 6, "correct_answer": "爽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大冬天里围着厚围巾，他却觉得浑身很爽。", "explanation": "这里应该用〈暖和〉。“爽”指清凉舒服，冬天围厚围巾的温暖感不能说“爽”。"}, {"text": "夏天的午后，他坐在火炉旁，觉得浑身很爽。", "explanation": "这里应该用〈燥热〉。“爽”指清凉舒服，靠近火炉的感觉是燥热，不是爽。"}, {"text": "一口热水下去，他的喉咙又烫又痛，却觉得很爽。", "explanation": "这里应该用〈不舒服〉。“爽”指清凉舒服，喝下热水后喉咙烫痛，与“爽”的感受相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的风吹在身上，爽很。", "corrected_sentence": "夏天的风吹在身上，爽得很。", "error_description": "错误：“爽很”；正确：“爽得很”。“爽”后面带补语“很”时，要用“得”引出补语，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吹了一晚上风扇，我爽地不得了。", "corrected_sentence": "吹了一晚上风扇，我爽得不得了。", "error_description": "“爽”后面带补语时要用“得”，不能用“地”。应说“爽得不得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
